#[cfg(feature = "kernel")]
struct RootRingProducerGuard<'a> {
    slot: &'a DriverTaskCommandSlot,
    tracked: bool,
}

#[cfg(feature = "kernel")]
impl Drop for RootRingProducerGuard<'_> {
    fn drop(&mut self) {
        if self.tracked {
            self.slot.root_ring_writers.fetch_sub(1, Ordering::AcqRel);
        }
    }
}

#[cfg(feature = "kernel")]
fn acquire_root_ring_producer<'a>(
    contract: DriverTaskContract,
    slot: &'a DriverTaskCommandSlot,
) -> Option<RootRingProducerGuard<'a>> {
    if contract != SDIO_HOST_DRIVER_TASK_CONTRACT {
        return Some(RootRingProducerGuard {
            slot,
            tracked: false,
        });
    }
    if slot.ring_producer.load(Ordering::Acquire) != SDIO_RING_PRODUCER_ROOT_BOOTSTRAP {
        return None;
    }
    slot.root_ring_writers.fetch_add(1, Ordering::AcqRel);
    if slot.ring_producer.load(Ordering::Acquire) != SDIO_RING_PRODUCER_ROOT_BOOTSTRAP {
        slot.root_ring_writers.fetch_sub(1, Ordering::AcqRel);
        return None;
    }
    Some(RootRingProducerGuard {
        slot,
        tracked: true,
    })
}

#[cfg(feature = "kernel")]
struct McsNonblockingRootProducerGuard<'a> {
    slot: &'a DriverTaskCommandSlot,
    contract: DriverTaskContract,
    tracked: bool,
}

const MCS_PRODUCER_DRAIN_UNREPORTED: u32 = 0;
const MCS_PRODUCER_DRAIN_ROOT_OBSERVED: u32 = 1;
const MCS_PRODUCER_DRAIN_CONTAINMENT_RESUMED: u32 = 2;

#[cfg(feature = "kernel")]
impl Drop for McsNonblockingRootProducerGuard<'_> {
    fn drop(&mut self) {
        if !self.tracked {
            return;
        }
        let prior = self
            .slot
            .mcs_nonblocking_root_producers
            .fetch_sub(1, Ordering::AcqRel);
        if prior == 1
            && self.slot.mcs_command_admission_open.load(Ordering::Acquire) == 0
            && self
                .slot
                .mcs_producer_drain_reported
                .compare_exchange(
                    MCS_PRODUCER_DRAIN_UNREPORTED,
                    MCS_PRODUCER_DRAIN_ROOT_OBSERVED,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .is_ok()
        {
            let mut line = heapless::String::<192>::new();
            let _ = core::fmt::write(
                &mut line,
                format_args!(
                    "DRIVER_TASK_COMMAND_DRAIN schema=v1 contract={} state=drained active=0 phase={} generation={}",
                    self.contract.name,
                    self.slot.mcs_call_phase.load(Ordering::Acquire),
                    self.slot.mcs_cap_generation.load(Ordering::Acquire),
                ),
            );
            crate::bootstrap::log::force_uart_line_raw_without_prompt_refresh(line.as_str());
        }
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_mcs_nonblocking_root_producer_requires_tracking(
    kernel_mcs: bool,
    cap_generation: u32,
    bounded_send: bool,
) -> bool {
    kernel_mcs && cap_generation != 0 && bounded_send
}

#[cfg(feature = "kernel")]
fn acquire_mcs_nonblocking_root_producer<'a>(
    contract: DriverTaskContract,
    slot: &'a DriverTaskCommandSlot,
    mode: DriverTaskRingCommandMode,
) -> Option<McsNonblockingRootProducerGuard<'a>> {
    let tracked = driver_task_mcs_nonblocking_root_producer_requires_tracking(
        cfg!(sel4_config_kernel_mcs),
        slot.mcs_cap_generation.load(Ordering::Acquire),
        driver_task_ring_mode_uses_bounded_send(mode),
    );
    if !tracked {
        return Some(McsNonblockingRootProducerGuard {
            slot,
            contract,
            tracked: false,
        });
    }
    if slot.mcs_command_admission_open.load(Ordering::Acquire) == 0 {
        return None;
    }
    slot.mcs_nonblocking_root_producers
        .fetch_add(1, Ordering::AcqRel);
    if slot.mcs_command_admission_open.load(Ordering::Acquire) == 0 {
        slot.mcs_nonblocking_root_producers
            .fetch_sub(1, Ordering::AcqRel);
        return None;
    }
    Some(McsNonblockingRootProducerGuard {
        slot,
        contract,
        tracked: true,
    })
}

#[cfg(feature = "kernel")]
fn mcs_nonblocking_root_producer_allows_send(
    slot: &DriverTaskCommandSlot,
    endpoint: usize,
) -> bool {
    slot.mcs_cap_generation.load(Ordering::Acquire) == 0
        || (slot.mcs_command_admission_open.load(Ordering::Acquire) != 0
            && slot.endpoint.load(Ordering::Acquire) == endpoint)
}

#[cfg(feature = "kernel")]
fn driver_task_counter_add(cell: &AtomicUsize, value: usize) {
    if value == 0 {
        return;
    }
    let _ = cell.fetch_add(value, Ordering::Relaxed);
}

#[cfg(feature = "kernel")]
fn driver_task_record_cache_clean(slot: &DriverTaskCommandSlot, bytes: usize) {
    driver_task_counter_add(&slot.counters.cache_clean_ops, 1);
    driver_task_counter_add(&slot.counters.cache_clean_bytes, bytes);
}

#[cfg(feature = "kernel")]
fn driver_task_record_completion_counters(
    slot: &DriverTaskCommandSlot,
    completion: DriverTaskCompletionRecord,
) {
    driver_task_counter_add(&slot.counters.completed_turns, 1);
    if completion.code == DriverTaskCompletionCode::Idle.as_u16() {
        driver_task_counter_add(&slot.counters.idle_turns, 1);
    } else if completion.code == DriverTaskCompletionCode::Fault.as_u16() {
        driver_task_counter_add(&slot.counters.fault_turns, 1);
    } else if completion.code == DriverTaskCompletionCode::BudgetExhausted.as_u16() {
        driver_task_counter_add(&slot.counters.budget_exhausted_turns, 1);
        driver_task_counter_add(&slot.counters.overruns, 1);
    } else if completion.code == DriverTaskCompletionCode::FrameReady.as_u16() {
        driver_task_counter_add(&slot.counters.frame_ready_turns, 1);
        driver_task_counter_add(&slot.counters.descriptors_drained, 1);
        driver_task_counter_add(&slot.counters.rx_frames, 1);
        driver_task_counter_add(&slot.counters.rx_bytes, usize::from(completion.frame.len));
    }
}

#[cfg(feature = "kernel")]
fn driver_task_staging_segments_bytes(segments: &[DriverTaskStagingSegment<'_>]) -> usize {
    segments.iter().fold(0usize, |total, segment| {
        total.saturating_add(match segment {
            DriverTaskStagingSegment::Ring { payload, .. }
            | DriverTaskStagingSegment::RuntimeInit { payload }
            | DriverTaskStagingSegment::Shared { payload, .. } => payload.len(),
        })
    })
}

