#[cfg(feature = "kernel")]
fn record_driver_task_ring_progress(
    slot: &DriverTaskCommandSlot,
    progress: DriverTaskRingProgressRecord,
) {
    if progress.magic != DRIVER_RUNTIME_RING_PROGRESS_MAGIC
        && slot.last_progress_magic.load(Ordering::Acquire) == DRIVER_RUNTIME_RING_PROGRESS_MAGIC
    {
        return;
    }
    slot.last_progress_magic
        .store(progress.magic, Ordering::Release);
    slot.last_progress_sequence
        .store(progress.sequence, Ordering::Release);
    slot.last_progress_phase
        .store(progress.phase, Ordering::Release);
    slot.last_progress_aux0
        .store(progress.aux0, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn driver_task_ring_progress_matches_request(
    progress: DriverTaskRingProgressRecord,
    request: u32,
    aux0: u32,
) -> bool {
    progress.magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC
        && progress.sequence == request
        && driver_task_ring_progress_route_matches(progress.phase, progress.aux0, aux0)
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_root_grant_phase(phase: u32) -> bool {
    matches!(
        phase,
        DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_WAIT_BEGIN
            | DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_READY
            | DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_REJECTED
            | DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_ACCEPTED
            | DRIVER_RUNTIME_RING_PROGRESS_ROOT_GRANT_ACK_FAILED
    )
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_progress_route_matches(
    phase: u32,
    observed_aux0: u32,
    expected_aux0: u32,
) -> bool {
    observed_aux0 == expected_aux0
        || (expected_aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
            && driver_task_ring_root_grant_phase(phase))
}

#[cfg(feature = "kernel")]
const fn cyw43_sdio_pair_restart_progress(progress: DriverTaskRingProgressRecord) -> bool {
    // The owner may escalate after the foreground sequence has already been
    // abandoned. Match the authenticated ABI marker/phase/route, not the old
    // sequence, so an active CYW43 ring cannot hide the restart request.
    progress.magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC
        && progress.phase == DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_PAIR_RESTART_REQUIRED
        && progress.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
}

#[cfg(feature = "kernel")]
fn record_first_cyw43_sdio_pair_restart_cause(cause: Cyw43SdioPairRestartCause) {
    let _ = CYW43_SDIO_PAIR_RESTART_FIRST_CAUSE.compare_exchange(
        0,
        cause as u32,
        Ordering::AcqRel,
        Ordering::Acquire,
    );
}

#[cfg(feature = "kernel")]
fn latch_cyw43_sdio_pair_restart_request(cause: Cyw43SdioPairRestartCause) {
    latch_cyw43_sdio_pair_restart_request_with_runtime_source(cause, 0);
}

#[cfg(feature = "kernel")]
fn latch_cyw43_sdio_pair_restart_request_with_runtime_source(
    cause: Cyw43SdioPairRestartCause,
    runtime_recovery_source_line: u32,
) {
    record_first_cyw43_sdio_pair_restart_cause(cause);
    capture_first_cyw43_recovery_scheduler_snapshot_with_runtime_source(
        runtime_recovery_source_line,
    );
    clear_cyw43_sdio_cold_bootstrap_epoch_token();
    if CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) != 0 {
        CYW43_SDIO_PAIR_RESTART_SUPERSEDED.store(1, Ordering::Release);
    }
    CYW43_SDIO_PAIR_RESTART_PENDING.store(1, Ordering::Release);
}

/// Return whether one stable runtime queue level proves that the current
/// linked CYW43/SDIO lifetime must enter the existing pair-recovery lane.
///
/// The queue's sequence-last commit is the durable fault condition. The DPC
/// owner epoch and retained restart contexts bind it to the one live physical
/// pair; neither a notification nor aggregate diagnostic counters can create
/// recovery authority.
#[cfg(feature = "kernel")]
fn cyw43_sdio_pair_restart_required_from_rx_queue(
    queue_state: Option<DriverRuntimeCyw43RxQueueState>,
    dpc_ring: Option<DriverTaskSdioDpcRingSnapshot>,
    restart_context_available: bool,
) -> bool {
    restart_context_available
        && queue_state.is_some_and(|queue| {
            queue.poisoned()
                && dpc_ring.is_some_and(|dpc| {
                    dpc.epoch == queue.generation
                        && dpc.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OWNER_ACTIVE != 0
                })
        })
}

#[cfg(feature = "kernel")]
fn latch_cyw43_sdio_pair_restart_from_rx_queue_samples(
    queue_state: Option<DriverRuntimeCyw43RxQueueState>,
    dpc_ring: Option<DriverTaskSdioDpcRingSnapshot>,
    restart_context_available: bool,
) -> bool {
    if !cyw43_sdio_pair_restart_required_from_rx_queue(
        queue_state,
        dpc_ring,
        restart_context_available,
    ) {
        return false;
    }
    let runtime_recovery_source_line = queue_state
        .and_then(DriverRuntimeCyw43RxQueueState::recovery_source_line)
        .unwrap_or(0);
    // Preserve the queue's immutable runtime source before the existing lease
    // poison takes its own no-argument first-snapshot path.
    capture_first_cyw43_recovery_scheduler_snapshot_with_runtime_source(
        runtime_recovery_source_line,
    );
    poison_cyw43_sdio_network_priority_lease_if_owned();
    latch_cyw43_sdio_pair_restart_request_with_runtime_source(
        Cyw43SdioPairRestartCause::RxQueuePoison,
        runtime_recovery_source_line,
    );
    true
}

#[cfg(feature = "kernel")]
fn latch_cyw43_sdio_pair_restart_from_rx_queue(
    queue_state: Option<DriverRuntimeCyw43RxQueueState>,
) -> bool {
    if !queue_state.is_some_and(DriverRuntimeCyw43RxQueueState::poisoned) {
        return false;
    }
    latch_cyw43_sdio_pair_restart_from_rx_queue_samples(
        queue_state,
        driver_task_sdio_dpc_ring_snapshot(),
        cyw43_sdio_pair_restart_context_available(),
    )
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_pair_restart_already_latched() -> bool {
    if CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) != 0 {
        clear_cyw43_sdio_cold_bootstrap_epoch_token();
        poison_cyw43_sdio_network_priority_lease_if_owned();
        return true;
    }
    CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) != 0
}

/// Check the sole pair-recovery condition using a queue sample already taken
/// by the root service scheduler.
///
/// Reusing the sample avoids another cache-maintenance round trip on the
/// ordinary Network path. The sample remains passive until a current poisoned
/// generation is also bound to the active physical DPC owner and both restart
/// contexts.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_pair_restart_required_with_rx_queue_state(
    queue_state: Option<DriverRuntimeCyw43RxQueueState>,
) -> bool {
    if cyw43_sdio_pair_restart_already_latched() {
        return true;
    }
    let Some(slot) = slot_for_task_key(DRIVER_TASK_KEY_CYW43455) else {
        return false;
    };
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        return false;
    }
    let progress = driver_task_ring_read_progress_record(ring_root_ptr);
    if cyw43_sdio_pair_restart_progress(progress) {
        record_driver_task_ring_progress(slot, progress);
        poison_cyw43_sdio_network_priority_lease_if_owned();
        latch_cyw43_sdio_pair_restart_request(Cyw43SdioPairRestartCause::RuntimeProgress);
        return true;
    }
    latch_cyw43_sdio_pair_restart_from_rx_queue(queue_state)
}

/// Return whether the linked runtime has requested a root-authoritative pair restart.
///
/// This probes the live progress record even while the immutable parent ring
/// request remains active, then latches the request. Join/service state machines
/// must consult it before short-circuiting on an active fingerprint.
#[cfg(feature = "kernel")]
#[must_use]
pub fn cyw43_sdio_pair_restart_required() -> bool {
    if cyw43_sdio_pair_restart_already_latched() {
        return true;
    }
    // The general recovery predicate is used throughout TX, EAPOL, and Gate
    // 8 hot paths. It may inspect the compact progress marker, but must not
    // resample the larger private-RX queue on every call. The root scheduler's
    // condition-before-sleep snapshot is the one authoritative intake for
    // queue poison and passes that exact stable sample through the dedicated
    // helper above.
    cyw43_sdio_pair_restart_required_with_rx_queue_state(None)
}

/// Latch a root-authoritative CYW43/SDIO pair restart for the next safe turn.
///
/// This has no immediate recovery side effect. Callers that discover an
/// orphaned or issued-unknown linked-runtime request while holding another
/// subsystem lock use this seam to preserve fail-closed ordering; the normal
/// recovery supervisor consumes the sticky request after that lock is released.
#[cfg(feature = "kernel")]
pub fn request_cyw43_sdio_pair_restart() {
    poison_cyw43_sdio_network_priority_lease_if_owned();
    latch_cyw43_sdio_pair_restart_request(Cyw43SdioPairRestartCause::RootRequest);
}

/// Preserve canonical-owner validation as the first pair-recovery cause.
///
/// This records evidence only. The owner's existing deferred-recovery commit
/// remains responsible for fencing admission and latching the sole recovery
/// lane after its typed record is durable.
#[cfg(feature = "kernel")]
pub(crate) fn record_cyw43_sdio_persistent_parent_invalid_cause() {
    record_first_cyw43_sdio_pair_restart_cause(
        Cyw43SdioPairRestartCause::PersistentParentStableInvalid,
    );
}

/// Preserve a generic root-owner request before its diagnostic is retained.
///
/// This records evidence only. The caller must still commit its typed deferred
/// recovery and use the single pair-restart seam immediately afterward.
#[cfg(feature = "kernel")]
pub(crate) fn record_cyw43_sdio_root_request_cause() {
    record_first_cyw43_sdio_pair_restart_cause(Cyw43SdioPairRestartCause::RootRequest);
}

/// Return the immutable first recovery authority for passive diagnostics.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn first_cyw43_sdio_pair_restart_cause() -> &'static str {
    Cyw43SdioPairRestartCause::from_u32(CYW43_SDIO_PAIR_RESTART_FIRST_CAUSE.load(Ordering::Acquire))
        .map_or("unavailable", Cyw43SdioPairRestartCause::as_str)
}

/// Return whether both linked runtimes published the recovery authority needed
/// for a root-authoritative pair restart. Bootstrap retries must not latch the
/// restart gate until this is true: an early descriptor failure has no runtime
/// pair to suspend and is safe to replay through normal initialisation.
#[cfg(feature = "kernel")]
#[must_use]
pub fn cyw43_sdio_pair_restart_context_available() -> bool {
    #[cfg(test)]
    if DRIVER_TASK_TEST_CYW43_SDIO_RESTART_CONTEXT_AVAILABLE.load(Ordering::Acquire) != 0 {
        return true;
    }
    cyw43_sdio_runtime_restart_context(DriverTaskHotPath::Cyw43Wifi).is_some()
        && cyw43_sdio_runtime_restart_context(DriverTaskHotPath::SdioHost).is_some()
}

/// Return whether a fresh pair engine still needs firmware/control context replay.
#[cfg(feature = "kernel")]
#[must_use]
pub fn cyw43_sdio_pair_context_replay_required() -> bool {
    CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) != 0
}

/// Enter the sole full-context replay scope after a successful pair restart.
///
/// While state is `required`, generic CYW43 submissions fail closed. The
/// driver_task_net recovery state machine must acquire this scope before it
/// sends the retained firmware/control sequence. A newly pending or active
/// pair restart always takes precedence over replay of the superseded pair.
#[cfg(feature = "kernel")]
pub fn begin_cyw43_sdio_pair_context_replay() -> bool {
    if !cyw43_sdio_pair_context_replay_entry_allowed(
        CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire),
        CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire),
        CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire),
    ) {
        return false;
    }
    if CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE
        .compare_exchange(1, 2, Ordering::AcqRel, Ordering::Acquire)
        .is_err()
    {
        return false;
    }
    if CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) != 0
        || CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) != 0
    {
        let _ = CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.compare_exchange(
            2,
            1,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
        return false;
    }
    true
}

/// Finish the full-context replay scope.
///
/// Only a fully successful firmware/control replay clears the sticky gate. A
/// failed replay returns it to `required`, preventing old join/service bytes
/// from entering the engine-only generation.
#[cfg(feature = "kernel")]
pub fn finish_cyw43_sdio_pair_context_replay(success: bool) {
    // The token is a narrow capability for the owned initial replay only. A
    // successful finish consumes it; failure or cancellation revokes it.
    clear_cyw43_sdio_cold_bootstrap_epoch_token();
    let next = if success && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0 {
        0
    } else {
        1
    };
    let _ = CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.compare_exchange(
        2,
        next,
        Ordering::AcqRel,
        Ordering::Acquire,
    );
}

#[cfg(feature = "kernel")]
const fn cyw43_sdio_pair_context_replay_entry_allowed(
    restart_in_progress: u32,
    restart_pending: u32,
    context_replay_state: u32,
) -> bool {
    restart_in_progress == 0 && restart_pending == 0 && context_replay_state == 1
}

#[cfg(all(feature = "kernel", test))]
pub(crate) fn reset_cyw43_sdio_pair_recovery_for_test() {
    CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.store(0, Ordering::Release);
    CYW43_SDIO_PAIR_RESTART_PENDING.store(0, Ordering::Release);
    CYW43_SDIO_PAIR_RESTART_SUPERSEDED.store(0, Ordering::Release);
    CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.store(0, Ordering::Release);
    clear_cyw43_sdio_cold_bootstrap_epoch_token();
    DRIVER_TASK_SLOT_SDIO_HOST
        .ring_producer
        .store(SDIO_RING_PRODUCER_ROOT_BOOTSTRAP, Ordering::Release);
    let _ = DRIVER_TASK_SLOT_CYW43455
        .retained_priority_boost_active
        .compare_exchange(
            CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN,
            0,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
    let _ = DRIVER_TASK_SLOT_SDIO_HOST
        .retained_priority_boost_active
        .compare_exchange(
            CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN,
            0,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
    reset_cyw43_sdio_network_priority_lease_state(&CYW43_SDIO_NETWORK_PRIORITY_LEASE);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .opens
        .store(0, Ordering::Release);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .closes
        .store(0, Ordering::Release);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .restores
        .store(0, Ordering::Release);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .recovery_revocations
        .store(0, Ordering::Release);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .amortized_requests
        .store(0, Ordering::Release);
    CYW43_SDIO_NETWORK_PRIORITY_LEASE
        .failures
        .store(0, Ordering::Release);
    clear_cyw43_pair_terminal_drain();
    DRIVER_TASK_TEST_CYW43_SDIO_RESTART_CONTEXT_AVAILABLE.store(0, Ordering::Release);
    DRIVER_TASK_TEST_STEADY_PRIORITY_CUTOVER_FAILURE_TCB.store(0, Ordering::Release);
    DRIVER_TASK_TEST_FORCE_DEFERRED_RUNTIME_INIT_REPLAY.store(0, Ordering::Release);
    clear_first_cyw43_recovery_scheduler_snapshot();
}

/// Publish recovery-context availability without fabricating runtime commands.
#[cfg(all(feature = "kernel", test))]
pub(crate) fn test_publish_cyw43_sdio_pair_restart_context_available() {
    DRIVER_TASK_TEST_CYW43_SDIO_RESTART_CONTEXT_AVAILABLE.store(1, Ordering::Release);
}

/// Scope one test-owned live SDIO DPC owner without weakening production
/// descriptor or delegation checks.
#[cfg(all(feature = "kernel", test))]
pub(crate) struct TestCyw43SdioDpcOwnerGuard {
    previous_descriptor_seals: usize,
    previous_ring_producer: usize,
    previous_restart_context: usize,
}

#[cfg(all(feature = "kernel", test))]
impl Drop for TestCyw43SdioDpcOwnerGuard {
    fn drop(&mut self) {
        DRIVER_TASK_RUNTIME_DESCRIPTOR_SEAL_HOT_PATH_MASK
            .store(self.previous_descriptor_seals, Ordering::Release);
        DRIVER_TASK_SLOT_SDIO_HOST
            .ring_producer
            .store(self.previous_ring_producer, Ordering::Release);
        DRIVER_TASK_TEST_CYW43_SDIO_RESTART_CONTEXT_AVAILABLE
            .store(self.previous_restart_context, Ordering::Release);
    }
}

/// Enter the exact delegated-owner preconditions used by the production DPC
/// snapshot while retaining the prior global test state for scoped cleanup.
#[cfg(all(feature = "kernel", test))]
pub(crate) fn test_delegate_cyw43_sdio_dpc_owner() -> TestCyw43SdioDpcOwnerGuard {
    let delegated_pair_seals = DriverTaskHotPath::SdioHost.owner_state_bit()
        | DriverTaskHotPath::Cyw43Wifi.owner_state_bit();
    let previous_descriptor_seals = DRIVER_TASK_RUNTIME_DESCRIPTOR_SEAL_HOT_PATH_MASK
        .fetch_or(delegated_pair_seals, Ordering::AcqRel);
    let previous_ring_producer = DRIVER_TASK_SLOT_SDIO_HOST
        .ring_producer
        .swap(SDIO_RING_PRODUCER_CYW43_RUNTIME, Ordering::AcqRel);
    let previous_restart_context =
        DRIVER_TASK_TEST_CYW43_SDIO_RESTART_CONTEXT_AVAILABLE.swap(1, Ordering::AcqRel);
    TestCyw43SdioDpcOwnerGuard {
        previous_descriptor_seals,
        previous_ring_producer,
        previous_restart_context,
    }
}

