#[cfg(feature = "kernel")]
const fn hot_path_for_task_key(task_key: usize) -> Option<DriverTaskHotPath> {
    match task_key {
        DRIVER_TASK_KEY_SERIAL => Some(DriverTaskHotPath::SerialConsole),
        DRIVER_TASK_KEY_USB_LOCAL_SEAT => Some(DriverTaskHotPath::UsbKeyboard),
        DRIVER_TASK_KEY_HDMI_TEXT => Some(DriverTaskHotPath::HdmiText),
        DRIVER_TASK_KEY_BCMGENET_V5 => Some(DriverTaskHotPath::GenetNic),
        DRIVER_TASK_KEY_CYW43455 => Some(DriverTaskHotPath::Cyw43Wifi),
        DRIVER_TASK_KEY_SDIO_HOST => Some(DriverTaskHotPath::SdioHost),
        DRIVER_TASK_KEY_PCIE_ROOT => Some(DriverTaskHotPath::PcieRoot),
        DRIVER_TASK_KEY_RTL8139 | DRIVER_TASK_KEY_VIRTIO_NET => None,
        _ => None,
    }
}

#[cfg(feature = "kernel")]
pub(crate) fn driver_task_counter_snapshot(
    contract: DriverTaskContract,
) -> Option<DriverRuntimeCounterSnapshot> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let hot_path = hot_path_for_task_key(task_key)?;
    let snapshot = slot
        .counters
        .snapshot(hot_path, slot.request_seq.load(Ordering::Acquire));
    driver_task_counter_snapshot_has_activity(&snapshot).then_some(snapshot)
}

#[cfg(feature = "kernel")]
fn driver_task_counter_snapshot_has_activity(snapshot: &DriverRuntimeCounterSnapshot) -> bool {
    snapshot.sequence != 0
        || snapshot.submitted_turns != 0
        || snapshot.completed_turns != 0
        || snapshot.idle_turns != 0
        || snapshot.fault_turns != 0
        || snapshot.budget_exhausted_turns != 0
        || snapshot.frame_ready_turns != 0
        || snapshot.descriptors_drained != 0
        || snapshot.staged_bytes != 0
        || snapshot.cache_clean_ops != 0
        || snapshot.cache_clean_bytes != 0
        || snapshot.cache_invalidate_ops != 0
        || snapshot.cache_invalidate_bytes != 0
        || snapshot.send_attempts != 0
        || snapshot.yield_count != 0
        || snapshot.busy_conflicts != 0
        || snapshot.same_request_resumes != 0
        || snapshot.timeouts != 0
        || snapshot.keep_active_timeouts != 0
        || snapshot.aborts != 0
        || snapshot.overruns != 0
        || snapshot.drops != 0
        || snapshot.rx_frames != 0
        || snapshot.tx_frames != 0
        || snapshot.rx_bytes != 0
        || snapshot.tx_bytes != 0
        || snapshot.role_aux0 != 0
        || snapshot.role_aux1 != 0
        || snapshot.role_aux2 != 0
        || snapshot.role_aux3 != 0
}

#[cfg(feature = "kernel")]
pub(crate) fn latest_driver_task_ring_progress(
    contract: DriverTaskContract,
) -> Option<DriverTaskRingProgressSnapshot> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let magic = slot.last_progress_magic.load(Ordering::Acquire);
    let sequence = slot.last_progress_sequence.load(Ordering::Acquire);
    let phase = slot.last_progress_phase.load(Ordering::Acquire);
    let aux0 = slot.last_progress_aux0.load(Ordering::Acquire);
    if magic == 0 && sequence == 0 && phase == 0 && aux0 == 0 {
        return None;
    }
    Some(DriverTaskRingProgressSnapshot {
        marker_valid: magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
        sequence,
        phase,
        phase_name: driver_task_ring_progress_phase_label(phase),
        aux0,
    })
}

#[cfg(all(test, feature = "kernel"))]
pub(crate) fn test_record_driver_task_ring_progress_snapshot(
    contract: DriverTaskContract,
    sequence: u32,
    phase: u32,
    aux0: u32,
) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    record_driver_task_ring_progress(
        slot,
        DriverTaskRingProgressRecord {
            magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
            sequence,
            phase,
            aux0,
        },
    );
}

#[cfg(all(test, feature = "kernel"))]
pub(crate) fn test_clear_driver_task_ring_progress_snapshot(contract: DriverTaskContract) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.last_progress_magic.store(0, Ordering::Release);
    slot.last_progress_sequence.store(0, Ordering::Release);
    slot.last_progress_phase.store(0, Ordering::Release);
    slot.last_progress_aux0.store(0, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn current_driver_task_ring_request_for_slot(slot: &DriverTaskCommandSlot) -> Option<usize> {
    let request = slot.request_seq.load(Ordering::Acquire);
    (request != 0).then_some(request)
}

#[cfg(feature = "kernel")]
pub(crate) fn current_driver_task_ring_request(contract: DriverTaskContract) -> Option<usize> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    current_driver_task_ring_request_for_slot(slot)
}

#[cfg(feature = "kernel")]
fn active_driver_task_ring_request_for_slot(slot: &DriverTaskCommandSlot) -> Option<usize> {
    if slot.active.load(Ordering::Acquire) == 0 {
        return None;
    }
    current_driver_task_ring_request_for_slot(slot)
}

#[cfg(feature = "kernel")]
pub(crate) fn active_driver_task_ring_request(contract: DriverTaskContract) -> Option<usize> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    active_driver_task_ring_request_for_slot(slot)
}

/// Root-visible identity and issuance state for one retained ring request.
///
/// `Prepared` records have an ABI sequence of zero and are therefore invisible
/// to the autonomously polling child. `Issued` begins when the sequence is
/// committed, before the best-effort notification turn. `Invalid` is a torn or
/// aliased transport state and must be fenced rather than resumed.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum DriverTaskRetainedRequestState {
    Prepared {
        request: u32,
        command: DriverTaskCommandRecord,
    },
    Issued {
        request: u32,
        command: DriverTaskCommandRecord,
    },
    Invalid {
        request: u32,
    },
}

#[cfg(feature = "kernel")]
impl DriverTaskRetainedRequestState {
    pub(crate) const fn request(self) -> u32 {
        match self {
            Self::Prepared { request, .. }
            | Self::Issued { request, .. }
            | Self::Invalid { request } => request,
        }
    }

    pub(crate) const fn command(self) -> Option<DriverTaskCommandRecord> {
        match self {
            Self::Prepared { command, .. } | Self::Issued { command, .. } => Some(command),
            Self::Invalid { .. } => None,
        }
    }

    pub(crate) const fn issued(self) -> bool {
        matches!(self, Self::Issued { .. })
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_retained_phase_is_prepared(
    phase: DriverTaskRetainedLeasePhase,
    doorbell_issued: bool,
) -> bool {
    !doorbell_issued
        && matches!(
            phase,
            DriverTaskRetainedLeasePhase::Inactive
                | DriverTaskRetainedLeasePhase::BoostBus
                | DriverTaskRetainedLeasePhase::BoostPrimary
                | DriverTaskRetainedLeasePhase::ReadyToIssue
        )
}

#[cfg(feature = "kernel")]
const fn driver_task_retained_phase_is_issued(
    phase: DriverTaskRetainedLeasePhase,
    doorbell_issued: bool,
) -> bool {
    doorbell_issued
        && matches!(
            phase,
            DriverTaskRetainedLeasePhase::GrantRequired
                | DriverTaskRetainedLeasePhase::Granted
                | DriverTaskRetainedLeasePhase::Committed
                | DriverTaskRetainedLeasePhase::Issued
                | DriverTaskRetainedLeasePhase::RestorePrimary
                | DriverTaskRetainedLeasePhase::RestoreBus
                | DriverTaskRetainedLeasePhase::ReadyToComplete
        )
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct DriverTaskRetainedRequestSnapshot {
    state: DriverTaskRetainedRequestState,
    command_fingerprint: u32,
}

#[cfg(feature = "kernel")]
pub(crate) fn active_driver_task_retained_request(
    contract: DriverTaskContract,
) -> Option<DriverTaskRetainedRequestState> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    active_driver_task_retained_request_for_slot(slot)
}

/// Revalidate one retained request against its complete caller-owned input.
///
/// A prepared retained command deliberately has sequence zero and does not
/// expose its staged descriptor or payload until the issue turn. The HAL's
/// immutable command-plus-staging fingerprint is therefore the only exact
/// authority available before issue; re-reading shared bytes would either
/// adopt stale runtime output or reject every legitimate prepared request.
#[cfg(feature = "kernel")]
pub(crate) fn active_driver_task_retained_request_matches_staging(
    contract: DriverTaskContract,
    mut command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> Option<DriverTaskRetainedRequestState> {
    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0 {
        return None;
    }
    let snapshot = active_driver_task_retained_request_snapshot(contract)?;
    let request = snapshot.state.request();
    let mut active_command = snapshot.state.command()?;
    command.flags =
        driver_task_ring_flags_for_mode(DriverTaskRingCommandMode::RetainedTurn, command.flags);
    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION == 0
        && driver_task_cyw43_persistent_transaction_requested(
            contract,
            command,
            DriverTaskRingCommandMode::RetainedTurn,
            staging_segments,
        )
    {
        // Passive reconstruction derives the same immutable op11 authority as
        // the fresh producer path. It never trusts a caller-supplied tag.
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION;
    }
    if active_command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0
        && driver_task_slot_for_contract(contract)
            .is_some_and(|slot| slot.retained_steady_tx_fast_lane.load(Ordering::Acquire) != 0)
        && driver_task_staged_cyw43_descriptor_header(command, staging_segments).is_some_and(
            |(_, flags)| flags & DRIVER_RUNTIME_CYW43_FLAG_STEADY_TX_SERVICE_LEASE != 0,
        )
    {
        // Passive identity reconstruction mirrors the tag already present in
        // the active immutable command; it does not stage, issue, or mint new
        // authority for the caller.
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE;
    }
    command.sequence = request;
    active_command.sequence = request;
    if active_command != command {
        return None;
    }
    let expected_fingerprint = driver_task_ring_command_fingerprint(
        command,
        driver_task_staging_segments_fingerprint(staging_segments),
    );
    (expected_fingerprint != 0 && snapshot.command_fingerprint == expected_fingerprint)
        .then_some(snapshot.state)
}

#[cfg(feature = "kernel")]
fn classify_driver_task_retained_request(
    request: u32,
    mut command: DriverTaskCommandRecord,
    phase: DriverTaskRetainedLeasePhase,
    doorbell_issued: bool,
) -> DriverTaskRetainedRequestState {
    if command.sequence == 0 && driver_task_retained_phase_is_prepared(phase, doorbell_issued) {
        command.sequence = request;
        DriverTaskRetainedRequestState::Prepared { request, command }
    } else if command.sequence == request
        && driver_task_retained_phase_is_issued(phase, doorbell_issued)
    {
        DriverTaskRetainedRequestState::Issued { request, command }
    } else {
        DriverTaskRetainedRequestState::Invalid { request }
    }
}

#[cfg(feature = "kernel")]
fn active_driver_task_retained_request_for_slot(
    slot: &DriverTaskCommandSlot,
) -> Option<DriverTaskRetainedRequestState> {
    if slot.active.load(Ordering::Acquire) == 0 {
        return None;
    }
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    let request = u32::try_from(slot.request_seq.load(Ordering::Acquire)).ok()?;
    if ring_root_ptr == 0 || request == 0 {
        return Some(DriverTaskRetainedRequestState::Invalid { request });
    }
    let Some(phase) = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    ) else {
        return Some(DriverTaskRetainedRequestState::Invalid { request });
    };
    let doorbell_issued = slot.retained_doorbell_issued.load(Ordering::Acquire) != 0;
    let command_ptr = ring_root_ptr as *const DriverTaskCommandRecord;
    // SAFETY: The admitted shared page begins with the fixed ABI command. Root
    // owns the single producer slot while `active` is set.
    let command = unsafe { core::ptr::read_volatile(command_ptr) };
    let fast = classify_driver_task_retained_request(request, command, phase, doorbell_issued);
    if !matches!(fast, DriverTaskRetainedRequestState::Invalid { .. }) {
        return Some(fast);
    }

    // A raw shared-page load is a fast hint, not authority to destroy the
    // pair. Only the uncommon invalid candidate pays for bounded cache
    // invalidation and a stable two-read snapshot. Re-reading the phase and
    // doorbell after that snapshot also closes a concurrent Issue transition;
    // ordinary valid TCP traffic keeps the zero-maintenance fast path.
    let Some(command) = driver_task_ring_stable_command_snapshot(slot, ring_root_ptr) else {
        return Some(DriverTaskRetainedRequestState::Invalid { request });
    };
    let Some(phase) = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    ) else {
        return Some(DriverTaskRetainedRequestState::Invalid { request });
    };
    let doorbell_issued = slot.retained_doorbell_issued.load(Ordering::Acquire) != 0;
    Some(classify_driver_task_retained_request(
        request,
        command,
        phase,
        doorbell_issued,
    ))
}

#[cfg(feature = "kernel")]
fn active_driver_task_retained_request_snapshot(
    contract: DriverTaskContract,
) -> Option<DriverTaskRetainedRequestSnapshot> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let state = active_driver_task_retained_request_for_slot(slot)?;
    let command_fingerprint = slot.active_command_fingerprint.load(Ordering::Acquire);
    (command_fingerprint != 0).then_some(DriverTaskRetainedRequestSnapshot {
        state,
        command_fingerprint,
    })
}

#[cfg(feature = "kernel")]
fn classify_cyw43_sdio_network_boundary_parent(
    snapshot: Option<DriverTaskRetainedRequestSnapshot>,
) -> Cyw43SdioNetworkBoundaryParent {
    let Some(snapshot) = snapshot else {
        return Cyw43SdioNetworkBoundaryParent::Inactive;
    };
    let request = snapshot.state.request();
    let Some(command) = snapshot.state.command() else {
        return Cyw43SdioNetworkBoundaryParent::Invalid { request };
    };
    if snapshot.command_fingerprint == 0
        || !driver_runtime_is_cyw43_root_continuation(command.arg0, command.arg1, command.aux0)
    {
        return Cyw43SdioNetworkBoundaryParent::Invalid { request };
    }
    match snapshot.state {
        DriverTaskRetainedRequestState::Prepared { .. } => {
            Cyw43SdioNetworkBoundaryParent::Prepared {
                request,
                command_fingerprint: snapshot.command_fingerprint,
            }
        }
        DriverTaskRetainedRequestState::Issued { .. } => Cyw43SdioNetworkBoundaryParent::Issued {
            request,
            command_fingerprint: snapshot.command_fingerprint,
        },
        DriverTaskRetainedRequestState::Invalid { .. } => {
            Cyw43SdioNetworkBoundaryParent::Invalid { request }
        }
    }
}

#[cfg(feature = "kernel")]
const fn validate_cyw43_sdio_network_boundary_parent(
    parent: Cyw43SdioNetworkBoundaryParent,
    phase: Option<Cyw43SdioNetworkPriorityLeasePhase>,
    priority_token_present: bool,
    pair_current: bool,
) -> Cyw43SdioNetworkBoundaryParent {
    if !parent.resumable() {
        return parent;
    }
    if matches!(phase, Some(Cyw43SdioNetworkPriorityLeasePhase::Inactive))
        && !priority_token_present
        && pair_current
    {
        parent
    } else {
        Cyw43SdioNetworkBoundaryParent::Invalid {
            request: parent.request(),
        }
    }
}

/// Snapshot the sole exact CYW43 parent that may cross from an unleased
/// network turn into the lease-aware EventPump lane.
///
/// This boundary exists for an already-prepared parent only. It never admits a
/// fresh command and rejects torn, wrong-operation, pair-recovery, or leaked
/// priority-token state.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_sdio_network_boundary_parent() -> Cyw43SdioNetworkBoundaryParent {
    let snapshot =
        active_driver_task_retained_request_for_slot(&DRIVER_TASK_SLOT_CYW43455).map(|state| {
            DriverTaskRetainedRequestSnapshot {
                state,
                command_fingerprint: DRIVER_TASK_SLOT_CYW43455
                    .active_command_fingerprint
                    .load(Ordering::Acquire),
            }
        });
    let parent = classify_cyw43_sdio_network_boundary_parent(snapshot);
    if !parent.resumable() {
        return parent;
    }
    let phase = Cyw43SdioNetworkPriorityLeasePhase::from_u32(
        CYW43_SDIO_NETWORK_PRIORITY_LEASE
            .phase
            .load(Ordering::Acquire),
    );
    let priority_token_present = DRIVER_TASK_SLOT_CYW43455
        .retained_priority_boost_active
        .load(Ordering::Acquire)
        == CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN
        || DRIVER_TASK_SLOT_SDIO_HOST
            .retained_priority_boost_active
            .load(Ordering::Acquire)
            == CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN;
    let pair_current = CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) == 0;
    validate_cyw43_sdio_network_boundary_parent(parent, phase, priority_token_present, pair_current)
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_network_active_parent_resumable_with(
    lease: &Cyw43SdioNetworkPriorityLeaseState,
    cyw43_slot: &DriverTaskCommandSlot,
    sdio_slot: &DriverTaskCommandSlot,
    snapshot: Option<DriverTaskRetainedRequestSnapshot>,
    expected_connection_generation: u32,
    current_pair_epoch: u32,
    pair_current: bool,
) -> bool {
    cyw43_sdio_network_active_parent_resumable_for_phase_with(
        lease,
        cyw43_slot,
        sdio_slot,
        snapshot,
        expected_connection_generation,
        current_pair_epoch,
        pair_current,
        false,
    )
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_network_active_parent_resumable_for_phase_with(
    lease: &Cyw43SdioNetworkPriorityLeaseState,
    cyw43_slot: &DriverTaskCommandSlot,
    sdio_slot: &DriverTaskCommandSlot,
    snapshot: Option<DriverTaskRetainedRequestSnapshot>,
    expected_connection_generation: u32,
    current_pair_epoch: u32,
    pair_current: bool,
    closing_parent_resume: bool,
) -> bool {
    let Some(snapshot) = snapshot else {
        return false;
    };
    let parent = classify_cyw43_sdio_network_boundary_parent(Some(snapshot));
    let (request, command_fingerprint) = match parent {
        Cyw43SdioNetworkBoundaryParent::Prepared {
            request,
            command_fingerprint,
        }
        | Cyw43SdioNetworkBoundaryParent::Issued {
            request,
            command_fingerprint,
        } => (request, command_fingerprint),
        Cyw43SdioNetworkBoundaryParent::Inactive
        | Cyw43SdioNetworkBoundaryParent::Invalid { .. } => return false,
    };
    let Some(command) = snapshot.state.command() else {
        return false;
    };
    if command.sequence != request
        || command.aux1 != expected_connection_generation
        || cyw43_slot.active.load(Ordering::Acquire) == 0
        || cyw43_slot.request_seq.load(Ordering::Acquire) != request as usize
        || cyw43_slot
            .active_command_fingerprint
            .load(Ordering::Acquire)
            != command_fingerprint
        || cyw43_slot.root_notification.load(Ordering::Acquire) == 0
        || !pair_current
    {
        return false;
    }

    let phase = Cyw43SdioNetworkPriorityLeasePhase::from_u32(lease.phase.load(Ordering::Acquire));
    let mask = lease.mask.load(Ordering::Acquire);
    let valid_mask = DRIVER_TASK_RETAINED_LEASE_PRIMARY | DRIVER_TASK_RETAINED_LEASE_BUS;
    let phase_covered = phase == Some(Cyw43SdioNetworkPriorityLeasePhase::Open)
        || (closing_parent_resume && phase == Some(Cyw43SdioNetworkPriorityLeasePhase::Closing));
    if !phase_covered
        || lease.pair_epoch.load(Ordering::Acquire) != current_pair_epoch
        || mask == 0
        || mask & !valid_mask != 0
        || !cyw43_sdio_network_priority_reservations_match(cyw43_slot, sdio_slot, mask)
    {
        return false;
    }

    let retained_phase = DriverTaskRetainedLeasePhase::from_usize(
        cyw43_slot
            .retained_priority_lease_phase
            .load(Ordering::Acquire),
    );
    let doorbell_issued = cyw43_slot.retained_doorbell_issued.load(Ordering::Acquire) != 0;
    let retained_phase_matches = match (snapshot.state, retained_phase) {
        (DriverTaskRetainedRequestState::Prepared { .. }, Some(retained_phase)) => {
            driver_task_retained_phase_is_prepared(retained_phase, doorbell_issued)
        }
        (DriverTaskRetainedRequestState::Issued { .. }, Some(retained_phase)) => {
            driver_task_retained_phase_is_issued(retained_phase, doorbell_issued)
        }
        (DriverTaskRetainedRequestState::Invalid { .. }, _) | (_, None) => false,
    };
    if !retained_phase_matches {
        return false;
    }
    if retained_phase == Some(DriverTaskRetainedLeasePhase::Inactive) {
        return !snapshot.state.issued()
            && cyw43_slot
                .retained_priority_lease_request
                .load(Ordering::Acquire)
                == 0
            && cyw43_slot
                .retained_priority_lease_fingerprint
                .load(Ordering::Acquire)
                == 0
            && cyw43_slot
                .retained_priority_lease_generation
                .load(Ordering::Acquire)
                == 0
            && cyw43_slot
                .retained_priority_lease_mask
                .load(Ordering::Acquire)
                == 0
            && cyw43_slot.retained_grant_id.load(Ordering::Acquire) == 0;
    }

    driver_task_retained_lease_identity_matches_generation(
        cyw43_slot,
        request as usize,
        command_fingerprint,
        current_pair_epoch,
    )
}

/// Return whether the open Network lease owns one exact current CYW43 parent.
///
/// Closing and unleased-boundary parents use their separate typed drain
/// snapshots. This predicate is solely for keeping an already-admitted Open
/// parent contiguous after the fresh-parent virtual-time fence has elapsed.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_network_active_parent_resumable(
    expected_connection_generation: u32,
) -> bool {
    let current_pair_epoch = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
    let pair_current = CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) == 0;
    cyw43_sdio_network_active_parent_resumable_with(
        &CYW43_SDIO_NETWORK_PRIORITY_LEASE,
        &DRIVER_TASK_SLOT_CYW43455,
        &DRIVER_TASK_SLOT_SDIO_HOST,
        active_driver_task_retained_request_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT),
        expected_connection_generation,
        current_pair_epoch,
        pair_current,
    )
}

/// Re-read the exact active CYW43 parent immediately before Network sleeps.
///
/// Prepared input, a persistent op11 without an exact committed wait receipt,
/// a stable sequence-last terminal, a published op8 grant awaiting its notify
/// turn, or a consumed/current op8 grant is runnable and must retain the
/// bounded Network episode without relying on another notification edge. Only
/// an exact persistent receipt proves the child is durably parked. This
/// predicate never samples a deadline or mutates the parent.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_network_active_parent_progress_visible(
    expected_connection_generation: u32,
) -> bool {
    let slot = &DRIVER_TASK_SLOT_CYW43455;
    let snapshot = active_driver_task_retained_request_for_slot(slot).map(|state| {
        DriverTaskRetainedRequestSnapshot {
            state,
            command_fingerprint: slot.active_command_fingerprint.load(Ordering::Acquire),
        }
    });
    let current_pair_epoch = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
    let pair_current = CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) == 0;
    if !cyw43_sdio_network_active_parent_resumable_with(
        &CYW43_SDIO_NETWORK_PRIORITY_LEASE,
        slot,
        &DRIVER_TASK_SLOT_SDIO_HOST,
        snapshot,
        expected_connection_generation,
        current_pair_epoch,
        pair_current,
    ) {
        return false;
    }
    let Some(snapshot) = snapshot else {
        return false;
    };
    cyw43_sdio_network_active_parent_progress_visible_for_slot(slot, snapshot)
}

/// Return whether exact persistent op11 is still crossing its notify/wait cut.
///
/// This is narrower than generic runnable-parent progress: EventPump must keep
/// the same Network episode live, but upper policy demand stays masked until a
/// stable wait receipt proves the child parked or the exact terminal appears.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_network_persistent_parent_pre_wait(
    expected_connection_generation: u32,
) -> bool {
    let slot = &DRIVER_TASK_SLOT_CYW43455;
    let snapshot = active_driver_task_retained_request_for_slot(slot).map(|state| {
        DriverTaskRetainedRequestSnapshot {
            state,
            command_fingerprint: slot.active_command_fingerprint.load(Ordering::Acquire),
        }
    });
    let current_pair_epoch = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
    let pair_current = CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) == 0;
    if !cyw43_sdio_network_active_parent_resumable_with(
        &CYW43_SDIO_NETWORK_PRIORITY_LEASE,
        slot,
        &DRIVER_TASK_SLOT_SDIO_HOST,
        snapshot,
        expected_connection_generation,
        current_pair_epoch,
        pair_current,
    ) {
        return false;
    }
    let Some(snapshot) = snapshot else {
        return false;
    };
    let DriverTaskRetainedRequestState::Issued { request, command } = snapshot.state else {
        return false;
    };
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0
        && driver_task_persistent_transaction_parent_identity_matches(
            slot,
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command,
            ring_root_ptr,
            request,
            snapshot.command_fingerprint,
        )
        && !driver_task_ring_exact_completion_is_stable(slot, ring_root_ptr, request)
        && !driver_task_persistent_transaction_wait_armed(slot, snapshot)
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_network_persistent_parent_condition_for_slot(
    slot: &DriverTaskCommandSlot,
    snapshot: DriverTaskRetainedRequestSnapshot,
) -> Cyw43SdioNetworkPersistentParentCondition {
    let Some(command) = snapshot.state.command() else {
        return Cyw43SdioNetworkPersistentParentCondition::Invalid;
    };
    if !driver_task_persistent_transaction_command_shape(CYW43_WIFI_DRIVER_TASK_CONTRACT, command) {
        return Cyw43SdioNetworkPersistentParentCondition::NotApplicable;
    }
    let (request, command) = match snapshot.state {
        DriverTaskRetainedRequestState::Prepared { .. } => {
            return Cyw43SdioNetworkPersistentParentCondition::PreWait;
        }
        DriverTaskRetainedRequestState::Issued { request, command } => (request, command),
        DriverTaskRetainedRequestState::Invalid { .. } => {
            return Cyw43SdioNetworkPersistentParentCondition::Invalid;
        }
    };
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if !driver_task_persistent_transaction_parent_identity_matches(
        slot,
        CYW43_WIFI_DRIVER_TASK_CONTRACT,
        command,
        ring_root_ptr,
        request,
        snapshot.command_fingerprint,
    ) {
        return Cyw43SdioNetworkPersistentParentCondition::Invalid;
    }
    if driver_task_ring_exact_completion_is_stable(slot, ring_root_ptr, request) {
        return Cyw43SdioNetworkPersistentParentCondition::Terminal;
    }
    if driver_task_persistent_transaction_wait_armed(slot, snapshot) {
        Cyw43SdioNetworkPersistentParentCondition::Waiting
    } else if driver_task_ring_exact_completion_is_stable(slot, ring_root_ptr, request) {
        Cyw43SdioNetworkPersistentParentCondition::Terminal
    } else {
        Cyw43SdioNetworkPersistentParentCondition::PreWait
    }
}

/// Classify exact op11 across Open, Closing, and typed boundary ownership.
///
/// The outer scheduling phase may change for bounded operator fairness, but
/// that cannot create a sleep edge between root Issue and the child's named
/// local-notification wait. Every phase revalidates the same immutable parent,
/// pair epoch, connection generation, and retained HAL lease before exposing
/// `PreWait`, `Waiting`, or `Terminal`.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_network_persistent_parent_condition(
    expected_connection_generation: u32,
) -> Cyw43SdioNetworkPersistentParentCondition {
    let slot = &DRIVER_TASK_SLOT_CYW43455;
    let snapshot = active_driver_task_retained_request_for_slot(slot).map(|state| {
        DriverTaskRetainedRequestSnapshot {
            state,
            command_fingerprint: slot.active_command_fingerprint.load(Ordering::Acquire),
        }
    });
    let Some(snapshot) = snapshot else {
        return Cyw43SdioNetworkPersistentParentCondition::NotApplicable;
    };
    let Some(command) = snapshot.state.command() else {
        return Cyw43SdioNetworkPersistentParentCondition::Invalid;
    };
    if !driver_task_persistent_transaction_command_shape(CYW43_WIFI_DRIVER_TASK_CONTRACT, command) {
        return Cyw43SdioNetworkPersistentParentCondition::NotApplicable;
    }
    if command.aux1 != expected_connection_generation {
        return Cyw43SdioNetworkPersistentParentCondition::Invalid;
    }

    let current_pair_epoch = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
    let pair_current = CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire) == 0
        && CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire) == 0;
    let phase = Cyw43SdioNetworkPriorityLeasePhase::from_u32(
        CYW43_SDIO_NETWORK_PRIORITY_LEASE
            .phase
            .load(Ordering::Acquire),
    );
    let exact_outer_owner = match phase {
        Some(Cyw43SdioNetworkPriorityLeasePhase::Open) => {
            cyw43_sdio_network_active_parent_resumable_for_phase_with(
                &CYW43_SDIO_NETWORK_PRIORITY_LEASE,
                slot,
                &DRIVER_TASK_SLOT_SDIO_HOST,
                Some(snapshot),
                expected_connection_generation,
                current_pair_epoch,
                pair_current,
                false,
            )
        }
        Some(Cyw43SdioNetworkPriorityLeasePhase::Closing) => {
            cyw43_sdio_network_active_parent_resumable_for_phase_with(
                &CYW43_SDIO_NETWORK_PRIORITY_LEASE,
                slot,
                &DRIVER_TASK_SLOT_SDIO_HOST,
                Some(snapshot),
                expected_connection_generation,
                current_pair_epoch,
                pair_current,
                true,
            )
        }
        Some(Cyw43SdioNetworkPriorityLeasePhase::Inactive) => {
            let expected = classify_cyw43_sdio_network_boundary_parent(Some(snapshot));
            expected.resumable() && cyw43_sdio_network_boundary_parent() == expected
        }
        Some(
            Cyw43SdioNetworkPriorityLeasePhase::Acquiring
            | Cyw43SdioNetworkPriorityLeasePhase::Restoring
            | Cyw43SdioNetworkPriorityLeasePhase::Poisoned,
        )
        | None => false,
    };
    if !exact_outer_owner {
        return Cyw43SdioNetworkPersistentParentCondition::Invalid;
    }
    cyw43_sdio_network_persistent_parent_condition_for_slot(slot, snapshot)
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_network_persistent_parent_condition_after_recheck_with(
    mut classify: impl FnMut() -> Cyw43SdioNetworkPersistentParentCondition,
) -> Cyw43SdioNetworkPersistentParentCondition {
    let first = classify();
    if first == Cyw43SdioNetworkPersistentParentCondition::Invalid {
        classify()
    } else {
        first
    }
}

/// Classify an outer persistent parent across one complete same-boundary recheck.
///
/// A single invalid composite sample can span root's Issue transition or one
/// non-coherent shared-command cache line. It is therefore only a prompt to
/// resample the same immutable identity, never pair-recovery authority. The
/// second result remains passive and is routed to the canonical policy owner.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_network_persistent_parent_condition_after_recheck(
    expected_connection_generation: u32,
) -> Cyw43SdioNetworkPersistentParentCondition {
    cyw43_sdio_network_persistent_parent_condition_after_recheck_with(|| {
        cyw43_sdio_network_persistent_parent_condition(expected_connection_generation)
    })
}

/// Classify runnable progress for an already-revalidated Network parent.
///
/// Keeping this condition separate from lease admission makes its phase
/// contract directly testable: persistent op11 stays runnable until its exact
/// wait receipt, a published grant still needs its notify turn, an issued
/// unconsumed grant may sleep, and a sequence-last terminal always wins over
/// either intermediate state.
#[cfg(feature = "kernel")]
fn cyw43_sdio_network_active_parent_progress_visible_for_slot(
    slot: &DriverTaskCommandSlot,
    snapshot: DriverTaskRetainedRequestSnapshot,
) -> bool {
    let (request, command) = match snapshot.state {
        DriverTaskRetainedRequestState::Prepared { .. } => return true,
        DriverTaskRetainedRequestState::Issued { request, command } => (request, command),
        DriverTaskRetainedRequestState::Invalid { .. } => return false,
    };
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if driver_task_ring_exact_completion_is_stable(slot, ring_root_ptr, request) {
        return true;
    }
    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0 {
        return !driver_task_persistent_transaction_wait_armed(slot, snapshot);
    }
    if !driver_task_retained_uses_root_grant(CYW43_WIFI_DRIVER_TASK_CONTRACT, command) {
        return false;
    }

    let phase = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    );
    let current_grant = slot.retained_grant_id.load(Ordering::Acquire);
    match phase {
        Some(DriverTaskRetainedLeasePhase::GrantRequired) if current_grant == 0 => {
            driver_task_ring_read_continuation_grant(ring_root_ptr).is_none()
        }
        Some(DriverTaskRetainedLeasePhase::GrantRequired) => {
            read_driver_task_retained_root_grant_stable_with(command, current_grant, || {
                driver_task_ring_read_continuation_grant(ring_root_ptr)
            })
            .is_some_and(|grant| grant.consumed_grant_id == current_grant)
        }
        Some(DriverTaskRetainedLeasePhase::Granted) => {
            current_grant != 0
                && read_driver_task_retained_root_grant_stable_with(command, current_grant, || {
                    driver_task_ring_read_continuation_grant(ring_root_ptr)
                })
                .is_some()
        }
        Some(DriverTaskRetainedLeasePhase::Issued) => {
            current_grant != 0
                && read_driver_task_retained_root_grant_stable_with(command, current_grant, || {
                    driver_task_ring_read_continuation_grant(ring_root_ptr)
                })
                .is_some_and(|grant| grant.consumed_grant_id == current_grant)
        }
        Some(
            DriverTaskRetainedLeasePhase::Inactive
            | DriverTaskRetainedLeasePhase::BoostBus
            | DriverTaskRetainedLeasePhase::BoostPrimary
            | DriverTaskRetainedLeasePhase::ReadyToIssue
            | DriverTaskRetainedLeasePhase::Committed
            | DriverTaskRetainedLeasePhase::RestorePrimary
            | DriverTaskRetainedLeasePhase::RestoreBus
            | DriverTaskRetainedLeasePhase::ReadyToComplete
            | DriverTaskRetainedLeasePhase::Poisoned,
        )
        | None => false,
    }
}

/// Open the sole pair-fenced continuation lane for one already-issued CYW43
/// request.
///
/// The authority is valid only while the same immutable request, generation,
/// and command fingerprint remain active. It cannot admit prepared or fresh
/// work and is cleared before pair teardown.
#[cfg(feature = "kernel")]
pub(crate) fn begin_cyw43_pair_terminal_drain(generation: u32, request: u32) -> bool {
    if request == 0 {
        return false;
    }
    let Some(snapshot) =
        active_driver_task_retained_request_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
    else {
        return false;
    };
    let DriverTaskRetainedRequestState::Issued {
        request: active_request,
        command,
    } = snapshot.state
    else {
        return false;
    };
    if active_request != request || snapshot.command_fingerprint == 0 {
        return false;
    }
    let current = CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire);
    let pair_epoch = CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire);
    if current != 0 {
        // A published request is sequence-last authority. Never rewrite its
        // body in place, even for an apparently idempotent second admission.
        return current == request
            && CYW43_PAIR_TERMINAL_DRAIN_GENERATION.load(Ordering::Relaxed) == generation
            && CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.load(Ordering::Relaxed) == command.aux1
            && CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.load(Ordering::Relaxed)
                == snapshot.command_fingerprint
            && CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.load(Ordering::Relaxed) == pair_epoch;
    }
    CYW43_PAIR_TERMINAL_DRAIN_GENERATION.store(generation, Ordering::Relaxed);
    // Engine-init commands intentionally keep ABI aux1 at zero, while normal
    // CYW43 descriptor commands carry the root generation there. Preserve
    // both independent identities: the root-owned generation controls
    // revocation, and the exact immutable command aux1 participates in the
    // retained-slot fingerprint fence.
    CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.store(command.aux1, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.store(snapshot.command_fingerprint, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.store(pair_epoch, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_REQUEST.store(request, Ordering::Release);
    true
}

/// Passively confirm the sole pair-fenced continuation authority.
///
/// Scheduler observations use this only to distinguish a supervisor-opened
/// exact bootstrap drain from an unadmitted recovery turn. It performs no ring
/// write, grant publication, notification, or authority mutation.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_pair_terminal_drain_authorized(generation: u32, request: u32) -> bool {
    if request == 0
        || CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire) != request
        || CYW43_PAIR_TERMINAL_DRAIN_GENERATION.load(Ordering::Acquire) != generation
    {
        return false;
    }
    let Some(snapshot) =
        active_driver_task_retained_request_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
    else {
        return false;
    };
    let DriverTaskRetainedRequestState::Issued {
        request: active_request,
        command,
    } = snapshot.state
    else {
        return false;
    };
    active_request == request
        && snapshot.command_fingerprint != 0
        && CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.load(Ordering::Acquire) == command.aux1
        && CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.load(Ordering::Acquire)
            == snapshot.command_fingerprint
        && CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.load(Ordering::Acquire)
            == CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire)
}

/// Non-copyable authority to close one exact pair-fenced continuation.
#[cfg(feature = "kernel")]
#[derive(Debug, Eq, PartialEq)]
pub(crate) struct Cyw43PairTerminalDrainReceipt {
    generation: u32,
    request: u32,
    command_aux1: u32,
    command_fingerprint: u32,
    pair_epoch: u32,
}

#[cfg(feature = "kernel")]
const CYW43_PAIR_TERMINAL_DRAIN_RETIRING: u32 = u32::MAX;

/// Acquire one stable, exact pair-drain receipt without advancing it.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_pair_terminal_drain_receipt(
    generation: u32,
    request: u32,
) -> Option<Cyw43PairTerminalDrainReceipt> {
    if request == 0 || request == CYW43_PAIR_TERMINAL_DRAIN_RETIRING {
        return None;
    }
    let first = CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire);
    if first != request {
        return None;
    }
    let receipt = Cyw43PairTerminalDrainReceipt {
        generation: CYW43_PAIR_TERMINAL_DRAIN_GENERATION.load(Ordering::Relaxed),
        request,
        command_aux1: CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.load(Ordering::Relaxed),
        command_fingerprint: CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.load(Ordering::Relaxed),
        pair_epoch: CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.load(Ordering::Relaxed),
    };
    let second = CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire);
    (second == first
        && receipt.generation == generation
        && receipt.command_fingerprint != 0
        && receipt.pair_epoch == CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire))
    .then_some(receipt)
}

/// Revalidate a previously acquired pair-drain authority.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_pair_terminal_drain_receipt_matches(
    receipt: &Cyw43PairTerminalDrainReceipt,
) -> bool {
    CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire) == receipt.request
        && CYW43_PAIR_TERMINAL_DRAIN_GENERATION.load(Ordering::Relaxed) == receipt.generation
        && CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.load(Ordering::Relaxed) == receipt.command_aux1
        && CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.load(Ordering::Relaxed)
            == receipt.command_fingerprint
        && CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.load(Ordering::Relaxed) == receipt.pair_epoch
        && receipt.command_fingerprint != 0
        && receipt.pair_epoch == CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire)
}

/// Compare-clear one exact pair-drain authority after semantic commit.
#[cfg(feature = "kernel")]
pub(crate) fn finish_cyw43_pair_terminal_drain_receipt(
    receipt: Cyw43PairTerminalDrainReceipt,
) -> bool {
    if !cyw43_pair_terminal_drain_receipt_matches(&receipt)
        || CYW43_PAIR_TERMINAL_DRAIN_REQUEST
            .compare_exchange(
                receipt.request,
                CYW43_PAIR_TERMINAL_DRAIN_RETIRING,
                Ordering::AcqRel,
                Ordering::Acquire,
            )
            .is_err()
    {
        return false;
    }
    CYW43_PAIR_TERMINAL_DRAIN_GENERATION.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_REQUEST.store(0, Ordering::Release);
    true
}

/// Exact HAL proof that one persistent op11 parent reached a stable terminal.
///
/// This replaces the active retained slot after terminal observation and
/// remains authoritative until the root protocol owner has copied/routed the
/// result and committed its semantic state. The request is the sequence-last
/// publication word; notifications carry none of this authority.
#[cfg(feature = "kernel")]
#[derive(Debug, Eq, PartialEq)]
pub(crate) struct Cyw43SemanticTerminalReceipt {
    request: u32,
    command_fingerprint: u32,
    command_aux1: u32,
    pair_epoch: u32,
}

#[cfg(feature = "kernel")]
const CYW43_SEMANTIC_TERMINAL_RETIRING: u32 = u32::MAX;

#[cfg(feature = "kernel")]
fn publish_cyw43_semantic_terminal_receipt(
    slot: &DriverTaskCommandSlot,
    request: u32,
    command: DriverTaskCommandRecord,
    command_fingerprint: u32,
) -> bool {
    if request == 0
        || request == CYW43_SEMANTIC_TERMINAL_RETIRING
        || command_fingerprint == 0
        || slot.semantic_terminal_request.load(Ordering::Acquire) != 0
    {
        return false;
    }
    slot.semantic_terminal_fingerprint
        .store(command_fingerprint, Ordering::Relaxed);
    slot.semantic_terminal_aux1
        .store(command.aux1, Ordering::Relaxed);
    slot.semantic_terminal_pair_epoch.store(
        CYW43_SDIO_PAIR_RESTART_EPOCH.load(Ordering::Acquire),
        Ordering::Relaxed,
    );
    slot.semantic_terminal_request
        .store(request, Ordering::Release);
    true
}

/// Passively acquire the exact persistent-op11 terminal receipt.
#[cfg(feature = "kernel")]
fn cyw43_semantic_terminal_receipt_from_slot(
    slot: &DriverTaskCommandSlot,
    request: u32,
) -> Option<Cyw43SemanticTerminalReceipt> {
    if request == 0 || request == CYW43_SEMANTIC_TERMINAL_RETIRING {
        return None;
    }
    let first = slot.semantic_terminal_request.load(Ordering::Acquire);
    if first != request {
        return None;
    }
    let receipt = Cyw43SemanticTerminalReceipt {
        request,
        command_fingerprint: slot.semantic_terminal_fingerprint.load(Ordering::Relaxed),
        command_aux1: slot.semantic_terminal_aux1.load(Ordering::Relaxed),
        pair_epoch: slot.semantic_terminal_pair_epoch.load(Ordering::Relaxed),
    };
    let second = slot.semantic_terminal_request.load(Ordering::Acquire);
    (second == first && receipt.command_fingerprint != 0).then_some(receipt)
}

/// Passively acquire the exact persistent-op11 terminal receipt.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_semantic_terminal_receipt(
    request: u32,
) -> Option<Cyw43SemanticTerminalReceipt> {
    cyw43_semantic_terminal_receipt_from_slot(&DRIVER_TASK_SLOT_CYW43455, request)
}

/// Passively revalidate a previously acquired semantic terminal receipt.
#[cfg(feature = "kernel")]
fn cyw43_semantic_terminal_receipt_matches_slot(
    slot: &DriverTaskCommandSlot,
    receipt: &Cyw43SemanticTerminalReceipt,
) -> bool {
    slot.semantic_terminal_request.load(Ordering::Acquire) == receipt.request
        && slot.semantic_terminal_fingerprint.load(Ordering::Relaxed) == receipt.command_fingerprint
        && slot.semantic_terminal_aux1.load(Ordering::Relaxed) == receipt.command_aux1
        && slot.semantic_terminal_pair_epoch.load(Ordering::Relaxed) == receipt.pair_epoch
}

/// Passively revalidate a previously acquired semantic terminal receipt.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_semantic_terminal_receipt_matches(
    receipt: &Cyw43SemanticTerminalReceipt,
) -> bool {
    cyw43_semantic_terminal_receipt_matches_slot(&DRIVER_TASK_SLOT_CYW43455, receipt)
}

/// Compare-clear one exact persistent-op11 terminal after semantic commit.
#[cfg(feature = "kernel")]
fn finish_cyw43_semantic_terminal_receipt_in_slot(
    slot: &DriverTaskCommandSlot,
    receipt: Cyw43SemanticTerminalReceipt,
) -> bool {
    if slot.semantic_terminal_request.load(Ordering::Acquire) != receipt.request
        || slot.semantic_terminal_fingerprint.load(Ordering::Relaxed) != receipt.command_fingerprint
        || slot.semantic_terminal_aux1.load(Ordering::Relaxed) != receipt.command_aux1
        || slot.semantic_terminal_pair_epoch.load(Ordering::Relaxed) != receipt.pair_epoch
    {
        return false;
    }
    if slot
        .semantic_terminal_request
        .compare_exchange(
            receipt.request,
            CYW43_SEMANTIC_TERMINAL_RETIRING,
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_err()
    {
        return false;
    }
    slot.semantic_terminal_fingerprint
        .store(0, Ordering::Relaxed);
    slot.semantic_terminal_aux1.store(0, Ordering::Relaxed);
    slot.semantic_terminal_pair_epoch
        .store(0, Ordering::Relaxed);
    slot.semantic_terminal_request.store(0, Ordering::Release);
    true
}

/// Compare-clear one exact persistent-op11 terminal after semantic commit.
#[cfg(feature = "kernel")]
pub(crate) fn finish_cyw43_semantic_terminal_receipt(
    receipt: Cyw43SemanticTerminalReceipt,
) -> bool {
    finish_cyw43_semantic_terminal_receipt_in_slot(&DRIVER_TASK_SLOT_CYW43455, receipt)
}

#[cfg(feature = "kernel")]
fn clear_cyw43_semantic_terminal_receipt() {
    let slot = &DRIVER_TASK_SLOT_CYW43455;
    slot.semantic_terminal_request.store(0, Ordering::Release);
    slot.semantic_terminal_fingerprint
        .store(0, Ordering::Relaxed);
    slot.semantic_terminal_aux1.store(0, Ordering::Relaxed);
    slot.semantic_terminal_pair_epoch
        .store(0, Ordering::Relaxed);
}

/// Close one exact pair-fenced terminal continuation authority.
///
/// The return value confirms that the caller retired the same generation and
/// immutable request that opened the exception. A semantic owner must treat a
/// mismatch as a pair-lifetime fault rather than silently continuing after a
/// different or already-cleared authority record.
#[cfg(feature = "kernel")]
pub(crate) fn finish_cyw43_pair_terminal_drain(generation: u32, request: u32) -> bool {
    cyw43_pair_terminal_drain_receipt(generation, request)
        .is_some_and(finish_cyw43_pair_terminal_drain_receipt)
}

/// Passively validate the stored pair-drain identity after the active slot has
/// been replaced by its terminal receipt.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_pair_terminal_drain_identity_matches(generation: u32, request: u32) -> bool {
    cyw43_pair_terminal_drain_receipt(generation, request).is_some()
}

/// Revoke any terminal-drain exception before deterministic pair teardown.
#[cfg(feature = "kernel")]
pub(crate) fn clear_cyw43_pair_terminal_drain() {
    clear_cyw43_semantic_terminal_receipt();
    CYW43_PAIR_TERMINAL_DRAIN_REQUEST.store(0, Ordering::Release);
    CYW43_PAIR_TERMINAL_DRAIN_GENERATION.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_FINGERPRINT.store(0, Ordering::Relaxed);
    CYW43_PAIR_TERMINAL_DRAIN_PAIR_EPOCH.store(0, Ordering::Relaxed);
}

/// Snapshot the exact root-owned continuation state without advancing it.
#[cfg(feature = "kernel")]
pub(crate) fn driver_task_retained_grant_snapshot(
    contract: DriverTaskContract,
) -> Option<DriverTaskRetainedGrantSnapshot> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let phase = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    );
    let state = active_driver_task_retained_request_for_slot(slot);
    let command = state.and_then(DriverTaskRetainedRequestState::command);
    let request = u32::try_from(slot.request_seq.load(Ordering::Acquire)).unwrap_or(0);
    let producer_grant_id = slot.retained_grant_id.load(Ordering::Acquire);
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    let command_sequence = (ring_root_ptr != 0)
        .then(|| DriverTaskRingView::new(ring_root_ptr))
        .flatten()
        .and_then(|ring| ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, sequence)))
        .unwrap_or(0);
    let grant = (ring_root_ptr != 0)
        .then(|| driver_task_ring_read_continuation_grant(ring_root_ptr))
        .flatten();
    let exact = command.zip(grant).is_some_and(|(command, grant)| {
        driver_task_continuation_grant_matches(grant, command, producer_grant_id)
    });
    Some(DriverTaskRetainedGrantSnapshot {
        active: slot.active.load(Ordering::Acquire) != 0,
        phase_name: phase.map_or("invalid", DriverTaskRetainedLeasePhase::as_str),
        priority_mask: slot.retained_priority_lease_mask.load(Ordering::Acquire),
        request,
        generation: command.map_or(0, |command| command.aux1),
        command_sequence,
        sequence_issued: slot.retained_doorbell_issued.load(Ordering::Acquire) != 0,
        root_notification_bound: slot.root_notification.load(Ordering::Acquire) != 0,
        producer_grant_id,
        shared_grant_id: grant.map_or(0, |grant| grant.grant_id),
        consumed_grant_id: grant.map_or(0, |grant| grant.consumed_grant_id),
        exact,
    })
}

/// Snapshot the complete immediate causal chain for one retained command.
#[cfg(feature = "kernel")]
pub(crate) fn driver_task_retained_frontier_snapshot(
    contract: DriverTaskContract,
) -> Option<DriverTaskRetainedFrontierSnapshot> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    driver_task_retained_frontier_snapshot_for_slot(task_key, slot)
}

/// Snapshot passive runtime cadence without advancing command or lease state.
#[cfg(feature = "kernel")]
pub(crate) fn driver_task_runtime_cadence_snapshot(
    contract: DriverTaskContract,
) -> Option<DriverRuntimeCadenceRecord> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    driver_task_ring_read_cadence_record(slot.ring_root_ptr.load(Ordering::Acquire))
}

/// Snapshot passive serial-owner RX/IRQ evidence without advancing its ring.
#[cfg(feature = "kernel")]
pub(crate) fn driver_task_serial_rx_state_snapshot() -> Option<DriverRuntimeSerialRxState> {
    let task_key = driver_task_contract_key(SERIAL_DRIVER_TASK_CONTRACT)?;
    let slot = slot_for_task_key(task_key)?;
    driver_task_ring_read_serial_rx_state(slot.ring_root_ptr.load(Ordering::Acquire))
}

#[cfg(feature = "kernel")]
fn driver_task_retained_frontier_snapshot_for_slot(
    task_key: usize,
    slot: &DriverTaskCommandSlot,
) -> Option<DriverTaskRetainedFrontierSnapshot> {
    let active = slot.active.load(Ordering::Acquire) != 0;
    let state = active.then(|| active_driver_task_retained_request_for_slot(slot));
    let request_state = match state.flatten() {
        Some(DriverTaskRetainedRequestState::Prepared { .. }) => "prepared",
        Some(DriverTaskRetainedRequestState::Issued { .. }) => "issued",
        Some(DriverTaskRetainedRequestState::Invalid { .. }) => "invalid",
        None if active => "unreadable",
        None => "inactive",
    };
    let phase_name = DriverTaskRetainedLeasePhase::from_usize(
        slot.retained_priority_lease_phase.load(Ordering::Acquire),
    )
    .map_or("invalid", DriverTaskRetainedLeasePhase::as_str);
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    let command_sequence = (ring_root_ptr != 0)
        .then(|| DriverTaskRingView::new(ring_root_ptr))
        .flatten()
        .and_then(|ring| ring.read_u32(core::mem::offset_of!(DriverTaskCommandRecord, sequence)))
        .unwrap_or(0);
    let completion_sequence = (ring_root_ptr != 0)
        .then(|| DriverTaskRingView::new(ring_root_ptr))
        .flatten()
        .and_then(|ring| ring.read_u32(DRIVER_TASK_RING_COMPLETION_OFFSET))
        .unwrap_or(0);
    let progress_magic = slot.last_progress_magic.load(Ordering::Acquire);
    let progress_phase = slot.last_progress_phase.load(Ordering::Acquire);
    let counters = slot.counters.snapshot(
        hot_path_for_task_key(task_key)?,
        slot.request_seq.load(Ordering::Acquire),
    );
    Some(DriverTaskRetainedFrontierSnapshot {
        active,
        request_state,
        phase_name,
        request: u32::try_from(slot.request_seq.load(Ordering::Acquire)).unwrap_or(0),
        command_sequence,
        completion_sequence,
        doorbell_issued: slot.retained_doorbell_issued.load(Ordering::Acquire) != 0,
        endpoint_bound: slot.endpoint.load(Ordering::Acquire) != 0,
        mcs_admission_open: slot.mcs_command_admission_open.load(Ordering::Acquire) != 0,
        mcs_cap_generation: slot.mcs_cap_generation.load(Ordering::Acquire),
        mcs_call_phase: slot.mcs_call_phase.load(Ordering::Acquire),
        mcs_producers: slot.mcs_nonblocking_root_producers.load(Ordering::Acquire),
        progress_valid: progress_magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
        progress_sequence: slot.last_progress_sequence.load(Ordering::Acquire),
        progress_phase,
        progress_phase_name: driver_task_ring_progress_phase_label(progress_phase),
        progress_aux0: slot.last_progress_aux0.load(Ordering::Acquire),
        send_attempts: counters.send_attempts,
        same_request_resumes: counters.same_request_resumes,
        timeouts: counters.timeouts,
        keep_active_timeouts: counters.keep_active_timeouts,
        aborts: counters.aborts,
    })
}

#[cfg(feature = "kernel")]
pub(crate) fn active_driver_task_ring_command(
    contract: DriverTaskContract,
) -> Option<DriverTaskCommandRecord> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    if slot.active.load(Ordering::Acquire) == 0 {
        return None;
    }
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        return None;
    }
    let request = slot.request_seq.load(Ordering::Acquire);
    if request == 0 {
        return None;
    }
    let command_ptr = ring_root_ptr as *const DriverTaskCommandRecord;
    // SAFETY: The ring root pointer was admitted by HAL and points to the
    // fixed command record at the start of the shared ring page.
    let command = unsafe { core::ptr::read_volatile(command_ptr) };
    (command.sequence == request as u32).then_some(command)
}

#[cfg(feature = "kernel")]
fn emit_driver_task_runtime_entry_status(
    contract: DriverTaskContract,
    task_key: usize,
    tcb: usize,
    status: &'static str,
    progress: DriverTaskRingProgressRecord,
) {
    let mut line = heapless::String::<320>::new();
    let _ = core::fmt::write(
        &mut line,
        format_args!(
            "DRIVER_TASK_RUNTIME_ENTRY contract={} task_key={} tcb=0x{:04x} status={} marker_valid={} marker_sequence={} marker_phase={} marker_phase_name={} marker_aux0=0x{:08x}",
            contract.name,
            task_key,
            tcb,
            status,
            if progress.magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC {
                "yes"
            } else {
                "no"
            },
            progress.sequence,
            progress.phase,
            driver_task_ring_progress_phase_label(progress.phase),
            progress.aux0,
        ),
    );
    crate::bootstrap::log::force_log_buffer_line_or_uart_without_prompt_refresh(line.as_str());
}

/// Wait for a linked runtime to enter its receive loop before descriptor replay.
#[cfg(feature = "kernel")]
#[must_use]
pub fn wait_for_driver_task_runtime_recv_ready(
    contract: DriverTaskContract,
    task_key: usize,
    spins: usize,
) -> bool {
    let mut deadline = driver_task_deadline_from_spins(spins);
    wait_for_driver_task_runtime_recv_ready_with_deadline(contract, task_key, spins, &mut deadline)
}

#[cfg(feature = "kernel")]
fn wait_for_driver_task_runtime_recv_ready_with_deadline(
    contract: DriverTaskContract,
    task_key: usize,
    poll_cap: usize,
    deadline: &mut DriverTaskDeadline,
) -> bool {
    let Some(slot) = slot_for_task_key(task_key) else {
        emit_driver_task_runtime_entry_status(
            contract,
            task_key,
            0,
            "invalid-task-key",
            DriverTaskRingProgressRecord {
                magic: 0,
                sequence: 0,
                phase: 0,
                aux0: 0,
            },
        );
        return false;
    };
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    let tcb = slot.tcb.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        emit_driver_task_runtime_entry_status(
            contract,
            task_key,
            tcb,
            "ring-missing",
            DriverTaskRingProgressRecord {
                magic: 0,
                sequence: 0,
                phase: 0,
                aux0: 0,
            },
        );
        return false;
    }
    let expected_aux0 = (task_key & u32::MAX as usize) as u32;
    let mut spin = 0usize;
    while spin < poll_cap && !driver_task_deadline_expired(deadline) {
        let progress = driver_task_ring_read_progress_record(ring_root_ptr);
        record_driver_task_ring_progress(slot, progress);
        if driver_task_runtime_progress_is_admission_ready(progress, expected_aux0) {
            emit_driver_task_runtime_entry_status(contract, task_key, tcb, "ready", progress);
            return true;
        }
        spin = spin.saturating_add(1);
        crate::sel4::yield_now();
    }
    let progress = driver_task_ring_read_progress_record(ring_root_ptr);
    record_driver_task_ring_progress(slot, progress);
    emit_driver_task_runtime_entry_status(contract, task_key, tcb, "timeout", progress);
    false
}

#[cfg(feature = "kernel")]
#[must_use]
const fn driver_task_runtime_progress_is_admission_ready(
    progress: DriverTaskRingProgressRecord,
    expected_aux0: u32,
) -> bool {
    progress.magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC
        && progress.sequence == 0
        && progress.aux0 == expected_aux0
        && matches!(
            progress.phase,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_RECV_READY
                | DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_POLL_READY
        )
}

#[cfg(feature = "kernel")]
pub(crate) fn driver_task_ring_command_active(contract: DriverTaskContract) -> bool {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    slot.active.load(Ordering::Acquire) != 0
}

/// Return the no-progress resume count for the contract's exact active ring
/// request. Zero means either no request is active or the current request has
/// not yet missed a completion fence.
#[cfg(feature = "kernel")]
pub(crate) fn driver_task_ring_active_timeout_resumes(contract: DriverTaskContract) -> usize {
    let Some(slot) = driver_task_slot_for_contract(contract) else {
        return 0;
    };
    if slot.active.load(Ordering::Acquire) == 0 {
        return 0;
    }
    slot.timeout_resumes.load(Ordering::Acquire)
}

#[cfg(feature = "kernel")]
fn observed_service_us_cell(contract: DriverTaskContract) -> Option<&'static AtomicU32> {
    match driver_task_contract_key(contract)? {
        DRIVER_TASK_KEY_SERIAL => Some(&DRIVER_TASK_OBSERVED_US_SERIAL),
        DRIVER_TASK_KEY_USB_LOCAL_SEAT => Some(&DRIVER_TASK_OBSERVED_US_USB_LOCAL_SEAT),
        DRIVER_TASK_KEY_HDMI_TEXT => Some(&DRIVER_TASK_OBSERVED_US_HDMI_TEXT),
        DRIVER_TASK_KEY_BCMGENET_V5 => Some(&DRIVER_TASK_OBSERVED_US_BCMGENET_V5),
        DRIVER_TASK_KEY_CYW43455 => Some(&DRIVER_TASK_OBSERVED_US_CYW43455),
        DRIVER_TASK_KEY_RTL8139 => Some(&DRIVER_TASK_OBSERVED_US_RTL8139),
        DRIVER_TASK_KEY_VIRTIO_NET => Some(&DRIVER_TASK_OBSERVED_US_VIRTIO_NET),
        DRIVER_TASK_KEY_SDIO_HOST => Some(&DRIVER_TASK_OBSERVED_US_SDIO_HOST),
        DRIVER_TASK_KEY_PCIE_ROOT => Some(&DRIVER_TASK_OBSERVED_US_PCIE_ROOT),
        _ => None,
    }
}

#[cfg(feature = "kernel")]
fn observed_service_us_for_contract(contract: DriverTaskContract) -> u32 {
    observed_service_us_cell(contract)
        .map(|cell| cell.load(Ordering::Acquire))
        .unwrap_or(0)
}

#[cfg(not(feature = "kernel"))]
const fn observed_service_us_for_contract(_contract: DriverTaskContract) -> u32 {
    0
}

#[must_use]
const fn driver_task_elapsed_us(start_ticks: u64, end_ticks: u64, counter_frequency: u64) -> u32 {
    if counter_frequency == 0 {
        return 1;
    }
    let delta = end_ticks.saturating_sub(start_ticks);
    let micros = (delta as u128)
        .saturating_mul(1_000_000u128)
        .saturating_div(counter_frequency as u128);
    if micros == 0 {
        1
    } else if micros > u32::MAX as u128 {
        u32::MAX
    } else {
        micros as u32
    }
}

#[cfg(feature = "kernel")]
fn record_observed_service_us(contract: DriverTaskContract, observed_us: u32) {
    let Some(cell) = observed_service_us_cell(contract) else {
        return;
    };
    let mut current = cell.load(Ordering::Acquire);
    while observed_us > current {
        match cell.compare_exchange(current, observed_us, Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => break,
            Err(next) => current = next,
        }
    }
}

#[cfg(feature = "kernel")]
#[inline]
fn driver_task_counter_frequency() -> Option<u64> {
    #[cfg(test)]
    if DRIVER_TASK_TEST_COUNTER_OVERRIDE_TICKS.with(|ticks| ticks.get().is_some()) {
        return Some(1_000_000);
    }
    #[cfg(all(target_arch = "aarch64", feature = "timers-arch-counter"))]
    {
        Some(timer_freq_hz())
    }
    #[cfg(all(target_arch = "aarch64", not(feature = "timers-arch-counter")))]
    {
        #[cfg(test)]
        if DRIVER_TASK_TEST_COUNTER_OVERRIDE_TICKS.with(|ticks| ticks.get().is_some()) {
            return Some(1_000_000);
        }
        None
    }
    #[cfg(not(target_arch = "aarch64"))]
    {
        Some(1_000_000)
    }
}

#[cfg(feature = "kernel")]
#[inline]
fn driver_task_counter_ticks() -> Option<u64> {
    #[cfg(test)]
    if let Some(tick) = DRIVER_TASK_TEST_COUNTER_OVERRIDE_TICKS.with(|ticks| {
        let tick = ticks.get()?;
        ticks.set(Some(tick.wrapping_add(1)));
        Some(tick)
    }) {
        return Some(tick);
    }
    #[cfg(all(target_arch = "aarch64", feature = "timers-arch-counter"))]
    {
        Some(timer_counter_ticks())
    }
    #[cfg(all(target_arch = "aarch64", not(feature = "timers-arch-counter")))]
    {
        #[cfg(test)]
        if let Some(tick) = DRIVER_TASK_TEST_COUNTER_OVERRIDE_TICKS.with(|ticks| {
            let tick = ticks.get()?;
            ticks.set(Some(tick.wrapping_add(1)));
            Some(tick)
        }) {
            return Some(tick);
        }
        None
    }
    #[cfg(not(target_arch = "aarch64"))]
    {
        Some(DRIVER_TASK_TEST_COUNTER_TICKS.fetch_add(1, Ordering::Relaxed))
    }
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
enum DriverTaskDeadline {
    Counter { start: u64, cycles: u64 },
    Iterations { remaining: usize },
}

#[cfg(feature = "kernel")]
fn driver_task_spins_to_cycles_at_hz(spins: usize, freq_hz: u64) -> u64 {
    if spins == 0 || freq_hz == 0 {
        return 0;
    }
    let cycles = (spins as u128)
        .saturating_mul(freq_hz as u128)
        .saturating_div(DRIVER_TASK_LEGACY_SPINS_PER_SECOND as u128);
    cycles.clamp(1, u64::MAX as u128) as u64
}

#[cfg(any(feature = "kernel", test))]
const fn driver_task_micros_to_cycles_at_hz(micros: u64, freq_hz: u64) -> u64 {
    if micros == 0 || freq_hz == 0 {
        return 0;
    }
    let numerator = (micros as u128).saturating_mul(freq_hz as u128);
    let cycles = numerator.saturating_add(999_999).saturating_div(1_000_000);
    if cycles > u64::MAX as u128 {
        u64::MAX
    } else if cycles == 0 {
        1
    } else {
        cycles as u64
    }
}

#[cfg(feature = "kernel")]
fn driver_task_deadline_from_spins(spins: usize) -> DriverTaskDeadline {
    match (driver_task_counter_ticks(), driver_task_counter_frequency()) {
        (Some(start), Some(freq_hz)) if start != 0 && freq_hz != 0 => {
            let cycles = driver_task_spins_to_cycles_at_hz(spins, freq_hz);
            if cycles == 0 {
                DriverTaskDeadline::Iterations { remaining: 0 }
            } else {
                DriverTaskDeadline::Counter { start, cycles }
            }
        }
        _ => DriverTaskDeadline::Iterations { remaining: spins },
    }
}

#[cfg(feature = "kernel")]
fn driver_task_deadline_expired(deadline: &mut DriverTaskDeadline) -> bool {
    match deadline {
        DriverTaskDeadline::Counter { start, cycles } => driver_task_counter_ticks()
            .map(|current| current.wrapping_sub(*start) >= *cycles)
            .unwrap_or(false),
        DriverTaskDeadline::Iterations { remaining } => {
            if *remaining == 0 {
                true
            } else {
                *remaining = (*remaining).saturating_sub(1);
                false
            }
        }
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_deadline_allows_attempt(deadline: Option<&mut DriverTaskDeadline>) -> bool {
    deadline.is_none_or(|deadline| !driver_task_deadline_expired(deadline))
}

/// Root-owned scheduling phase for a driver runtime.
///
/// Deferred CYW43/SDIO runtimes may leave bootstrap priority exactly once per
/// ready generation. `CutoverClaimed` fences a concurrent or duplicate caller
/// before the scheduler syscall, while `CutoverFailed` requires an explicit
/// pair transition back to `Bootstrap` before another cutover can be attempted.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(usize)]
enum DriverTaskSteadyPriorityState {
    Bootstrap,
    Active,
    CutoverClaimed,
    CutoverFailed,
}

#[cfg(feature = "kernel")]
impl DriverTaskSteadyPriorityState {
    const fn as_usize(self) -> usize {
        self as usize
    }

    const fn from_usize(value: usize) -> Option<Self> {
        match value {
            0 => Some(Self::Bootstrap),
            1 => Some(Self::Active),
            2 => Some(Self::CutoverClaimed),
            3 => Some(Self::CutoverFailed),
            _ => None,
        }
    }
}

#[cfg(feature = "kernel")]
fn driver_task_steady_priority_is_active(slot: &DriverTaskCommandSlot) -> bool {
    DriverTaskSteadyPriorityState::from_usize(slot.steady_priority_state.load(Ordering::Acquire))
        == Some(DriverTaskSteadyPriorityState::Active)
}

/// Return whether a linked runtime's claimed steady-priority transition failed.
///
/// This state is distinct from a precondition rejection: only a pair restart
/// may reset it to `Bootstrap` and authorize a later generation to claim the
/// scheduler syscall again.
#[cfg(feature = "kernel")]
#[must_use]
pub fn cyw43_sdio_pair_priority_cutover_failed(contract: DriverTaskContract) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT && contract != SDIO_HOST_DRIVER_TASK_CONTRACT {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    DriverTaskSteadyPriorityState::from_usize(slot.steady_priority_state.load(Ordering::Acquire))
        == Some(DriverTaskSteadyPriorityState::CutoverFailed)
}

/// Inject one post-claim scheduler failure for the selected linked runtime.
#[cfg(all(feature = "kernel", test))]
pub(crate) fn test_fail_next_cyw43_sdio_pair_priority_cutover(
    contract: DriverTaskContract,
) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT && contract != SDIO_HOST_DRIVER_TASK_CONTRACT {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    let tcb = slot.tcb.load(Ordering::Acquire);
    if tcb == 0 {
        return false;
    }
    DRIVER_TASK_TEST_STEADY_PRIORITY_CUTOVER_FAILURE_TCB.store(tcb, Ordering::Release);
    true
}

#[cfg(feature = "kernel")]
fn reset_driver_task_steady_priority_for_bootstrap(slot: &DriverTaskCommandSlot) {
    slot.steady_priority_state.store(
        DriverTaskSteadyPriorityState::Bootstrap.as_usize(),
        Ordering::Release,
    );
}

#[cfg(feature = "kernel")]
fn claim_driver_task_steady_priority_cutover(slot: &DriverTaskCommandSlot) -> bool {
    slot.steady_priority_state
        .compare_exchange(
            DriverTaskSteadyPriorityState::Bootstrap.as_usize(),
            DriverTaskSteadyPriorityState::CutoverClaimed.as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

#[cfg(feature = "kernel")]
fn resolve_driver_task_steady_priority_cutover(
    slot: &DriverTaskCommandSlot,
    succeeded: bool,
) -> bool {
    slot.steady_priority_state
        .compare_exchange(
            DriverTaskSteadyPriorityState::CutoverClaimed.as_usize(),
            if succeeded {
                DriverTaskSteadyPriorityState::Active
            } else {
                DriverTaskSteadyPriorityState::CutoverFailed
            }
            .as_usize(),
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_ok()
}

/// Publish the TCB cap and steady priority backing one driver task.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_scheduler(
    contract: DriverTaskContract,
    tcb: usize,
    steady_priority: u8,
) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.tcb.store(tcb, Ordering::Release);
    slot.steady_priority
        .store(usize::from(steady_priority), Ordering::Release);
    reset_driver_task_steady_priority_for_bootstrap(slot);
}

const DRIVER_TASK_MCS_CALL_IDLE: u32 = 0;
const DRIVER_TASK_MCS_CALL_ASSOCIATED: u32 = 1;
const DRIVER_TASK_MCS_CALL_FAULT_PUBLISHED: u32 = 2;
const DRIVER_TASK_MCS_CALL_FAILURE_REPLIED: u32 = 3;
const DRIVER_TASK_MCS_CALL_SUSPENDED: u32 = 4;
const DRIVER_TASK_MCS_CALL_ASSOCIATIONS_CLEAR: u32 = 5;
const DRIVER_TASK_MCS_CALL_REVOKED: u32 = 6;

/// Publish the root-driver-supervisor's retained MCS containment authority.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
#[allow(
    clippy::too_many_arguments,
    reason = "the arguments mirror the fixed per-runtime MCS capability inventory"
)]
pub fn publish_driver_task_mcs_kernel_objects(
    contract: DriverTaskContract,
    command_endpoint_origin: usize,
    command_reply: usize,
    completion_notification_origin: usize,
    sched_context: usize,
    standard_fault_endpoint: usize,
    timeout_fault_endpoint: usize,
) -> bool {
    if command_endpoint_origin == 0
        || command_reply == 0
        || completion_notification_origin == 0
        || sched_context == 0
        || standard_fault_endpoint == 0
        || timeout_fault_endpoint == 0
    {
        return false;
    }
    let Some(slot) = driver_task_slot_for_contract(contract) else {
        return false;
    };
    if slot.mcs_nonblocking_root_producers.load(Ordering::Acquire) != 0 {
        return false;
    }
    let generation = slot
        .mcs_cap_generation
        .load(Ordering::Acquire)
        .wrapping_add(1)
        .max(1);
    slot.mcs_command_endpoint_origin
        .store(command_endpoint_origin, Ordering::Relaxed);
    slot.mcs_command_reply
        .store(command_reply, Ordering::Relaxed);
    slot.mcs_completion_notification_origin
        .store(completion_notification_origin, Ordering::Relaxed);
    slot.mcs_sched_context
        .store(sched_context, Ordering::Relaxed);
    slot.mcs_standard_fault_endpoint
        .store(standard_fault_endpoint, Ordering::Relaxed);
    slot.mcs_timeout_fault_endpoint
        .store(timeout_fault_endpoint, Ordering::Relaxed);
    slot.mcs_supervisor_tcb.store(0, Ordering::Relaxed);
    slot.mcs_supervisor_authority_ready
        .store(0, Ordering::Relaxed);
    slot.mcs_call_sequence.store(0, Ordering::Relaxed);
    slot.mcs_call_phase
        .store(DRIVER_TASK_MCS_CALL_IDLE, Ordering::Relaxed);
    slot.mcs_command_admission_open.store(1, Ordering::Relaxed);
    slot.mcs_producer_drain_reported
        .store(MCS_PRODUCER_DRAIN_UNREPORTED, Ordering::Relaxed);
    slot.mcs_cap_generation.store(generation, Ordering::Release);
    true
}

/// Publish the exact child-local capability row after root has transferred
/// every retained origin into the restricted driver-supervisor CSpace.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn publish_driver_task_supervisor_authority(
    contract: DriverTaskContract,
    caps: crate::hal::critical_tcb::DriverSupervisorRuntimeLocalCaps,
) -> bool {
    if [
        caps.tcb,
        caps.command_endpoint_origin,
        caps.command_reply,
        caps.completion_notification_origin,
        caps.sched_context,
        caps.standard_fault_endpoint,
        caps.timeout_fault_endpoint,
    ]
    .contains(&sel4_sys::seL4_CapNull)
    {
        return false;
    }
    let Some(slot) = driver_task_slot_for_contract(contract) else {
        return false;
    };
    if slot.mcs_cap_generation.load(Ordering::Acquire) == 0
        || slot.mcs_supervisor_authority_ready.load(Ordering::Acquire) != 0
    {
        return false;
    }
    slot.mcs_supervisor_tcb
        .store(caps.tcb as usize, Ordering::Relaxed);
    slot.mcs_command_endpoint_origin
        .store(caps.command_endpoint_origin as usize, Ordering::Relaxed);
    slot.mcs_command_reply
        .store(caps.command_reply as usize, Ordering::Relaxed);
    slot.mcs_completion_notification_origin.store(
        caps.completion_notification_origin as usize,
        Ordering::Relaxed,
    );
    slot.mcs_sched_context
        .store(caps.sched_context as usize, Ordering::Relaxed);
    slot.mcs_standard_fault_endpoint
        .store(caps.standard_fault_endpoint as usize, Ordering::Relaxed);
    slot.mcs_timeout_fault_endpoint
        .store(caps.timeout_fault_endpoint as usize, Ordering::Relaxed);
    slot.mcs_supervisor_authority_ready
        .store(1, Ordering::Release);
    true
}

/// Return the retained capability generation for one published MCS runtime.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn driver_task_mcs_cap_generation(contract: DriverTaskContract) -> Option<u32> {
    let generation = driver_task_slot_for_contract(contract)?
        .mcs_cap_generation
        .load(Ordering::Acquire);
    (generation != 0).then_some(generation)
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn begin_driver_task_mcs_call(slot: &DriverTaskCommandSlot, sequence: u32) -> bool {
    sequence != 0
        && slot.mcs_command_admission_open.load(Ordering::Acquire) != 0
        && slot
            .mcs_call_phase
            .compare_exchange(
                DRIVER_TASK_MCS_CALL_IDLE,
                DRIVER_TASK_MCS_CALL_ASSOCIATED,
                Ordering::AcqRel,
                Ordering::Acquire,
            )
            .is_ok()
        && {
            slot.mcs_call_sequence.store(sequence, Ordering::Release);
            true
        }
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn finish_driver_task_mcs_normal_reply(slot: &DriverTaskCommandSlot, sequence: u32) -> bool {
    if slot.mcs_call_sequence.load(Ordering::Acquire) != sequence {
        return false;
    }
    if slot
        .mcs_call_phase
        .compare_exchange(
            DRIVER_TASK_MCS_CALL_ASSOCIATED,
            DRIVER_TASK_MCS_CALL_IDLE,
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .is_err()
    {
        return false;
    }
    slot.mcs_call_sequence.store(0, Ordering::Release);
    slot.mcs_normal_replies.fetch_add(1, Ordering::AcqRel);
    true
}

/// Driver-supervisor containment failure.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DriverSupervisorContainmentError {
    UnsupportedScheduler,
    UnknownRuntimeSlot,
    IdentityMismatch,
    FaultBadgeMismatch,
    RootProducerActive,
    DuplicateOrOutOfOrder,
    MissingAuthority,
    Kernel(sel4_sys::seL4_Error),
}

const DRIVER_SUPERVISOR_DIAG_EMPTY: u8 = 0;
const DRIVER_SUPERVISOR_DIAG_CONTAINING: u8 = 1;
const DRIVER_SUPERVISOR_DIAG_COMPLETE: u8 = 2;
const DRIVER_SUPERVISOR_DIAG_FAILED: u8 = 3;
const DRIVER_SUPERVISOR_DIAG_DEFERRED: u8 = 4;

const DRIVER_SUPERVISOR_DIAG_STAGE_IDENTITY: u8 = 1;
const DRIVER_SUPERVISOR_DIAG_STAGE_BADGE: u8 = 2;
const DRIVER_SUPERVISOR_DIAG_STAGE_PHASE: u8 = 3;
const DRIVER_SUPERVISOR_DIAG_STAGE_REPLY: u8 = 4;
const DRIVER_SUPERVISOR_DIAG_STAGE_SUSPEND: u8 = 5;
const DRIVER_SUPERVISOR_DIAG_STAGE_UNBIND: u8 = 6;
const DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_COMMAND: u8 = 7;
const DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_REPLY: u8 = 8;
const DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_COMPLETION: u8 = 9;
const DRIVER_SUPERVISOR_DIAG_STAGE_DELETE_STANDARD: u8 = 10;
const DRIVER_SUPERVISOR_DIAG_STAGE_DELETE_TIMEOUT: u8 = 11;
const DRIVER_SUPERVISOR_DIAG_STAGE_DONE: u8 = 12;
const DRIVER_SUPERVISOR_DIAG_STAGE_PRODUCER_DRAIN: u8 = 13;

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
#[derive(Clone, Copy, Debug)]
struct DriverSupervisorFaultDiagnostic {
    record: crate::critical_tcb::FaultHandoffRecord,
    contract: DriverTaskContract,
    local_tcb: usize,
    local_sc: usize,
    ipc_buffer_vaddr: usize,
    prior_call_phase: u32,
    stage: u8,
    kernel_error: isize,
    state: u8,
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
impl DriverSupervisorFaultDiagnostic {
    const fn empty() -> Self {
        Self {
            record: crate::critical_tcb::FaultHandoffRecord {
                sequence: 0,
                task_index: 0,
                identity: crate::critical_tcb::GenerationIdentity {
                    slot: 0,
                    lease_epoch: 0,
                    supervisor_generation: 0,
                    cap_generation: 0,
                },
                fault_badge: 0,
                fault_class: crate::critical_tcb::FaultClass::Standard,
                fault_label: 0,
                fault_length: 0,
                fault_mr0: 0,
                fault_mr1: 0,
                tcb_cap: 0,
            },
            contract: SERIAL_DRIVER_TASK_CONTRACT,
            local_tcb: 0,
            local_sc: 0,
            ipc_buffer_vaddr: 0,
            prior_call_phase: 0,
            stage: 0,
            kernel_error: 0,
            state: DRIVER_SUPERVISOR_DIAG_EMPTY,
        }
    }
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
static DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC: spin::Mutex<DriverSupervisorFaultDiagnostic> =
    spin::Mutex::new(DriverSupervisorFaultDiagnostic::empty());

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn begin_driver_supervisor_fault_diagnostic(
    record: crate::critical_tcb::FaultHandoffRecord,
    contract: DriverTaskContract,
    local_tcb: usize,
    local_sc: usize,
    ipc_buffer_vaddr: usize,
    prior_call_phase: u32,
) -> bool {
    let mut diagnostic = DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.lock();
    let resumed_after_producer_drain = diagnostic.record.sequence == record.sequence
        && diagnostic.contract == contract
        && diagnostic.state == DRIVER_SUPERVISOR_DIAG_DEFERRED
        && diagnostic.stage == DRIVER_SUPERVISOR_DIAG_STAGE_PRODUCER_DRAIN;
    *diagnostic = DriverSupervisorFaultDiagnostic {
        record,
        contract,
        local_tcb,
        local_sc,
        ipc_buffer_vaddr,
        prior_call_phase,
        stage: DRIVER_SUPERVISOR_DIAG_STAGE_IDENTITY,
        kernel_error: 0,
        state: DRIVER_SUPERVISOR_DIAG_CONTAINING,
    };
    resumed_after_producer_drain
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn defer_driver_supervisor_fault_diagnostic() {
    let mut diagnostic = DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.lock();
    diagnostic.stage = DRIVER_SUPERVISOR_DIAG_STAGE_PRODUCER_DRAIN;
    diagnostic.state = DRIVER_SUPERVISOR_DIAG_DEFERRED;
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn complete_driver_supervisor_fault_diagnostic() {
    let mut diagnostic = DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.lock();
    diagnostic.stage = DRIVER_SUPERVISOR_DIAG_STAGE_DONE;
    diagnostic.state = DRIVER_SUPERVISOR_DIAG_COMPLETE;
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn fail_driver_supervisor_fault_diagnostic(
    stage: u8,
    error: DriverSupervisorContainmentError,
) -> DriverSupervisorContainmentError {
    let mut diagnostic = DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.lock();
    diagnostic.stage = stage;
    diagnostic.kernel_error = match error {
        DriverSupervisorContainmentError::Kernel(kernel_error) => kernel_error as isize,
        _ => 0,
    };
    diagnostic.state = DRIVER_SUPERVISOR_DIAG_FAILED;
    error
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
fn driver_supervisor_fault_diagnostic_state(contract: DriverTaskContract) -> (u64, u8, u8, isize) {
    let Some(diagnostic) = DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.try_lock() else {
        return (0, DRIVER_SUPERVISOR_DIAG_CONTAINING, 0, 0);
    };
    if diagnostic.contract != contract {
        return (0, DRIVER_SUPERVISOR_DIAG_EMPTY, 0, 0);
    }
    (
        diagnostic.record.sequence,
        diagnostic.state,
        diagnostic.stage,
        diagnostic.kernel_error,
    )
}

#[cfg(all(feature = "kernel", not(sel4_config_kernel_mcs)))]
const fn driver_supervisor_fault_diagnostic_state(
    _contract: DriverTaskContract,
) -> (u64, u8, u8, isize) {
    (0, 0, 0, 0)
}

/// Format one stable, terminal driver fault/containment record for root-control.
/// The caller advances `after_sequence` only after it has retained the line.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn driver_supervisor_fault_diagnostic_line(
    after_sequence: u64,
) -> Option<(u64, heapless::String<256>)> {
    let diagnostic = *DRIVER_SUPERVISOR_FAULT_DIAGNOSTIC.try_lock()?;
    if diagnostic.record.sequence <= after_sequence
        || !matches!(
            diagnostic.state,
            DRIVER_SUPERVISOR_DIAG_COMPLETE | DRIVER_SUPERVISOR_DIAG_FAILED
        )
    {
        return None;
    }
    let class = match diagnostic.record.fault_class {
        crate::critical_tcb::FaultClass::Standard => "standard",
        crate::critical_tcb::FaultClass::Timeout => "timeout",
    };
    let mut line = heapless::String::<256>::new();
    let result = if diagnostic.state == DRIVER_SUPERVISOR_DIAG_COMPLETE {
        "ok"
    } else {
        "fail"
    };
    core::fmt::write(
        &mut line,
        format_args!(
            "DRIVER_FAULT_CONTAINMENT v1 q={:x} task={} c={} l={:x}/{} b={:x} m0={:x} m1={:x} t={:x} sc={:x} ipc={:x} p={:x} res={} st={:x} e={:x}",
            diagnostic.record.sequence,
            diagnostic.contract.name,
            class,
            diagnostic.record.fault_label,
            diagnostic.record.fault_length,
            diagnostic.record.fault_badge,
            diagnostic.record.fault_mr0,
            diagnostic.record.fault_mr1,
            diagnostic.local_tcb,
            diagnostic.local_sc,
            diagnostic.ipc_buffer_vaddr,
            diagnostic.prior_call_phase,
            result,
            diagnostic.stage,
            diagnostic.kernel_error,
        ),
    )
    .ok()?;
    Some((diagnostic.record.sequence, line))
}

/// Classic-kernel builds have no MCS driver fault-containment record.
#[cfg(all(feature = "kernel", not(sel4_config_kernel_mcs)))]
pub fn driver_supervisor_fault_diagnostic_line(
    _after_sequence: u64,
) -> Option<(u64, heapless::String<256>)> {
    None
}

#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn driver_contract_for_runtime_slot(runtime_slot: u16) -> Option<DriverTaskContract> {
    match runtime_slot {
        0 => Some(SERIAL_DRIVER_TASK_CONTRACT),
        1 => Some(USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT),
        2 => Some(HDMI_TEXT_DRIVER_TASK_CONTRACT),
        3 => Some(GENET_DRIVER_TASK_CONTRACT),
        4 => Some(CYW43_WIFI_DRIVER_TASK_CONTRACT),
        5 => Some(SDIO_HOST_DRIVER_TASK_CONTRACT),
        6 => Some(PCIE_ROOT_DRIVER_TASK_CONTRACT),
        _ => None,
    }
}

/// Return the exact generated fault-registry slot for one linked runtime.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn driver_runtime_registry_slot(contract: DriverTaskContract) -> Option<u16> {
    (0..crate::critical_tcb::DRIVER_FAULT_RECORD_CAPACITY as u16)
        .find(|slot| driver_contract_for_runtime_slot(*slot) == Some(contract))
}

/// Contain one durable root-fault handoff on the independent driver supervisor.
///
/// This hook is bounded and nonblocking: it closes admission, answers at most
/// one associated command caller, suspends the driver to clear its independent
/// fault association, unbinds the active SC, then revokes every derived
/// per-generation command/completion capability. Reconstruction is a later
/// supervisor turn and cannot overlap this old generation.
#[cfg(all(feature = "kernel", sel4_config_kernel_mcs))]
pub fn root_driver_supervisor_contain_fault(
    record: crate::critical_tcb::FaultHandoffRecord,
    ipc_buffer_vaddr: usize,
) -> Result<(), DriverSupervisorContainmentError> {
    let contract = driver_contract_for_runtime_slot(record.identity.slot)
        .ok_or(DriverSupervisorContainmentError::UnknownRuntimeSlot)?;
    let slot = driver_task_slot_for_contract(contract)
        .ok_or(DriverSupervisorContainmentError::UnknownRuntimeSlot)?;
    let root_tcb = slot.tcb.load(Ordering::Acquire);
    let supervisor_tcb = slot.mcs_supervisor_tcb.load(Ordering::Acquire);
    let supervisor_reply = slot.mcs_command_reply.load(Ordering::Acquire);
    let supervisor_sc = slot.mcs_sched_context.load(Ordering::Acquire);
    let prior = slot.mcs_call_phase.load(Ordering::Acquire);
    let resumed_after_producer_drain = begin_driver_supervisor_fault_diagnostic(
        record,
        contract,
        supervisor_tcb,
        supervisor_sc,
        ipc_buffer_vaddr,
        prior,
    );
    if root_tcb == 0
        || supervisor_tcb == 0
        || ipc_buffer_vaddr == 0
        || slot.mcs_supervisor_authority_ready.load(Ordering::Acquire) == 0
        || record.tcb_cap != root_tcb
        || record.identity.cap_generation != slot.mcs_cap_generation.load(Ordering::Acquire)
    {
        return Err(fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_IDENTITY,
            DriverSupervisorContainmentError::IdentityMismatch,
        ));
    }
    let expected_badge = match record.fault_class {
        crate::critical_tcb::FaultClass::Standard => {
            let spec = pi4_driver_task_runtime_image_spec_for_contract(contract)
                .ok_or(DriverSupervisorContainmentError::IdentityMismatch)?;
            let temporal = driver_task_temporal_config(spec.hot_path)
                .ok_or(DriverSupervisorContainmentError::IdentityMismatch)?;
            crate::hal::critical_tcb::temporal_fault_badges(temporal.id)
                .map(|badges| badges.0)
                .ok_or(DriverSupervisorContainmentError::IdentityMismatch)?
        }
        crate::critical_tcb::FaultClass::Timeout => {
            let spec = pi4_driver_task_runtime_image_spec_for_contract(contract)
                .ok_or(DriverSupervisorContainmentError::IdentityMismatch)?;
            driver_task_temporal_config(spec.hot_path)
                .ok_or(DriverSupervisorContainmentError::IdentityMismatch)?
                .timeout_badge
        }
    };
    if record.fault_badge != expected_badge {
        return Err(fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_BADGE,
            DriverSupervisorContainmentError::FaultBadgeMismatch,
        ));
    }
    slot.mcs_command_admission_open.store(0, Ordering::Release);
    // Root must lose the published send CPtr before the supervisor can revoke
    // its retained origin. Keeping a stale nonzero CPtr until the end of the
    // containment sequence lets any later-stage failure turn every display or
    // service retry into an unbounded null-cap syscall loop.
    slot.endpoint.store(0, Ordering::Release);
    if slot.mcs_nonblocking_root_producers.load(Ordering::Acquire) != 0 {
        defer_driver_supervisor_fault_diagnostic();
        return Err(DriverSupervisorContainmentError::RootProducerActive);
    }
    if resumed_after_producer_drain {
        slot.mcs_producer_drain_reported
            .store(MCS_PRODUCER_DRAIN_CONTAINMENT_RESUMED, Ordering::Release);
    }
    if prior != DRIVER_TASK_MCS_CALL_IDLE && prior != DRIVER_TASK_MCS_CALL_ASSOCIATED {
        return Err(fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_PHASE,
            DriverSupervisorContainmentError::DuplicateOrOutOfOrder,
        ));
    }
    slot.mcs_call_phase
        .compare_exchange(
            prior,
            DRIVER_TASK_MCS_CALL_FAULT_PUBLISHED,
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .map_err(|_| {
            fail_driver_supervisor_fault_diagnostic(
                DRIVER_SUPERVISOR_DIAG_STAGE_PHASE,
                DriverSupervisorContainmentError::DuplicateOrOutOfOrder,
            )
        })?;

    if prior == DRIVER_TASK_MCS_CALL_ASSOCIATED {
        if supervisor_reply == 0 || slot.mcs_call_sequence.load(Ordering::Acquire) == 0 {
            return Err(fail_driver_supervisor_fault_diagnostic(
                DRIVER_SUPERVISOR_DIAG_STAGE_REPLY,
                DriverSupervisorContainmentError::MissingAuthority,
            ));
        }
        crate::sel4::reply_to(
            supervisor_reply as sel4_sys::seL4_CPtr,
            sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1),
            [
                pi4_driver_abi::DRIVER_RUNTIME_MCS_FAULTED_CALL_RESULT as sel4_sys::seL4_Word,
                0,
                0,
                0,
            ],
        );
        slot.mcs_failure_replies.fetch_add(1, Ordering::AcqRel);
    }
    slot.mcs_call_sequence.store(0, Ordering::Release);
    slot.mcs_call_phase
        .store(DRIVER_TASK_MCS_CALL_FAILURE_REPLIED, Ordering::Release);

    crate::sel4::suspend_tcb(supervisor_tcb as sel4_sys::seL4_CPtr).map_err(|error| {
        fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_SUSPEND,
            DriverSupervisorContainmentError::Kernel(error),
        )
    })?;
    slot.mcs_call_phase
        .store(DRIVER_TASK_MCS_CALL_SUSPENDED, Ordering::Release);
    if supervisor_sc == 0 {
        return Err(fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_UNBIND,
            DriverSupervisorContainmentError::MissingAuthority,
        ));
    }
    crate::sel4::unbind_sched_context_object(
        supervisor_sc as sel4_sys::seL4_CPtr,
        supervisor_tcb as sel4_sys::seL4_CPtr,
        Some(ipc_buffer_vaddr),
    )
    .map_err(|error| {
        fail_driver_supervisor_fault_diagnostic(
            DRIVER_SUPERVISOR_DIAG_STAGE_UNBIND,
            DriverSupervisorContainmentError::Kernel(error),
        )
    })?;
    slot.mcs_call_phase
        .store(DRIVER_TASK_MCS_CALL_ASSOCIATIONS_CLEAR, Ordering::Release);

    for (cap, stage) in [
        (
            slot.mcs_command_endpoint_origin.load(Ordering::Acquire),
            DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_COMMAND,
        ),
        (
            slot.mcs_command_reply.load(Ordering::Acquire),
            DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_REPLY,
        ),
        (
            slot.mcs_completion_notification_origin
                .load(Ordering::Acquire),
            DRIVER_SUPERVISOR_DIAG_STAGE_REVOKE_COMPLETION,
        ),
    ] {
        if cap == 0 {
            return Err(fail_driver_supervisor_fault_diagnostic(
                stage,
                DriverSupervisorContainmentError::MissingAuthority,
            ));
        }
        let error = crate::hal::critical_tcb::driver_supervisor_revoke_local_cap(
            cap as sel4_sys::seL4_CPtr,
        );
        if error != sel4_sys::seL4_NoError {
            return Err(fail_driver_supervisor_fault_diagnostic(
                stage,
                DriverSupervisorContainmentError::Kernel(error),
            ));
        }
    }
    for (cap, stage) in [
        (
            slot.mcs_standard_fault_endpoint.load(Ordering::Acquire),
            DRIVER_SUPERVISOR_DIAG_STAGE_DELETE_STANDARD,
        ),
        (
            slot.mcs_timeout_fault_endpoint.load(Ordering::Acquire),
            DRIVER_SUPERVISOR_DIAG_STAGE_DELETE_TIMEOUT,
        ),
    ] {
        if cap == 0 {
            return Err(fail_driver_supervisor_fault_diagnostic(
                stage,
                DriverSupervisorContainmentError::MissingAuthority,
            ));
        }
        let error = crate::hal::critical_tcb::driver_supervisor_delete_local_cap(
            cap as sel4_sys::seL4_CPtr,
        );
        if error != sel4_sys::seL4_NoError {
            return Err(fail_driver_supervisor_fault_diagnostic(
                stage,
                DriverSupervisorContainmentError::Kernel(error),
            ));
        }
    }
    slot.mcs_call_phase
        .store(DRIVER_TASK_MCS_CALL_REVOKED, Ordering::Release);
    complete_driver_supervisor_fault_diagnostic();
    Ok(())
}

/// Classic kernels cannot consume the MCS driver-supervisor hook.
#[cfg(all(feature = "kernel", not(sel4_config_kernel_mcs)))]
pub fn root_driver_supervisor_contain_fault(
    _record: crate::critical_tcb::FaultHandoffRecord,
    _ipc_buffer_vaddr: usize,
) -> Result<(), DriverSupervisorContainmentError> {
    Err(DriverSupervisorContainmentError::UnsupportedScheduler)
}

/// Retain the manifest-derived context required for a fenced CYW43/SDIO pair restart.
///
/// The endpoint cap is recovery-only: normal SDIO handoff still removes root's
/// published producer cap, and this retained cap is exposed only while both
/// linked runtime TCBs are suspended under the pair-restart gate. The original
/// notification cap remains the TCB-bind authority. Retained foreground
/// quanta use exact generation grants plus the typed SDIO-owner notification.
#[cfg(feature = "kernel")]
fn cyw43_sdio_restart_irq_handlers_valid(
    contract: DriverTaskContract,
    irq_handlers: [usize; 2],
) -> bool {
    if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT {
        irq_handlers[0] == 0 && irq_handlers[1] == 0
    } else if contract == SDIO_HOST_DRIVER_TASK_CONTRACT {
        irq_handlers[0] != 0 && irq_handlers[1] != 0 && irq_handlers[0] != irq_handlers[1]
    } else {
        false
    }
}

#[cfg(feature = "kernel")]
pub fn publish_cyw43_sdio_restart_context(
    contract: DriverTaskContract,
    entry: usize,
    stack_top: usize,
    task_key: usize,
    recovery_endpoint: usize,
    normal_endpoint: usize,
    notification: usize,
    irq_handlers: [usize; 2],
    sdhci_root_ptr: usize,
) -> bool {
    if (contract != CYW43_WIFI_DRIVER_TASK_CONTRACT && contract != SDIO_HOST_DRIVER_TASK_CONTRACT)
        || entry == 0
        || stack_top == 0
        || recovery_endpoint == 0
        || normal_endpoint == 0
        || notification == 0
        || driver_task_contract_key(contract) != Some(task_key)
        || (contract == SDIO_HOST_DRIVER_TASK_CONTRACT && sdhci_root_ptr == 0)
        || !cyw43_sdio_restart_irq_handlers_valid(contract, irq_handlers)
    {
        return false;
    }
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    slot.restart_entry.store(entry, Ordering::Release);
    slot.restart_stack_top.store(stack_top, Ordering::Release);
    slot.restart_task_key.store(task_key, Ordering::Release);
    slot.restart_endpoint
        .store(recovery_endpoint, Ordering::Release);
    slot.restart_normal_endpoint
        .store(normal_endpoint, Ordering::Release);
    slot.restart_notification
        .store(notification, Ordering::Release);
    slot.restart_notification_bound.store(1, Ordering::Release);
    slot.restart_irq_handler
        .store(irq_handlers[0], Ordering::Release);
    slot.restart_dma_irq_handler
        .store(irq_handlers[1], Ordering::Release);
    slot.restart_sdhci_root_ptr
        .store(sdhci_root_ptr, Ordering::Release);
    true
}

/// Mark that one driver task has left bootstrap priority and is in steady state.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_steady_priority_active(contract: DriverTaskContract) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.steady_priority_state.store(
        DriverTaskSteadyPriorityState::Active.as_usize(),
        Ordering::Release,
    );
}

/// Move one deferred CYW43/SDIO runtime back to its shell-safe bootstrap priority.
///
/// Pair recovery invokes this as a retained operation while the target TCB is
/// suspended. The following outer turn programs or resumes the runtime; the
/// transition is never combined with a ring submission.
#[cfg(feature = "kernel")]
pub fn transition_deferred_cyw43_pair_to_bootstrap_priority(contract: DriverTaskContract) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT && contract != SDIO_HOST_DRIVER_TASK_CONTRACT {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    let tcb = slot.tcb.load(Ordering::Acquire);
    if tcb == 0 {
        return false;
    }
    let priority = driver_task_bootstrap_priority(contract);
    #[cfg(sel4_config_kernel_mcs)]
    let _ = priority;
    #[cfg(not(sel4_config_kernel_mcs))]
    if crate::sel4::set_tcb_sched_params(
        tcb as sel4_sys::seL4_CPtr,
        sel4_sys::seL4_CapInitThreadTCB,
        priority,
        priority,
    )
    .is_err()
    {
        return false;
    }
    slot.retained_priority_boost_active
        .store(0, Ordering::Release);
    reset_driver_task_retained_priority_lease_slot(slot);
    reset_driver_task_steady_priority_for_bootstrap(slot);
    true
}

/// Complete one deferred CYW43/SDIO runtime's priority cutover.
///
/// The retained supervisor invokes this only after descriptor replay, engine
/// initialization, firmware/core release, and control-plane setup have all
/// completed. Keeping the shared-core pair at priority 255 through those
/// multi-phase operations avoids depending on an unproved dynamic boost while
/// either runtime still owns bootstrap state; steady priorities begin only at
/// the ready-generation boundary.
#[cfg(feature = "kernel")]
pub fn complete_deferred_cyw43_pair_priority_cutover(contract: DriverTaskContract) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT && contract != SDIO_HOST_DRIVER_TASK_CONTRACT {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    let tcb = slot.tcb.load(Ordering::Acquire);
    let steady_priority = slot.steady_priority.load(Ordering::Acquire);
    if tcb == 0
        || steady_priority == 0
        || slot.retained_priority_boost_active.load(Ordering::Acquire) != 0
    {
        return false;
    }
    let Ok(steady_priority) = u8::try_from(steady_priority) else {
        return false;
    };
    #[cfg(sel4_config_kernel_mcs)]
    let _ = steady_priority;
    if !claim_driver_task_steady_priority_cutover(slot) {
        return false;
    }
    #[cfg(test)]
    if DRIVER_TASK_TEST_STEADY_PRIORITY_CUTOVER_FAILURE_TCB
        .compare_exchange(tcb, 0, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
    {
        let _ = resolve_driver_task_steady_priority_cutover(slot, false);
        return false;
    }
    #[cfg(not(sel4_config_kernel_mcs))]
    if crate::sel4::set_tcb_sched_params(
        tcb as sel4_sys::seL4_CPtr,
        sel4_sys::seL4_CapInitThreadTCB,
        steady_priority,
        steady_priority,
    )
    .is_err()
    {
        let _ = resolve_driver_task_steady_priority_cutover(slot, false);
        return false;
    }
    resolve_driver_task_steady_priority_cutover(slot, true)
}

/// Publish the root-side command endpoint for a created driver TCB.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_command_endpoint(contract: DriverTaskContract, endpoint: usize) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    let expected_ident = if physical_driver_endpoint_identify_available() {
        crate::sel4::debug_cap_identify(endpoint as sel4_sys::seL4_CPtr) as usize
    } else {
        0
    };
    slot.endpoint_expected_ident
        .store(expected_ident, Ordering::Relaxed);
    slot.endpoint_lifetime_probes.store(0, Ordering::Relaxed);
    slot.endpoint_lifetime_failure.store(0, Ordering::Relaxed);
    slot.endpoint.store(endpoint, Ordering::Release);
    if contract == HDMI_TEXT_DRIVER_TASK_CONTRACT && expected_ident != 0 {
        emit_driver_task_endpoint_lifetime_checkpoint(contract, "publish");
    }
}

const DRIVER_TASK_ENDPOINT_LIFETIME_PROBE_LIMIT: u32 = 4;

#[cfg(feature = "kernel")]
const fn physical_driver_endpoint_identify_available() -> bool {
    cfg!(all(
        target_arch = "aarch64",
        target_os = "none",
        sel4_config_debug_build
    ))
}

#[cfg(feature = "kernel")]
const fn driver_task_endpoint_identity_matches(
    identify_available: bool,
    expected_ident: usize,
    observed_ident: usize,
) -> bool {
    !identify_available || expected_ident == 0 || observed_ident == expected_ident
}

/// Emit one bounded root-side command-cap identity checkpoint.
#[cfg(feature = "kernel")]
pub fn emit_driver_task_endpoint_lifetime_checkpoint(
    contract: DriverTaskContract,
    checkpoint: &'static str,
) {
    if !physical_driver_endpoint_identify_available() {
        return;
    }
    let Some(slot) = driver_task_slot_for_contract(contract) else {
        return;
    };
    let endpoint = slot.endpoint.load(Ordering::Acquire);
    let expected_ident = slot.endpoint_expected_ident.load(Ordering::Acquire);
    if endpoint == 0 || expected_ident == 0 {
        return;
    }
    let observed_ident = crate::sel4::debug_cap_identify(endpoint as sel4_sys::seL4_CPtr) as usize;
    let mut line = heapless::String::<224>::new();
    let _ = core::fmt::write(
        &mut line,
        format_args!(
            "DRIVER_TASK_ENDPOINT_LIFETIME schema=v1 contract={} checkpoint={} endpoint=0x{:04x} ident=0x{:x} expected=0x{:x} action=observe",
            contract.name, checkpoint, endpoint, observed_ident, expected_ident,
        ),
    );
    crate::bootstrap::log::force_uart_line_raw_without_prompt_refresh(line.as_str());
}

#[cfg(feature = "kernel")]
fn driver_task_endpoint_lifetime_allows_submit(
    contract: DriverTaskContract,
    slot: &DriverTaskCommandSlot,
    endpoint: usize,
) -> bool {
    if contract != HDMI_TEXT_DRIVER_TASK_CONTRACT || !physical_driver_endpoint_identify_available()
    {
        return true;
    }
    let expected_ident = slot.endpoint_expected_ident.load(Ordering::Acquire);
    if expected_ident == 0 {
        return true;
    }
    let probe = slot.endpoint_lifetime_probes.fetch_add(1, Ordering::AcqRel);
    if probe >= DRIVER_TASK_ENDPOINT_LIFETIME_PROBE_LIMIT {
        return slot.endpoint_lifetime_failure.load(Ordering::Acquire) == 0;
    }
    let observed_ident = crate::sel4::debug_cap_identify(endpoint as sel4_sys::seL4_CPtr) as usize;
    if driver_task_endpoint_identity_matches(true, expected_ident, observed_ident) {
        return true;
    }

    let _ = slot
        .endpoint
        .compare_exchange(endpoint, 0, Ordering::AcqRel, Ordering::Acquire);
    slot.mcs_command_admission_open.store(0, Ordering::Release);
    if slot
        .endpoint_lifetime_failure
        .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
    {
        let (diag_sequence, diag_state, diag_stage, diag_error) =
            driver_supervisor_fault_diagnostic_state(contract);
        let mut line = heapless::String::<384>::new();
        let _ = core::fmt::write(
            &mut line,
            format_args!(
                "DRIVER_TASK_ENDPOINT_LIFETIME schema=v1 contract={} checkpoint=submit endpoint=0x{:04x} ident=0x{:x} expected=0x{:x} action=fence probe={} admission={} phase={} sequence={} generation={} normal_replies={} failure_replies={} supervisor_ready={} diag_q={} diag_state={} diag_stage={} diag_error={} submitted={} completed={} faults={} timeouts={}",
                contract.name,
                endpoint,
                observed_ident,
                expected_ident,
                probe.saturating_add(1),
                slot.mcs_command_admission_open.load(Ordering::Acquire),
                slot.mcs_call_phase.load(Ordering::Acquire),
                slot.mcs_call_sequence.load(Ordering::Acquire),
                slot.mcs_cap_generation.load(Ordering::Acquire),
                slot.mcs_normal_replies.load(Ordering::Acquire),
                slot.mcs_failure_replies.load(Ordering::Acquire),
                slot.mcs_supervisor_authority_ready.load(Ordering::Acquire),
                diag_sequence,
                diag_state,
                diag_stage,
                diag_error,
                slot.counters.submitted_turns.load(Ordering::Acquire),
                slot.counters.completed_turns.load(Ordering::Acquire),
                slot.counters.fault_turns.load(Ordering::Acquire),
                slot.counters.timeouts.load(Ordering::Acquire),
            ),
        );
        crate::bootstrap::log::force_uart_line_raw_without_prompt_refresh(line.as_str());
    }
    false
}

/// Publish root's send-only, reserved-badge cap for one runtime notification.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_root_notification(contract: DriverTaskContract, notification: usize) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.root_notification
        .store(notification, Ordering::Release);
}

/// Publish root's receive cap for the compiler-declared CYW43 RX wake route.
///
/// This notification is distinct from the child-bound continuation/IRQ
/// notification. The CYW43 child receives only a send-only, badged cap, while
/// root retains this unbound receive cap and polls it once per EventPump turn.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_root_wake_notification(
    contract: DriverTaskContract,
    notification: usize,
    badge: u32,
) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT
        || notification == 0
        || badge != pi4_driver_abi::DRIVER_RUNTIME_CYW43_ROOT_WAKE_NOTIFICATION_BADGE
    {
        return false;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    slot.root_wake_notification
        .store(notification, Ordering::Release);
    slot.root_wake_badge.store(badge, Ordering::Release);
    true
}

#[cfg(all(feature = "kernel", test))]
static TEST_CYW43_ROOT_WAKE_BADGE: AtomicUsize = AtomicUsize::new(0);

#[cfg(feature = "kernel")]
fn poll_cyw43_root_wake_badge(notification: usize) -> sel4_sys::seL4_Word {
    #[cfg(test)]
    {
        let _ = notification;
        TEST_CYW43_ROOT_WAKE_BADGE.swap(0, Ordering::AcqRel) as sel4_sys::seL4_Word
    }
    #[cfg(not(test))]
    {
        let mut badge = 0;
        let _ = crate::sel4::poll(notification as sel4_sys::seL4_CPtr, &mut badge);
        badge
    }
}

#[cfg(feature = "kernel")]
fn poll_cyw43_root_wake_slot(slot: &DriverTaskCommandSlot) -> bool {
    let notification = slot.root_wake_notification.load(Ordering::Acquire);
    let expected_badge = slot.root_wake_badge.load(Ordering::Acquire);
    if notification == 0
        || expected_badge != pi4_driver_abi::DRIVER_RUNTIME_CYW43_ROOT_WAKE_NOTIFICATION_BADGE
    {
        return false;
    }
    slot.root_wake_polls.fetch_add(1, Ordering::AcqRel);
    if poll_cyw43_root_wake_badge(notification) == sel4_sys::seL4_Word::from(expected_badge) {
        slot.root_wake_hits.fetch_add(1, Ordering::AcqRel);
        return true;
    }
    false
}

/// Poll the unbound CYW43 child-to-root RX wake once.
///
/// The result is an urgency hint for this scheduling turn only. Queue state in
/// the sequence-last CYW43 record remains the sole work authority and history.
/// HAL retains no software work latch; EventPump may combine this returned bit
/// with a fresh durable snapshot to form one transient scheduling urgency.
#[cfg(feature = "kernel")]
#[must_use]
pub fn poll_cyw43_root_wake_notification() -> bool {
    let Some(task_key) = driver_task_contract_key(CYW43_WIFI_DRIVER_TASK_CONTRACT) else {
        return false;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return false;
    };
    poll_cyw43_root_wake_slot(slot)
}

/// Snapshot CYW43 root-wake telemetry without assigning it queue authority.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_root_wake_snapshot() -> Option<Cyw43RootWakeSnapshot> {
    let task_key = driver_task_contract_key(CYW43_WIFI_DRIVER_TASK_CONTRACT)?;
    let slot = slot_for_task_key(task_key)?;
    Some(Cyw43RootWakeSnapshot {
        bound: slot.root_wake_notification.load(Ordering::Acquire) != 0,
        badge: slot.root_wake_badge.load(Ordering::Acquire),
        polls: slot.root_wake_polls.load(Ordering::Acquire),
        hits: slot.root_wake_hits.load(Ordering::Acquire),
    })
}

/// Publish the root mapping of the fixed command/completion ring for a driver.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_ring(contract: DriverTaskContract, ring_root_ptr: usize) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.ring_root_ptr.store(ring_root_ptr, Ordering::Release);
}

/// Publish the root CSpace cap for the frame backing a driver command ring.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_ring_frame_cap(contract: DriverTaskContract, ring_frame_cap: usize) {
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.ring_frame_cap.store(ring_frame_cap, Ordering::Release);
}

/// Publish one root CSpace cap backing a driver shared-buffer page.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_shared_frame_cap(
    contract: DriverTaskContract,
    page_index: usize,
    shared_frame_cap: usize,
) {
    publish_driver_task_shared_frame(contract, page_index, shared_frame_cap, 0);
}

/// Publish one root CSpace cap and root mapping backing a shared-buffer page.
#[cfg(feature = "kernel")]
pub fn publish_driver_task_shared_frame(
    contract: DriverTaskContract,
    page_index: usize,
    shared_frame_cap: usize,
    shared_frame_root_ptr: usize,
) {
    if page_index >= DRIVER_TASK_SHARED_FRAME_TRACKING_CAPACITY {
        return;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        return;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        return;
    };
    slot.shared_frame_caps[page_index].store(shared_frame_cap, Ordering::Release);
    slot.shared_frame_root_ptrs[page_index].store(shared_frame_root_ptr, Ordering::Release);
    let required_count = page_index.saturating_add(1);
    let current = slot.shared_frame_count.load(Ordering::Acquire);
    if required_count > current {
        slot.shared_frame_count
            .store(required_count, Ordering::Release);
    }
}

/// Return the endpoint and ring-frame caps for a linked bus-owner runtime.
#[cfg(feature = "kernel")]
#[must_use]
pub fn driver_task_bus_owner_transport_caps(
    contract: DriverTaskContract,
) -> Option<(sel4_sys::seL4_CPtr, sel4_sys::seL4_CPtr)> {
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    let endpoint = slot.endpoint.load(Ordering::Acquire);
    let ring_frame_cap = slot.ring_frame_cap.load(Ordering::Acquire);
    if endpoint == 0 || ring_frame_cap == 0 {
        return None;
    }
    Some((
        endpoint as sel4_sys::seL4_CPtr,
        ring_frame_cap as sel4_sys::seL4_CPtr,
    ))
}

/// Return the endpoint, ring-frame cap, and bounded shared-buffer caps for a
/// linked bus-owner runtime.
#[cfg(feature = "kernel")]
#[must_use]
pub fn driver_task_bus_owner_transport_caps_with_shared(
    contract: DriverTaskContract,
    min_shared_pages: usize,
) -> Option<(
    sel4_sys::seL4_CPtr,
    sel4_sys::seL4_CPtr,
    [sel4_sys::seL4_CPtr; DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY],
)> {
    if min_shared_pages > DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY {
        return None;
    }
    let (endpoint, ring_frame_cap) = driver_task_bus_owner_transport_caps(contract)?;
    let task_key = driver_task_contract_key(contract)?;
    let slot = slot_for_task_key(task_key)?;
    if slot.shared_frame_count.load(Ordering::Acquire) < min_shared_pages {
        return None;
    }
    let mut shared_frame_caps = [0; DRIVER_TASK_BUS_LINK_SHARED_FRAME_CAPACITY];
    let mut index = 0usize;
    while index < min_shared_pages {
        let cap = slot.shared_frame_caps[index].load(Ordering::Acquire);
        if cap == 0 {
            return None;
        }
        shared_frame_caps[index] = cap as sel4_sys::seL4_CPtr;
        index = index.saturating_add(1);
    }
    Some((endpoint, ring_frame_cap, shared_frame_caps))
}

/// Return one stable, passive sample of the CYW43 private-RX queue level.
///
/// The runtime's sequence-last record is authoritative. Root invalidates and
/// samples it twice; the child-to-root notification is deliberately absent
/// from this decision path.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn driver_task_cyw43_rx_queue_state_snapshot() -> Option<DriverRuntimeCyw43RxQueueState>
{
    const SNAPSHOT_ATTEMPTS: usize = 3;

    let slot = driver_task_slot_for_contract(CYW43_WIFI_DRIVER_TASK_CONTRACT)?;
    if slot.root_ring_writers.load(Ordering::Acquire) != 0 {
        return None;
    }
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if ring_root_ptr == 0 {
        return None;
    }
    let record_ptr =
        ring_root_ptr.checked_add(usize::from(DRIVER_RUNTIME_CYW43_RX_QUEUE_STATE_OFFSET))?;
    let record_bytes = usize::from(DRIVER_RUNTIME_CYW43_RX_QUEUE_STATE_BYTES);
    let ring = DriverTaskRingView::new(ring_root_ptr)?;

    let mut attempt = 0usize;
    while attempt < SNAPSHOT_ATTEMPTS {
        driver_task_ring_invalidate_root_range(record_ptr, record_bytes);
        let first = ring.read_cyw43_rx_queue_state()?;
        driver_task_shared_load_barrier();
        driver_task_ring_invalidate_root_range(record_ptr, record_bytes);
        let second = ring.read_cyw43_rx_queue_state()?;
        driver_task_counter_add(&slot.counters.cache_invalidate_ops, 2);
        driver_task_counter_add(
            &slot.counters.cache_invalidate_bytes,
            record_bytes.saturating_mul(2),
        );
        if let Some(snapshot) = DriverRuntimeCyw43RxQueueState::stable_snapshot(first, second) {
            return Some(snapshot);
        }
        attempt = attempt.saturating_add(1);
    }
    None
}

#[cfg(feature = "kernel")]
fn driver_task_cyw43_rx_batch_pages_ready(slot: &DriverTaskCommandSlot) -> bool {
    if slot.shared_frame_count.load(Ordering::Acquire)
        < DRIVER_RUNTIME_CYW43_RX_BATCH_REQUIRED_SHARED_PAGES
    {
        return false;
    }
    let mut page = DRIVER_RUNTIME_CYW43_RX_BATCH_FIRST_SHARED_PAGE;
    while page < DRIVER_RUNTIME_CYW43_RX_BATCH_REQUIRED_SHARED_PAGES {
        if slot.shared_frame_caps[page].load(Ordering::Acquire) == 0
            || slot.shared_frame_root_ptrs[page].load(Ordering::Acquire) == 0
        {
            return false;
        }
        page = page.saturating_add(1);
    }
    true
}

/// Resolve one contiguous absolute shared-buffer span to its root mapping.
#[cfg(feature = "kernel")]
fn driver_task_cyw43_rx_batch_contiguous_root_span(
    slot: &DriverTaskCommandSlot,
    absolute_offset: usize,
    len: usize,
) -> Option<usize> {
    if len == 0 || !driver_task_cyw43_rx_batch_pages_ready(slot) {
        return None;
    }
    let relative =
        absolute_offset.checked_sub(usize::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE))?;
    let page = relative / DRIVER_TASK_RING_PAGE_BYTES;
    let page_offset = relative % DRIVER_TASK_RING_PAGE_BYTES;
    if page < DRIVER_RUNTIME_CYW43_RX_BATCH_FIRST_SHARED_PAGE
        || page >= DRIVER_RUNTIME_CYW43_RX_BATCH_REQUIRED_SHARED_PAGES
        || len > DRIVER_TASK_RING_PAGE_BYTES.saturating_sub(page_offset)
    {
        return None;
    }
    slot.shared_frame_root_ptrs[page]
        .load(Ordering::Acquire)
        .checked_add(page_offset)
}

#[cfg(feature = "kernel")]
struct DriverTaskSharedRecordView {
    window: super::MappedRegisterWindow,
    base_offset: usize,
    len: usize,
}

#[cfg(feature = "kernel")]
impl DriverTaskSharedRecordView {
    fn new(record_ptr: usize, len: usize) -> Option<Self> {
        if len == 0 {
            return None;
        }
        let base_offset = record_ptr % DRIVER_TASK_RING_PAGE_BYTES;
        let page_base = record_ptr.checked_sub(base_offset)?;
        if len > DRIVER_TASK_RING_PAGE_BYTES.checked_sub(base_offset)? {
            return None;
        }
        #[cfg(not(test))]
        let window =
            super::MappedRegisterWindow::new(page_base, DRIVER_TASK_RING_PAGE_BYTES).ok()?;
        #[cfg(test)]
        let window =
            super::MappedRegisterWindow::new_test(page_base, DRIVER_TASK_RING_PAGE_BYTES).ok()?;
        Some(Self {
            window,
            base_offset,
            len,
        })
    }

    fn read_u32(&self, offset: usize) -> Option<u32> {
        if offset.checked_add(core::mem::size_of::<u32>())? > self.len {
            return None;
        }
        self.window
            .read_u32(self.base_offset.checked_add(offset)?)
            .ok()
    }

    fn read_u16(&self, offset: usize) -> Option<u16> {
        if offset.checked_add(core::mem::size_of::<u16>())? > self.len {
            return None;
        }
        let aligned = offset & !3;
        let shift = ((offset & 2) * 8) as u32;
        self.read_u32(aligned)
            .map(|word| ((word >> shift) & u32::from(u16::MAX)) as u16)
    }

    fn read_u8(&self, offset: usize) -> Option<u8> {
        if offset >= self.len {
            return None;
        }
        let aligned = offset & !3;
        let shift = ((offset & 3) * 8) as u32;
        self.read_u32(aligned)
            .map(|word| ((word >> shift) & u32::from(u8::MAX)) as u8)
    }
}

#[cfg(feature = "kernel")]
fn driver_task_read_cyw43_bus_episode_record(
    record_ptr: usize,
) -> Option<DriverRuntimeCyw43BusEpisodeRecord> {
    let record_bytes = usize::from(DRIVER_RUNTIME_CYW43_BUS_EPISODE_BYTES);
    let view = DriverTaskSharedRecordView::new(record_ptr, record_bytes)?;
    let mut words = [0; pi4_driver_abi::DRIVER_RUNTIME_CYW43_BUS_EPISODE_WORDS];
    let mut index = 0usize;
    while index < words.len() {
        words[index] = view.read_u32(index * core::mem::size_of::<u32>())?;
        index = index.saturating_add(1);
    }
    Some(DriverRuntimeCyw43BusEpisodeRecord::from_le_words(words))
}

