/// Stable reason class returned by the retained CYW43/SDIO pair restart.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Cyw43SdioPairRestartFailureKind {
    /// Another cursor currently owns the pair-restart generation.
    AlreadyInProgress,
    /// One retained runtime context was unavailable or invalid.
    ContextMissing,
    /// The permitted virtual counter was unavailable.
    CounterUnavailable,
    /// The owner-written physical-lifetime record was unavailable or invalid.
    PhysicalLifetimeUnavailable,
    /// The aggregate deadline or a retained poll bound expired.
    DeadlineExpired,
    /// One exact restart operation failed.
    ActionFailed,
}

#[cfg(feature = "kernel")]
impl Cyw43SdioPairRestartFailureKind {
    /// Return the stable operator-facing reason class.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::AlreadyInProgress => "already-in-progress",
            Self::ContextMissing => "context-missing",
            Self::CounterUnavailable => "counter-unavailable",
            Self::PhysicalLifetimeUnavailable => "physical-lifetime-unavailable",
            Self::DeadlineExpired => "deadline-expired",
            Self::ActionFailed => "action-failed",
        }
    }
}

/// Supervisor-proven origin of one CYW43/SDIO pair transaction.
///
/// `ColdBootstrap` is a one-shot authority for the canonical first physical
/// lifetime. Every descriptor fault, issued-unknown action, restart request,
/// and later pair transaction must use `Recovery`, even when the global pair
/// epoch has not advanced yet.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Cyw43SdioPairRestartProvenance {
    /// Sole supervisor-routed first physical pair lifetime.
    ColdBootstrap,
    /// Pre-handoff fault recovery or any later pair recovery.
    Recovery,
}

/// Typed terminal failure from pair-restart admission or execution.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Cyw43SdioPairRestartFailure {
    kind: Cyw43SdioPairRestartFailureKind,
    action: &'static str,
    operation: &'static str,
    cause_status: &'static str,
    status: &'static str,
    sdhci_root_ptr: usize,
    completion: Option<DriverTaskCompletionRecord>,
}

#[cfg(feature = "kernel")]
impl Cyw43SdioPairRestartFailure {
    /// Return the stable failure class.
    #[must_use]
    pub const fn kind(self) -> Cyw43SdioPairRestartFailureKind {
        self.kind
    }

    /// Return the canonical action that failed.
    #[must_use]
    pub const fn action(self) -> &'static str {
        self.action
    }

    /// Return the exact retained sub-operation active at first failure.
    #[must_use]
    pub const fn operation(self) -> &'static str {
        self.operation
    }

    /// Return the first causal status before the deterministic fence ran.
    #[must_use]
    pub const fn cause_status(self) -> &'static str {
        self.cause_status
    }

    /// Return the stable fence/admission status.
    #[must_use]
    pub const fn status(self) -> &'static str {
        self.status
    }

    /// Return the root-side SDHCI virtual address admitted to this restart.
    #[must_use]
    pub const fn sdhci_root_ptr(self) -> usize {
        self.sdhci_root_ptr
    }

    /// Return the exact terminal runtime completion that caused an engine
    /// replay failure, when the child runtime produced one.
    #[must_use]
    pub const fn completion(self) -> Option<DriverTaskCompletionRecord> {
        self.completion
    }
}

/// Result of one retained CYW43/SDIO pair-restart outer turn.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[must_use]
pub enum Cyw43SdioPairRestartTurn {
    /// Exactly one HAL/runtime operation or retained poll completed.
    Pending {
        /// Canonical 22-action schedule entry.
        action: &'static str,
        /// Exact retained sub-operation completed by this turn.
        operation: &'static str,
    },
    /// The pair was delegated in a fresh generation.
    Complete {
        /// Newly published pair epoch.
        epoch: u32,
        /// Exact SDIO-owner lifetime completed by `ReplaySdioEngine`.
        physical_lifetime_epoch: u32,
    },
    /// The pair transaction completed, but a later recovery request revoked
    /// replay authority before the cursor could publish it.
    Superseded {
        /// Newly published pair epoch.
        epoch: u32,
        /// Exact SDIO-owner lifetime completed by `ReplaySdioEngine`.
        physical_lifetime_epoch: u32,
    },
    /// The deterministic outer failure fence reached a terminal state.
    Failed(Cyw43SdioPairRestartFailure),
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
struct Cyw43SdioPairRestartDeadline {
    start: u64,
    cycles: u64,
    frequency_hz: u64,
}

#[cfg(feature = "kernel")]
impl Cyw43SdioPairRestartDeadline {
    fn new(micros: u64) -> Option<Self> {
        let start = driver_task_counter_ticks()?;
        let frequency_hz = driver_task_counter_frequency()?;
        let cycles = driver_task_micros_to_cycles_at_hz(micros, frequency_hz);
        if frequency_hz == 0 || cycles == 0 {
            return None;
        }
        Some(Self {
            start,
            cycles,
            frequency_hz,
        })
    }

    const fn expired_at(self, now: u64) -> bool {
        now.wrapping_sub(self.start) >= self.cycles
    }

    const fn delay_cycles(self) -> u64 {
        driver_task_micros_to_cycles_at_hz(CYW43_SDIO_PAIR_RESTART_MMIO_GAP_US, self.frequency_hz)
    }
}

