#[cfg(feature = "kernel")]
fn emit_driver_task_ring_call_progress(
    contract: DriverTaskContract,
    request: usize,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    progress: DriverTaskRingProgressRecord,
) {
    use core::fmt::Write;
    use heapless::String;

    let key = driver_task_ring_log_key(
        0,
        request,
        command,
        DriverTaskRingCommandMode::PromptSlice,
        progress,
        0,
    );
    let Some(repeat_count) = driver_task_ring_log_repeat_count_for_mode(
        contract,
        DriverTaskRingRepeatLog::Progress,
        key,
        DriverTaskRingCommandMode::PromptSlice,
    ) else {
        return;
    };
    let mut line = String::<512>::new();
    let valid = progress.magic == DRIVER_RUNTIME_RING_PROGRESS_MAGIC;
    let _ = write!(
        line,
        "DRIVER_TASK_RING_PROGRESS contract={} request={} expected_aux0=0x{:08x} marker_valid={} marker_sequence={} marker_phase={} marker_phase_name={} marker_aux0=0x{:08x}",
        contract.name,
        request,
        command.aux0,
        if valid { "yes" } else { "no" },
        progress.sequence,
        progress.phase,
        driver_task_ring_progress_phase_label(progress.phase),
        progress.aux0,
    );
    if repeat_count > 1 {
        let _ = write!(line, " repeat_count={}", repeat_count);
    }
    emit_driver_task_ring_prompt_progress_line(contract, mode, line.as_str());
}

#[cfg(feature = "kernel")]
fn emit_driver_task_ring_call_abort(
    contract: DriverTaskContract,
    endpoint: usize,
    request: usize,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    reason: &'static str,
    timeout_count: usize,
    progress: DriverTaskRingProgressRecord,
) {
    use core::fmt::Write;
    use heapless::String;

    let key = driver_task_ring_abort_log_key(
        endpoint,
        request,
        command,
        mode,
        reason,
        timeout_count,
        progress,
    );
    let Some(repeat_count) = driver_task_ring_log_repeat_count_for_mode(
        contract,
        DriverTaskRingRepeatLog::Abort,
        key,
        mode,
    ) else {
        return;
    };
    let mut line = String::<640>::new();
    let _ = write!(
        line,
        "DRIVER_TASK_RING_CALL_ABORT contract={} endpoint=0x{:04x} request={} mode={} reason={} timeout_count={} opcode={} arg0={} aux0=0x{:08x} frame_len={} owner=linked-runtime marker_valid={} marker_sequence={} marker_phase={} marker_phase_name={} marker_aux0=0x{:08x} blocker={} next_action=retry-fresh-request-after-blocker-fix",
        contract.name,
        endpoint,
        request,
        mode.as_str(),
        reason,
        timeout_count,
        command.opcode,
        command.arg0,
        command.aux0,
        command.frame.len,
        driver_task_ring_progress_marker_valid(progress),
        progress.sequence,
        progress.phase,
        driver_task_ring_progress_phase_label(progress.phase),
        progress.aux0,
        driver_task_ring_progress_blocker(progress, request, command),
    );
    if repeat_count > 1 {
        let _ = write!(line, " repeat_count={}", repeat_count);
    }
    emit_driver_task_ring_prompt_progress_line(contract, mode, line.as_str());
}

#[cfg(feature = "kernel")]
fn emit_driver_task_ring_call_keep_active(
    contract: DriverTaskContract,
    endpoint: usize,
    request: usize,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    timeout_count: usize,
    keep_limit: usize,
    progress_advanced: bool,
    progress: DriverTaskRingProgressRecord,
) {
    use core::fmt::Write;
    use heapless::String;

    let extra = keep_limit ^ ((progress_advanced as usize) << 16);
    let key = driver_task_ring_log_key(endpoint, request, command, mode, progress, extra);
    let Some(repeat_count) = driver_task_ring_log_repeat_count_for_mode(
        contract,
        DriverTaskRingRepeatLog::KeepActive,
        key,
        mode,
    ) else {
        return;
    };
    let mut line = String::<640>::new();
    let _ = write!(
        line,
        "DRIVER_TASK_RING_CALL_KEEP_ACTIVE contract={} endpoint=0x{:04x} request={} mode={} timeout_count={} keep_limit={} progress_advanced={} opcode={} arg0={} aux0=0x{:08x} frame_len={} owner=linked-runtime marker_valid={} marker_sequence={} marker_phase={} marker_phase_name={} marker_aux0=0x{:08x} blocker={} next_action=poll-same-request",
        contract.name,
        endpoint,
        request,
        mode.as_str(),
        timeout_count,
        keep_limit,
        if progress_advanced { "yes" } else { "no" },
        command.opcode,
        command.arg0,
        command.aux0,
        command.frame.len,
        driver_task_ring_progress_marker_valid(progress),
        progress.sequence,
        progress.phase,
        driver_task_ring_progress_phase_label(progress.phase),
        progress.aux0,
        driver_task_ring_progress_blocker(progress, request, command),
    );
    if repeat_count > 1 {
        let _ = write!(line, " repeat_count={}", repeat_count);
    }
    emit_driver_task_ring_prompt_progress_line(contract, mode, line.as_str());
}

#[cfg(feature = "kernel")]
fn emit_driver_task_ring_prompt_progress_line(
    contract: DriverTaskContract,
    mode: DriverTaskRingCommandMode,
    line: &str,
) {
    let _ = (contract, mode);
    crate::bootstrap::log::force_log_buffer_line_or_uart_without_prompt_refresh(line);
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DriverTaskRingCommandMode {
    Steady,
    Bootstrap,
    NonBlocking,
    PromptSlice,
    RetainedTurn,
}

#[cfg(feature = "kernel")]
impl DriverTaskRingCommandMode {
    const fn as_str(self) -> &'static str {
        match self {
            DriverTaskRingCommandMode::Steady => "steady",
            DriverTaskRingCommandMode::Bootstrap => "bootstrap",
            DriverTaskRingCommandMode::NonBlocking => "nonblocking",
            DriverTaskRingCommandMode::PromptSlice => "prompt-slice",
            DriverTaskRingCommandMode::RetainedTurn => "retained-turn",
        }
    }

    const fn records_latency(self) -> bool {
        matches!(
            self,
            DriverTaskRingCommandMode::Steady
                | DriverTaskRingCommandMode::NonBlocking
                | DriverTaskRingCommandMode::PromptSlice
                | DriverTaskRingCommandMode::RetainedTurn
        )
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_call_trace_enabled(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
) -> bool {
    if matches!(contract.kind, DriverTaskKind::WifiNic)
        && command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        return false;
    }
    if matches!(contract.kind, DriverTaskKind::WifiNic)
        && command.aux0 == 0
        && command.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE == 0
        && command.frame.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE == 0
        && matches!(
            mode,
            DriverTaskRingCommandMode::Steady
                | DriverTaskRingCommandMode::NonBlocking
                | DriverTaskRingCommandMode::PromptSlice
                | DriverTaskRingCommandMode::RetainedTurn
        )
    {
        return false;
    }
    if matches!(contract.kind, DriverTaskKind::HdmiText)
        && command.opcode == DriverTaskOpcode::SubmitFrame.as_u16()
        && command.aux0 == 0
        && matches!(
            mode,
            DriverTaskRingCommandMode::Steady
                | DriverTaskRingCommandMode::NonBlocking
                | DriverTaskRingCommandMode::PromptSlice
                | DriverTaskRingCommandMode::RetainedTurn
        )
    {
        return false;
    }
    if matches!(contract.kind, DriverTaskKind::WiredNic)
        && command.aux0 == 0
        && command.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE == 0
        && command.frame.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE == 0
        && matches!(
            mode,
            DriverTaskRingCommandMode::Steady
                | DriverTaskRingCommandMode::NonBlocking
                | DriverTaskRingCommandMode::PromptSlice
                | DriverTaskRingCommandMode::RetainedTurn
        )
    {
        return false;
    }
    if matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX
        && matches!(
            mode,
            DriverTaskRingCommandMode::Steady
                | DriverTaskRingCommandMode::NonBlocking
                | DriverTaskRingCommandMode::PromptSlice
        )
    {
        return false;
    }
    if command.aux0 != 0
        || command.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE != 0
        || command.frame.flags & DRIVER_TASK_RING_FLAG_INIT_DESCRIPTOR_NON_ACCEPTANCE != 0
    {
        return true;
    }
    if matches!(
        contract.kind,
        DriverTaskKind::Serial | DriverTaskKind::LocalSeatUsb
    ) {
        return false;
    }
    true
}

#[cfg(feature = "kernel")]
fn driver_task_ring_completion_trace_enabled(
    trace_call: bool,
    command: DriverTaskCommandRecord,
    completion: DriverTaskCompletionRecord,
) -> bool {
    if trace_call {
        return true;
    }
    if command.flags & DRIVER_TASK_RING_FLAG_QUIET_HOT_PATH != 0
        && driver_task_ring_completion_is_quiet_expected(completion)
    {
        return false;
    }
    completion.code == DriverTaskCompletionCode::Fault.as_u16()
        || completion.code == DriverTaskCompletionCode::BudgetExhausted.as_u16()
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_completion_is_quiet_expected(
    completion: DriverTaskCompletionRecord,
) -> bool {
    completion.code == DriverTaskCompletionCode::Idle.as_u16()
        || (completion.code == DriverTaskCompletionCode::Fault.as_u16()
            && completion.detail == DRIVER_TASK_RING_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL
            && completion.result == DRIVER_TASK_RING_SDIO_RESPONSE_ERROR_RESULT)
}

#[cfg(feature = "kernel")]
fn driver_task_ring_timeout_trace_enabled(
    trace_call: bool,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> bool {
    if trace_call {
        return true;
    }
    if command.flags & DRIVER_TASK_RING_FLAG_QUIET_HOT_PATH != 0 {
        return false;
    }
    matches!(
        contract.kind,
        DriverTaskKind::WiredNic | DriverTaskKind::WifiNic
    )
}

#[cfg(feature = "kernel")]
fn emit_driver_task_ring_resource_submit_status(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    stage: &'static str,
    status: &'static str,
) {
    if !driver_task_ring_call_trace_enabled(contract, command, DriverTaskRingCommandMode::Steady) {
        return;
    }
    if let Some(hot_path) = DriverTaskHotPath::from_u32(command.arg0) {
        emit_driver_task_resource_init_status_with_context(
            contract,
            hot_path,
            stage,
            status,
            None,
            Some(command.aux0),
            Some(command.sequence),
        );
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_mode_uses_bounded_send(mode: DriverTaskRingCommandMode) -> bool {
    matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking
            | DriverTaskRingCommandMode::Bootstrap
            | DriverTaskRingCommandMode::PromptSlice
            | DriverTaskRingCommandMode::RetainedTurn
    )
}

#[cfg(feature = "kernel")]
fn driver_task_ring_attempt_limit(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
) -> usize {
    if !driver_task_ring_mode_uses_bounded_send(mode) {
        return DRIVER_TASK_BOOTSTRAP_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::RetainedTurn {
        return 1;
    }
    if mode == DriverTaskRingCommandMode::PromptSlice
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX
    {
        return DRIVER_TASK_USB_PROMPT_ENUM_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::PromptSlice
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX
    {
        return DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::PromptSlice
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
    {
        return DRIVER_TASK_USB_PROMPT_INIT_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::PromptSlice {
        return DRIVER_TASK_PROMPT_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && command.aux0 == 0
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
    {
        return DRIVER_TASK_USB_PROMPT_POLL_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && command.aux0 == DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
    {
        return DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && command.aux0 == 0
        && matches!(contract.kind, DriverTaskKind::HdmiText)
    {
        return DRIVER_TASK_HDMI_FRAME_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && command.aux0 == 0
        && matches!(contract.kind, DriverTaskKind::Serial)
    {
        return DRIVER_TASK_PROMPT_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX
    {
        return DRIVER_TASK_USB_BOOTSTRAP_ENUM_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking
        && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
    {
        return DRIVER_TASK_LONG_INIT_RING_ATTEMPTS;
    }
    if mode == DriverTaskRingCommandMode::NonBlocking && driver_task_engine_init_aux(command.aux0) {
        return DRIVER_TASK_LONG_INIT_RING_ATTEMPTS;
    }
    if matches!(contract.kind, DriverTaskKind::WifiNic)
        && command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        DRIVER_TASK_CYW43_TRANSPORT_RING_ATTEMPTS
    } else if matches!(contract.kind, DriverTaskKind::WifiNic) && command.aux0 != 0 {
        DRIVER_TASK_LONG_INIT_RING_ATTEMPTS
    } else {
        DRIVER_TASK_BOOTSTRAP_RING_ATTEMPTS
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_timeout_keeps_active(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
) -> bool {
    driver_task_ring_timeout_keep_active_limit(contract, command, mode) != 0
}

#[cfg(feature = "kernel")]
fn driver_task_ring_timeout_keep_active_limit(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
) -> usize {
    if mode == DriverTaskRingCommandMode::RetainedTurn {
        if matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
            && command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX
        {
            DRIVER_TASK_RETAINED_OWNER_TERMINAL_KEEP_ACTIVE_LIMIT
        } else if matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
            && command.aux0 == DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
        {
            DRIVER_TASK_RETAINED_OWNER_TERMINAL_KEEP_ACTIVE_LIMIT
        } else if matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
            && command.aux0 == DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX
        {
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
        } else if matches!(contract.kind, DriverTaskKind::LocalSeatUsb) && command.aux0 == 0 {
            DRIVER_TASK_USB_STEADY_POLL_TIMEOUT_KEEP_ACTIVE_LIMIT
        } else if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
            && command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0
        {
            // Completion-poll count is only the timerless host fallback. Pi
            // hardware uses the exact semantic-progress timestamp and one
            // CNTVCT-scaled child lifetime before terminal fault containment.
            DRIVER_TASK_CYW43_TRANSPORT_TIMEOUT_KEEP_ACTIVE_LIMIT
        } else {
            usize::MAX
        }
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX
    {
        DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
    {
        DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && command.aux0 == DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX
    {
        DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::LocalSeatUsb)
        && driver_task_engine_init_aux(command.aux0)
    {
        // USB engine initialization owns the same retained controller lifetime
        // as local-seat initialization. Its isolated MCS task may require
        // several replenishments to zero and publish the admitted DMA arena;
        // root must continue observing the one active sequence instead of
        // aborting it through the generic short bootstrap timeout.
        DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::PcieRoot)
        && (command.aux0 == DRIVER_RUNTIME_INIT_AUX || driver_task_engine_init_aux(command.aux0))
    {
        DRIVER_TASK_PCIE_PREREQ_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::SdioHost)
        && (command.aux0 == DRIVER_RUNTIME_INIT_AUX || driver_task_engine_init_aux(command.aux0))
    {
        DRIVER_TASK_SDIO_PREREQ_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(
        contract.kind,
        DriverTaskKind::WiredNic | DriverTaskKind::WifiNic
    ) && driver_task_engine_init_aux(command.aux0)
    {
        DRIVER_TASK_NET_ENGINE_INIT_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::WifiNic)
        && command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX
    {
        DRIVER_TASK_CYW43_TRANSPORT_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if matches!(
        mode,
        DriverTaskRingCommandMode::NonBlocking | DriverTaskRingCommandMode::PromptSlice
    ) && matches!(contract.kind, DriverTaskKind::HdmiText)
        && command.aux0 == 0
    {
        DRIVER_TASK_HDMI_FRAME_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else {
        0
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_engine_init_aux(aux0: u32) -> bool {
    matches!(
        aux0,
        DRIVER_RUNTIME_ENGINE_INIT_AUX | DRIVER_RUNTIME_NET_INIT_AUX
    )
}

#[cfg(feature = "kernel")]
fn driver_task_ring_timeout_keep_decision(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    request: u32,
    progress_advanced: bool,
) -> (bool, usize) {
    let limit = driver_task_ring_timeout_keep_active_limit_for_progress(
        slot, contract, command, mode, request,
    );
    if limit == 0 {
        return (false, 0);
    }
    let steady_service = mode == DriverTaskRingCommandMode::RetainedTurn
        && contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0;
    if steady_service {
        if progress_advanced {
            slot.timeout_resumes.store(0, Ordering::Release);
            record_driver_task_steady_service_progress_time(slot);
            return (true, 0);
        }
        if let Some(expired) = driver_task_steady_service_inactivity_expired(slot) {
            if !expired {
                // Healthy waiting is IRQ-driven. Completion polls merely inspect
                // the ring and cannot age this lease by scheduler-call count.
                return (true, 0);
            }
            let timeout_count = slot
                .timeout_resumes
                .fetch_add(1, Ordering::AcqRel)
                .saturating_add(1);
            // Expiry is a terminal fault-containment trigger. The caller closes
            // the race with one stable completion fence, then enters pair
            // recovery; it never creates another scheduling edge.
            return (false, timeout_count);
        }
        // Counterless host profiles retain a finite diagnostic fallback below.
        // Its terminal action is the same fault fence, never a wake or retry.
    }
    if progress_advanced {
        slot.timeout_resumes.store(0, Ordering::Release);
        return (true, 0);
    }
    let timeout_count = slot
        .timeout_resumes
        .fetch_add(1, Ordering::AcqRel)
        .saturating_add(1);
    (timeout_count < limit, timeout_count)
}

#[cfg(feature = "kernel")]
fn driver_task_ring_timeout_keep_active_limit_for_progress(
    slot: &DriverTaskCommandSlot,
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    request: u32,
) -> usize {
    let limit = driver_task_ring_timeout_keep_active_limit(contract, command, mode);
    if mode == DriverTaskRingCommandMode::RetainedTurn
        && command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0
    {
        // The tagged lane has its own exact sequence/fingerprint/generation
        // progress record. Generic phase breadcrumbs must neither extend nor
        // shorten its fixed inactivity bound.
        return limit;
    }
    if limit == DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT
        && cached_driver_task_ring_progress_matches_request(slot, request, command.aux0)
    {
        let phase = slot.last_progress_phase.load(Ordering::Acquire);
        driver_task_ring_usb_enum_timeout_limit_for_phase(phase, limit)
    } else if limit == DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT {
        if cached_driver_task_ring_usb_enum_logical_turn_matches(slot, request, command.aux0) {
            let phase = slot.last_progress_phase.load(Ordering::Acquire);
            driver_task_ring_usb_enum_timeout_limit_for_phase(phase, limit)
        } else {
            limit
        }
    } else if limit == DRIVER_TASK_SDIO_PREREQ_TIMEOUT_KEEP_ACTIVE_LIMIT
        && cached_driver_task_ring_progress_matches_request(slot, request, command.aux0)
        && driver_task_ring_sdio_pwrseq_mailbox_phase(
            slot.last_progress_phase.load(Ordering::Acquire),
        )
    {
        DRIVER_TASK_SDIO_PWRSEQ_MAILBOX_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if limit == DRIVER_TASK_CYW43_TRANSPORT_TIMEOUT_KEEP_ACTIVE_LIMIT
        && cached_driver_task_ring_progress_matches_request(slot, request, command.aux0)
        && driver_task_ring_cyw43_sdio_owner_phase(slot.last_progress_phase.load(Ordering::Acquire))
    {
        if driver_task_ring_cyw43_sdio_owner_long_phase(
            slot.last_progress_phase.load(Ordering::Acquire),
        ) {
            DRIVER_TASK_CYW43_SDIO_OWNER_REPLY_TIMEOUT_KEEP_ACTIVE_LIMIT
        } else {
            DRIVER_TASK_CYW43_SDIO_OWNER_TIMEOUT_KEEP_ACTIVE_LIMIT
        }
    } else if limit == DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
        && cached_driver_task_ring_progress_matches_request(slot, request, command.aux0)
        && driver_task_ring_usb_hid_recovery_phase(slot.last_progress_phase.load(Ordering::Acquire))
    {
        DRIVER_TASK_USB_HID_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else {
        limit
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_sdio_pwrseq_mailbox_phase(phase: u32) -> bool {
    matches!(
        phase,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_WIFI_PWRSEQ_GET_CONFIG_BEGIN
            | DRIVER_RUNTIME_RING_PROGRESS_SDIO_WIFI_PWRSEQ_SET_CONFIG_BEGIN
            | DRIVER_RUNTIME_RING_PROGRESS_SDIO_WIFI_PWRSEQ_ASSERT_LOW_BEGIN
            | DRIVER_RUNTIME_RING_PROGRESS_SDIO_WIFI_PWRSEQ_RELEASE_HIGH_BEGIN
    )
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_usb_hid_recovery_phase(phase: u32) -> bool {
    matches!(
        phase,
        DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_BEGIN
            | DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_FAILED
            | DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_READY
    )
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_usb_enum_cross_request_phase(phase: u32) -> bool {
    driver_task_ring_usb_enum_controller_reset_phase(phase)
        || driver_task_ring_usb_enum_root_reset_phase(phase)
        || driver_task_ring_usb_enum_address_phase(phase)
        || driver_task_ring_usb_enum_transfer_wait_phase(phase)
        || driver_task_ring_usb_enum_status_wait_phase(phase)
        || driver_task_ring_usb_enum_hub_wait_phase(phase)
        || driver_task_ring_usb_enum_hub_event_phase(phase)
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_usb_enum_timeout_limit_for_phase(
    phase: u32,
    fallback_limit: usize,
) -> usize {
    if driver_task_ring_usb_enum_address_phase(phase) {
        DRIVER_TASK_USB_ENUM_ADDRESS_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if driver_task_ring_usb_enum_controller_reset_phase(phase)
        || driver_task_ring_usb_enum_root_reset_phase(phase)
    {
        DRIVER_TASK_USB_ENUM_ROOT_RESET_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if driver_task_ring_usb_enum_status_wait_phase(phase) {
        DRIVER_TASK_USB_ENUM_STATUS_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if driver_task_ring_usb_enum_transfer_wait_phase(phase) {
        DRIVER_TASK_USB_ENUM_TRANSFER_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if driver_task_ring_usb_enum_hub_event_phase(phase) {
        DRIVER_TASK_USB_ENUM_HUB_EVENT_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else if driver_task_ring_usb_enum_hub_wait_phase(phase) {
        DRIVER_TASK_USB_ENUM_HUB_TIMEOUT_KEEP_ACTIVE_LIMIT
    } else {
        fallback_limit
    }
}

