#[cfg(feature = "kernel")]
const fn driver_task_ring_flags_for_mode(mode: DriverTaskRingCommandMode, flags: u16) -> u16 {
    if driver_task_ring_mode_uses_bounded_send(mode) {
        flags | DRIVER_TASK_RING_FLAG_ONE_WAY
    } else {
        flags
    }
}

#[cfg(feature = "kernel")]
const fn driver_task_ring_command_fingerprint_mix(mut hash: u32, value: u32) -> u32 {
    hash ^= value;
    hash = hash.wrapping_mul(16_777_619);
    hash
}

#[cfg(feature = "kernel")]
fn driver_task_staging_bytes_fingerprint(mut hash: u32, payload: &[u8]) -> u32 {
    for byte in payload.iter().copied() {
        hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(byte));
    }
    hash
}

#[cfg(feature = "kernel")]
fn driver_task_staging_segments_fingerprint(segments: &[DriverTaskStagingSegment<'_>]) -> u32 {
    if segments.is_empty() {
        return 0;
    }
    let mut hash = 2_166_136_261u32;
    for segment in segments.iter().copied() {
        match segment {
            DriverTaskStagingSegment::Ring {
                offset,
                payload,
                flags,
            } => {
                hash = driver_task_ring_command_fingerprint_mix(hash, 0x5249_4e47);
                hash = driver_task_ring_command_fingerprint_mix(hash, offset as u32);
                hash = driver_task_ring_command_fingerprint_mix(hash, payload.len() as u32);
                hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(flags));
                hash = driver_task_staging_bytes_fingerprint(hash, payload);
            }
            DriverTaskStagingSegment::RuntimeInit { payload } => {
                hash = driver_task_ring_command_fingerprint_mix(hash, 0x494e_4954);
                hash = driver_task_ring_command_fingerprint_mix(
                    hash,
                    DRIVER_TASK_RING_FRAME_OFFSET as u32,
                );
                hash = driver_task_ring_command_fingerprint_mix(hash, payload.len() as u32);
                hash = driver_task_staging_bytes_fingerprint(hash, payload);
            }
            DriverTaskStagingSegment::Shared { payload, flags } => {
                hash = driver_task_ring_command_fingerprint_mix(hash, 0x5348_5244);
                hash = driver_task_ring_command_fingerprint_mix(
                    hash,
                    u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE),
                );
                hash = driver_task_ring_command_fingerprint_mix(hash, payload.len() as u32);
                hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(flags));
                hash = driver_task_staging_bytes_fingerprint(hash, payload);
            }
        }
    }
    hash | 1
}

#[cfg(feature = "kernel")]
fn driver_task_staged_cyw43_descriptor_header(
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> Option<(u16, u16)> {
    let descriptor_offset = usize::from(DRIVER_RUNTIME_CYW43_COMMAND_DESCRIPTOR_OFFSET);
    let descriptor_len = core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>();
    if command.frame.offset as usize != descriptor_offset
        || usize::from(command.frame.len) != descriptor_len
    {
        return None;
    }
    staging_segments.iter().find_map(|segment| match segment {
        DriverTaskStagingSegment::Ring {
            offset,
            payload,
            flags,
        } if *offset == descriptor_offset
            && payload.len() == descriptor_len
            && *flags == command.frame.flags =>
        {
            Some((
                u16::from_le_bytes([payload[0], payload[1]]),
                u16::from_le_bytes([payload[2], payload[3]]),
            ))
        }
        DriverTaskStagingSegment::Ring { .. }
        | DriverTaskStagingSegment::RuntimeInit { .. }
        | DriverTaskStagingSegment::Shared { .. } => None,
    })
}

#[cfg(feature = "kernel")]
fn driver_task_staged_cyw43_descriptor(
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> Option<DriverRuntimeCyw43CommandDescriptor> {
    let descriptor_offset = usize::from(DRIVER_RUNTIME_CYW43_COMMAND_DESCRIPTOR_OFFSET);
    let descriptor_len = core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>();
    if command.frame.offset as usize != descriptor_offset
        || usize::from(command.frame.len) != descriptor_len
    {
        return None;
    }
    let payload = staging_segments.iter().find_map(|segment| match segment {
        DriverTaskStagingSegment::Ring {
            offset,
            payload,
            flags,
        } if *offset == descriptor_offset
            && payload.len() == descriptor_len
            && *flags == command.frame.flags =>
        {
            Some(*payload)
        }
        DriverTaskStagingSegment::Ring { .. }
        | DriverTaskStagingSegment::RuntimeInit { .. }
        | DriverTaskStagingSegment::Shared { .. } => None,
    })?;
    let read_u16 = |offset: usize| u16::from_le_bytes([payload[offset], payload[offset + 1]]);
    let read_u32 = |offset: usize| {
        u32::from_le_bytes([
            payload[offset],
            payload[offset + 1],
            payload[offset + 2],
            payload[offset + 3],
        ])
    };
    let descriptor = DriverRuntimeCyw43CommandDescriptor {
        op: read_u16(0),
        flags: read_u16(2),
        target_addr: read_u32(4),
        payload_offset: read_u16(8),
        payload_len: read_u16(10),
        total_len: read_u32(12),
        arg0: read_u32(16),
        arg1: read_u32(20),
        reserved: read_u32(24),
    };
    descriptor.valid().then_some(descriptor)
}

/// Derive the command half of one persistent CYW43 transaction from its exact
/// staged op11 descriptor and payload. No caller-supplied flag is trusted.
#[cfg(feature = "kernel")]
fn driver_task_cyw43_persistent_transaction_requested(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    staging_segments: &[DriverTaskStagingSegment<'_>],
) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT
        || mode != DriverTaskRingCommandMode::RetainedTurn
        || command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
        || command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0
        || command.budget != DriverTaskBudgetGrant::from_contract(contract)
        || !driver_runtime_is_cyw43_root_continuation(command.arg0, command.arg1, command.aux0)
        || staging_segments.len() != 2
    {
        return false;
    }
    let Some(descriptor) = driver_task_staged_cyw43_descriptor(command, staging_segments) else {
        return false;
    };
    if descriptor.op != DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE
        || descriptor.payload_offset != DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE
        || descriptor.payload_len == 0
        || descriptor.total_len != u32::from(descriptor.payload_len)
        || descriptor.reserved != 0
    {
        return false;
    }
    staging_segments.iter().any(|segment| {
        matches!(
            segment,
            DriverTaskStagingSegment::Shared { payload, flags }
                if payload.len() == usize::from(descriptor.payload_len) && *flags == 0
        )
    })
}

#[cfg(feature = "kernel")]
fn driver_task_cyw43_steady_data_plane_command_matches(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
    expected: Cyw43SteadyDataPlaneOp,
) -> bool {
    if contract != CYW43_WIFI_DRIVER_TASK_CONTRACT
        || command.aux0 != DRIVER_RUNTIME_CYW43_COMMAND_AUX
        || command.aux1 == 0
        || command.budget != CYW43_STEADY_TX_SERVICE_LEASE_BUDGET
        || command.flags & DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY == 0
        || command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE == 0
        || !driver_runtime_is_cyw43_root_continuation(command.arg0, command.arg1, command.aux0)
        || staging_segments.len() != 2
    {
        return false;
    }
    let Some(descriptor) = driver_task_staged_cyw43_descriptor(command, staging_segments) else {
        return false;
    };
    if descriptor.op != expected.wire_op()
        || descriptor.flags != DRIVER_RUNTIME_CYW43_FLAG_STEADY_TX_SERVICE_LEASE
        || descriptor.target_addr != 0
        || descriptor.payload_offset != DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE
        || descriptor.payload_len < 14
        || descriptor.total_len != u32::from(descriptor.payload_len)
        || descriptor.arg0 != 0
        || descriptor.arg1 != 0
        || descriptor.reserved != 0
    {
        return false;
    }
    let payload_is_eapol = staging_segments.iter().find_map(|segment| match segment {
        DriverTaskStagingSegment::Shared { payload, flags }
            if *flags == 0 && payload.len() == usize::from(descriptor.payload_len) =>
        {
            Some(u16::from_be_bytes([payload[12], payload[13]]) == 0x888e)
        }
        DriverTaskStagingSegment::Ring { .. }
        | DriverTaskStagingSegment::RuntimeInit { .. }
        | DriverTaskStagingSegment::Shared { .. } => None,
    });
    match (expected, payload_is_eapol) {
        (Cyw43SteadyDataPlaneOp::EthTx, Some(false))
        | (Cyw43SteadyDataPlaneOp::HostEapolTx, Some(true)) => true,
        _ => false,
    }
}

#[cfg(feature = "kernel")]
fn driver_task_cyw43_steady_data_plane_fast_lane_admitted(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
    staging_segments: &[DriverTaskStagingSegment<'_>],
    expected: Cyw43SteadyDataPlaneOp,
    closing_parent_resume: bool,
) -> bool {
    if !driver_task_cyw43_steady_data_plane_command_matches(
        contract,
        command,
        staging_segments,
        expected,
    ) {
        return false;
    }
    match expected {
        Cyw43SteadyDataPlaneOp::EthTx => {
            cyw43_sdio_network_priority_lease_covers_exact_command(command, closing_parent_resume)
        }
        Cyw43SteadyDataPlaneOp::HostEapolTx => true,
    }
}

#[cfg(feature = "kernel")]
fn driver_task_ring_command_fingerprint(
    command: DriverTaskCommandRecord,
    staging_fingerprint: u32,
) -> u32 {
    let mut hash = 2_166_136_261u32;
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.opcode));
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.flags));
    hash = driver_task_ring_command_fingerprint_mix(hash, command.arg0);
    hash = driver_task_ring_command_fingerprint_mix(hash, command.arg1);
    hash = driver_task_ring_command_fingerprint_mix(hash, command.aux0);
    hash = driver_task_ring_command_fingerprint_mix(hash, command.aux1);
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.budget.max_ops));
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.budget.max_frames));
    hash = driver_task_ring_command_fingerprint_mix(hash, command.budget.max_bytes);
    hash = driver_task_ring_command_fingerprint_mix(hash, command.frame.offset);
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.frame.len));
    hash = driver_task_ring_command_fingerprint_mix(hash, u32::from(command.frame.flags));
    hash = driver_task_ring_command_fingerprint_mix(hash, staging_fingerprint);
    hash | 1
}

/// Execute a fixed-layout command over the pointer-free shared-ring ABI.
///
/// This transport is intentionally narrower than the transitional callback
/// service path. It is used by the isolated QEMU smoke task to prove the ABI
/// mechanics without crediting a hardware hot path until the driver state has
/// moved behind that ring.
#[cfg(feature = "kernel")]
pub fn run_driver_task_ring_command(
    contract: DriverTaskContract,
    command: DriverTaskCommandRecord,
) -> Option<DriverTaskCompletionRecord> {
    run_driver_task_ring_command_with_mode(contract, command, DriverTaskRingCommandMode::Steady)
}

