#[cfg(feature = "kernel")]
fn run_driver_task_ring_command_with_mode_and_staging_deadline(
    contract: DriverTaskContract,
    mut command: DriverTaskCommandRecord,
    mode: DriverTaskRingCommandMode,
    staging_segments: &[DriverTaskStagingSegment<'_>],
    mut recovery_deadline: Option<&mut DriverTaskDeadline>,
    steady_data_plane_operation: Option<Cyw43SteadyDataPlaneOp>,
) -> Option<DriverTaskCompletionRecord> {
    if !driver_task_ring_deadline_allows_attempt(recovery_deadline.as_deref_mut()) {
        return None;
    }
    let Some(task_key) = driver_task_contract_key(contract) else {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "invalid-contract",
        );
        return None;
    };
    let Some(slot) = slot_for_task_key(task_key) else {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "slot-missing",
        );
        return None;
    };
    let Some(_root_producer_guard) = acquire_root_ring_producer(contract, slot) else {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "producer-delegated-to-cyw43",
        );
        return None;
    };
    let Some(_mcs_nonblocking_root_producer_guard) =
        acquire_mcs_nonblocking_root_producer(contract, slot, mode)
    else {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "mcs-command-admission-closed",
        );
        return None;
    };
    let endpoint = slot.endpoint.load(Ordering::Acquire);
    let ring_root_ptr = slot.ring_root_ptr.load(Ordering::Acquire);
    if endpoint == 0 {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "no-endpoint",
        );
        return None;
    }
    if !driver_task_endpoint_lifetime_allows_submit(contract, slot, endpoint) {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "endpoint-identity-lost",
        );
        return None;
    }
    if ring_root_ptr == 0 {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "ring-missing",
        );
        return None;
    }
    if !driver_task_staging_segments_valid(slot, ring_root_ptr, staging_segments) {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "stage-invalid",
        );
        return None;
    }

    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0 {
        // The authority tag is minted only by the typed HAL entry. Callers may
        // present the descriptor marker, but they cannot self-authorize the
        // command-level service lease.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "caller-supplied-steady-service-lease",
        );
        return None;
    }
    if command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0 {
        // The op11 authority is derived from the exact staged descriptor and
        // payload below. A caller-provided command bit could alias unrelated
        // work and is never accepted.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "caller-supplied-persistent-transaction",
        );
        return None;
    }
    command.flags = driver_task_ring_flags_for_mode(mode, command.flags);
    let staged_cyw43_descriptor_header =
        driver_task_staged_cyw43_descriptor_header(command, staging_segments);
    let steady_tx_descriptor_marked = contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && staged_cyw43_descriptor_header.is_some_and(|(_, flags)| {
            flags & DRIVER_RUNTIME_CYW43_FLAG_STEADY_TX_SERVICE_LEASE != 0
        });
    let staged_control_exchange = contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && staged_cyw43_descriptor_header
            .is_some_and(|(op, _)| op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE);
    let persistent_transaction_candidate = staged_control_exchange;
    let persistent_transaction_requested = driver_task_cyw43_persistent_transaction_requested(
        contract,
        command,
        mode,
        staging_segments,
    );
    if persistent_transaction_candidate != persistent_transaction_requested {
        // An op11 header is not sufficient. The complete descriptor, exact
        // command budget, retained mode, and matching shared payload must form
        // one sealed authority statement before HAL mints the command flag.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "persistent-transaction-descriptor-mismatch",
        );
        return None;
    }
    if persistent_transaction_requested {
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION;
    }
    let typed_steady_tx_entry = steady_data_plane_operation.is_some();
    let terminal_drain_candidate = !typed_steady_tx_entry
        && mode == DriverTaskRingCommandMode::RetainedTurn
        && slot.active.load(Ordering::Acquire) != 0
        && CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire) != 0
        && slot.request_seq.load(Ordering::Acquire)
            == CYW43_PAIR_TERMINAL_DRAIN_REQUEST.load(Ordering::Acquire) as usize
        && CYW43_PAIR_TERMINAL_DRAIN_COMMAND_AUX1.load(Ordering::Acquire) == command.aux1;
    let steady_tx_terminal_drain_candidate = terminal_drain_candidate
        && steady_tx_descriptor_marked
        && slot.retained_steady_tx_fast_lane.load(Ordering::Acquire) != 0;
    if typed_steady_tx_entry || steady_tx_terminal_drain_candidate {
        command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE;
    }
    let command_marks_steady_service_lease =
        command.flags & DRIVER_RUNTIME_COMMAND_FLAG_STEADY_SERVICE_LEASE != 0;
    if steady_tx_descriptor_marked != command_marks_steady_service_lease
        || steady_tx_descriptor_marked
            != (typed_steady_tx_entry || steady_tx_terminal_drain_candidate)
    {
        // The immutable descriptor marker and the typed root entry are one
        // authority statement. Neither a generic caller with a marked op7, a
        // caller-supplied command tag, nor an unmarked specialized caller may
        // create a mixed-cadence request.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "steady-tx-cadence-marker-mismatch",
        );
        return None;
    }
    let staging_fingerprint = driver_task_staging_segments_fingerprint(staging_segments);
    let command_fingerprint = driver_task_ring_command_fingerprint(command, staging_fingerprint);
    let exact_terminal_drain = terminal_drain_candidate
        && cyw43_pair_fence_allows_exact_terminal_retained_turn(
            slot,
            mode,
            command,
            command_fingerprint,
        );
    if terminal_drain_candidate && !exact_terminal_drain {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "steady-tx-terminal-drain-identity-mismatch",
        );
        return None;
    }
    if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && cyw43_sdio_pair_submission_blocked(
            CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire),
            CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire),
            CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire),
        )
        && !exact_terminal_drain
    {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "pair-context-recovery-required",
        );
        return None;
    }
    let command_ptr = ring_root_ptr as *mut DriverTaskCommandRecord;
    let completion_ptr =
        (ring_root_ptr + DRIVER_TASK_RING_COMPLETION_OFFSET) as *mut DriverTaskCompletionRecord;
    let mut cache_counter_batch = DriverTaskCacheCounterBatch::new();

    if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && slot.semantic_terminal_request.load(Ordering::Acquire) != 0
    {
        // A completed persistent parent still belongs to its semantic owner.
        // No successor request may reuse the physical slot until that exact
        // receipt is compare-cleared or deterministic pair recovery scrubs it.
        request_cyw43_sdio_pair_restart();
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "semantic-terminal-owner-active",
        );
        return None;
    }

    let active_before_submit = slot.active.load(Ordering::Acquire) != 0;
    if active_before_submit
        && !exact_terminal_drain
        && !driver_task_retained_cadence_matches(slot, typed_steady_tx_entry)
    {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "retained-cadence-mismatch",
        );
        return None;
    }
    let same_request_resume = active_before_submit
        && driver_task_ring_mode_uses_bounded_send(mode)
        && (exact_terminal_drain || driver_task_ring_timeout_keeps_active(contract, command, mode))
        && slot.active_command_fingerprint.load(Ordering::Acquire) == command_fingerprint;
    let closing_cyw43_parent_resume = mode == DriverTaskRingCommandMode::RetainedTurn
        && contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && Cyw43SdioNetworkPriorityLeasePhase::from_u32(
            CYW43_SDIO_NETWORK_PRIORITY_LEASE
                .phase
                .load(Ordering::Acquire),
        ) == Some(Cyw43SdioNetworkPriorityLeasePhase::Closing)
        && same_request_resume;
    if mode == DriverTaskRingCommandMode::RetainedTurn
        && contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && Cyw43SdioNetworkPriorityLeasePhase::from_u32(
            CYW43_SDIO_NETWORK_PRIORITY_LEASE
                .phase
                .load(Ordering::Acquire),
        ) == Some(Cyw43SdioNetworkPriorityLeasePhase::Closing)
        && !closing_cyw43_parent_resume
    {
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "network-priority-lease-closing",
        );
        return None;
    }
    let steady_tx_fast_lane_requested = steady_data_plane_operation.is_some_and(|operation| {
        driver_task_cyw43_steady_data_plane_fast_lane_admitted(
            contract,
            command,
            staging_segments,
            operation,
            closing_cyw43_parent_resume,
        )
    });
    if steady_tx_fast_lane_requested && slot.root_notification.load(Ordering::Acquire) == 0 {
        // The tagged parent has no grant/ACK fallback. Its sole issue edge is
        // the final root notification, so require that endpoint before Stage
        // can make any request identity active.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "steady-tx-root-notification-missing",
        );
        return None;
    }
    if persistent_transaction_requested && slot.root_notification.load(Ordering::Acquire) == 0 {
        // Persistent op11 has one hint edge and no grant/endpoint fallback.
        // Reject before Stage makes any identity active.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "persistent-transaction-root-notification-missing",
        );
        return None;
    }
    if steady_data_plane_operation.is_some() && !steady_tx_fast_lane_requested {
        // The specialized entry is a cadence class, not an optional hint.
        // Fresh requests require an open exact-pair Network lease; a resumed
        // request may retain that class only while it is the exact Closing
        // parent. Reject before staging, phase mutation, or physical issue.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "steady-tx-fast-lane-not-admitted",
        );
        return None;
    }
    if same_request_resume
        && !exact_terminal_drain
        && !driver_task_retained_cadence_matches(slot, steady_tx_fast_lane_requested)
    {
        // One immutable request has exactly one cadence class for its whole
        // lifetime. A generic caller cannot adopt or downgrade an urgent fast
        // request, and the specialized caller cannot upgrade a generic slot.
        emit_driver_task_ring_resource_submit_status(
            contract,
            command,
            "runtime-ring-submit",
            "retained-cadence-mismatch",
        );
        return None;
    }
    if slot.active.swap(1, Ordering::AcqRel) != 0 && !same_request_resume {
        if DriverTaskRetainedLeasePhase::from_usize(
            slot.retained_priority_lease_phase.load(Ordering::Acquire),
        ) != Some(DriverTaskRetainedLeasePhase::Inactive)
        {
            driver_task_counter_add(&slot.counters.busy_conflicts, 1);
            cache_counter_batch.flush(slot);
            emit_driver_task_ring_resource_submit_status(
                contract,
                command,
                "runtime-ring-submit",
                "retained-lease-busy",
            );
            return None;
        }
        let active_request = slot.request_seq.load(Ordering::Acquire);
        cache_counter_batch.record_completion_invalidate(ring_root_ptr);
        // Drain a late completion before declaring the ring busy so one delayed
        // driver turn cannot permanently block a hot path.
        let active_completion =
            DriverTaskRingView::new(ring_root_ptr)?.read_completion_snapshot()?;
        if active_request == 0 || active_completion.sequence != active_request as u32 {
            driver_task_counter_add(&slot.counters.busy_conflicts, 1);
            cache_counter_batch.flush(slot);
            emit_driver_task_ring_resource_submit_status(
                contract,
                command,
                "runtime-ring-submit",
                "busy",
            );
            return None;
        }
        driver_task_record_completion_counters(slot, active_completion);
        slot.timeout_resumes.store(0, Ordering::Release);
    }

    let mut retained_request_prepared = false;
    let request = if same_request_resume {
        driver_task_counter_add(&slot.counters.same_request_resumes, 1);
        slot.request_seq.load(Ordering::Acquire)
    } else {
        if mode != DriverTaskRingCommandMode::RetainedTurn
            && !staging_segments.is_empty()
            && driver_task_stage_segments(slot, ring_root_ptr, staging_segments).is_none()
        {
            slot.active.store(0, Ordering::Release);
            slot.active_command_fingerprint.store(0, Ordering::Release);
            slot.timeout_resumes.store(0, Ordering::Release);
            slot.retained_doorbell_issued.store(0, Ordering::Release);
            slot.retained_grant_id.store(0, Ordering::Release);
            slot.retained_steady_tx_fast_lane
                .store(0, Ordering::Release);
            slot.retained_steady_tx_last_progress_slice
                .store(0, Ordering::Release);
            slot.retained_steady_tx_last_progress_ticks
                .store(0, Ordering::Release);
            slot.retained_persistent_transaction_start_ticks
                .store(0, Ordering::Release);
            emit_driver_task_ring_resource_submit_status(
                contract,
                command,
                "runtime-ring-submit",
                "stage-failed",
            );
            return None;
        }
        let request = slot
            .request_seq
            .load(Ordering::Relaxed)
            .wrapping_add(1)
            .max(1);
        if contract == SDIO_HOST_DRIVER_TASK_CONTRACT && request > SDIO_ROOT_SEQUENCE_MAX {
            slot.active.store(0, Ordering::Release);
            slot.active_command_fingerprint.store(0, Ordering::Release);
            slot.timeout_resumes.store(0, Ordering::Release);
            slot.retained_doorbell_issued.store(0, Ordering::Release);
            slot.retained_grant_id.store(0, Ordering::Release);
            slot.retained_steady_tx_fast_lane
                .store(0, Ordering::Release);
            slot.retained_steady_tx_last_progress_slice
                .store(0, Ordering::Release);
            slot.retained_steady_tx_last_progress_ticks
                .store(0, Ordering::Release);
            slot.retained_persistent_transaction_start_ticks
                .store(0, Ordering::Release);
            emit_driver_task_ring_resource_submit_status(
                contract,
                command,
                "runtime-ring-submit",
                "root-sequence-domain-exhausted",
            );
            return None;
        }
        slot.request_seq.store(request, Ordering::Release);
        slot.active_command_fingerprint
            .store(command_fingerprint, Ordering::Release);
        slot.timeout_resumes.store(0, Ordering::Release);
        slot.retained_doorbell_issued.store(0, Ordering::Release);
        slot.retained_grant_id.store(0, Ordering::Release);
        slot.retained_steady_tx_fast_lane.store(
            steady_data_plane_operation.map_or(0, Cyw43SteadyDataPlaneOp::slot_value),
            Ordering::Release,
        );
        slot.retained_steady_tx_last_progress_slice
            .store(0, Ordering::Release);
        slot.retained_steady_tx_last_progress_ticks
            .store(0, Ordering::Release);
        slot.retained_persistent_transaction_start_ticks
            .store(0, Ordering::Release);
        slot.retained_persistent_signal_returned_request
            .store(0, Ordering::Release);
        command.sequence = request as u32;
        let completion_reset =
            DriverTaskCompletionRecord::fault(0, DriverTaskFaultCode::RejectedCommand);
        if mode == DriverTaskRingCommandMode::RetainedTurn {
            // Retained CYW43/SDIO turns first publish only an ABI-invisible
            // command identity. The runtime polls this ring without a
            // doorbell, so a nonzero sequence before both scheduling boosts
            // would let the physical action start outside the retained issue
            // turn. Descriptor/payload bytes are deliberately deferred to that
            // issue turn so the complete fingerprint-matched snapshot is
            // materialized only at its child-visible boundary.
            driver_task_ring_stage_command_record(
                slot,
                ring_root_ptr,
                command_ptr,
                completion_ptr,
                command,
                completion_reset,
            );
            #[cfg(test)]
            if steady_tx_fast_lane_requested {
                record_test_cyw43_steady_tx_lease_action(1);
            }
            retained_request_prepared = true;
        } else {
            driver_task_ring_publish_command_record(
                slot,
                ring_root_ptr,
                command_ptr,
                completion_ptr,
                command,
                completion_reset,
            );
        }
        driver_task_counter_add(&slot.counters.submitted_turns, 1);
        driver_task_counter_add(
            &slot.counters.staged_bytes,
            driver_task_staging_segments_bytes(staging_segments),
        );
        if command.opcode == DriverTaskOpcode::SubmitFrame.as_u16() && command.frame.len != 0 {
            driver_task_counter_add(&slot.counters.tx_frames, 1);
            driver_task_counter_add(&slot.counters.tx_bytes, usize::from(command.frame.len));
        }
        request
    };
    if request == 0 {
        slot.active.store(0, Ordering::Release);
        slot.active_command_fingerprint.store(0, Ordering::Release);
        slot.timeout_resumes.store(0, Ordering::Release);
        slot.retained_doorbell_issued.store(0, Ordering::Release);
        slot.retained_grant_id.store(0, Ordering::Release);
        slot.retained_steady_tx_fast_lane
            .store(0, Ordering::Release);
        slot.retained_steady_tx_last_progress_slice
            .store(0, Ordering::Release);
        slot.retained_steady_tx_last_progress_ticks
            .store(0, Ordering::Release);
        slot.retained_persistent_transaction_start_ticks
            .store(0, Ordering::Release);
        return None;
    }
    // Resumed callers rebuild the immutable command with sequence zero. Keep
    // that local value aligned with the already-published request; no shared
    // byte is rewritten and the staging fingerprint still fences all fields.
    command.sequence = request as u32;
    let steady_tx_fast_lane = steady_tx_fast_lane_requested
        && slot.retained_steady_tx_fast_lane.load(Ordering::Acquire) != 0;
    let persistent_transaction = persistent_transaction_requested
        && command.flags & DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION != 0;
    if retained_request_prepared && !steady_tx_fast_lane && !persistent_transaction {
        // Generic, cold, non-op11 control, untyped op7, bulk, and recovery
        // commands keep Stage as their own retained outer turn. A typed finite
        // op7 or exact persistent op11 may continue only through its existing
        // request-bound scheduler coverage. For op11 this closes the
        // sequence-zero Stage cut inside the already-admitted producer call;
        // its sequence-last commit and sole notification below remain the
        // child-visible authority transfer.
        cache_counter_batch.flush(slot);
        return None;
    }

    // Eligibility is admitted only on the fresh Stage boundary. Every later
    // retained turn remains an ordinary single-step resume; exact op11's
    // bounded completion below may never consume a post-issue phase.

    let retained_lease_turn = if mode == DriverTaskRingCommandMode::RetainedTurn {
        let mut step = || {
            step_driver_task_retained_priority_lease(
                slot,
                contract,
                command,
                request,
                command_fingerprint,
                closing_cyw43_parent_resume,
            )
        };
        let turn = if retained_request_prepared && persistent_transaction {
            complete_fresh_persistent_op11_preissue(&mut step)
        } else {
            step()
        };
        match turn {
            DriverTaskRetainedLeaseTurn::CommitRing
            | DriverTaskRetainedLeaseTurn::PublishGrant
            | DriverTaskRetainedLeaseTurn::NotifyRing
            | DriverTaskRetainedLeaseTurn::PollRing
            | DriverTaskRetainedLeaseTurn::ReadyToComplete => {}
            DriverTaskRetainedLeaseTurn::Pending => {
                cache_counter_batch.flush(slot);
                return None;
            }
            DriverTaskRetainedLeaseTurn::Failed => {
                fail_driver_task_retained_priority_lease(slot, contract);
                cache_counter_batch.flush(slot);
                return None;
            }
        }
        Some(turn)
    } else {
        None
    };
    let retained_commit_turn = retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::CommitRing);
    let retained_publish_grant_turn =
        retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::PublishGrant);
    let retained_notify_turn = retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::NotifyRing);
    let mut retained_early_completion = None;
    let retained_lease_ready_to_complete =
        retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::ReadyToComplete);
    let trace_call = driver_task_ring_call_trace_enabled(contract, command, mode);

    if retained_commit_turn {
        // Sequence publication is the issue boundary for autonomously polling
        // runtimes. Both required TCBs are already boosted. Re-materialize the
        // fingerprint-matched descriptor/payload and zero-sequence records now,
        // after every pre-issue scheduler turn and immediately before making
        // them child-visible. CYW43's dedicated descriptor and shared parent
        // payload remain disjoint from DPC writers after this boundary. The
        // generic wake notification remains deferred to the next turn. The
        // tagged urgent op7 lease and persistent op11 transaction each
        // complete this one producer transaction with their single final
        // signal below.
        if !driver_task_ring_prepare_retained_issue(
            slot,
            ring_root_ptr,
            command_ptr,
            completion_ptr,
            command,
            staging_segments,
        ) {
            fail_driver_task_retained_priority_lease(slot, contract);
            cache_counter_batch.flush(slot);
            return None;
        }
        #[cfg(test)]
        if steady_tx_fast_lane {
            record_test_cyw43_steady_tx_lease_action(2);
        }
        // Conservatively latch issued-unknown before sequence-last publication.
        // Thus any child that can observe the nonzero sequence is guaranteed
        // that root already classifies the action as non-replayable. A fault in
        // the following publication may poison unseen work, which is safer than
        // replaying work that the child could already have executed.
        slot.retained_doorbell_issued.store(1, Ordering::Release);
        #[cfg(test)]
        if steady_tx_fast_lane {
            record_test_cyw43_steady_tx_lease_action(3);
        }
        if persistent_transaction {
            // Start the full-parent containment clock before sequence-last
            // publication: the autonomously polling runtime may observe that
            // commit before the notification hint below.
            record_driver_task_persistent_transaction_start_time(slot);
        }
        driver_task_ring_commit_command_sequence(slot, ring_root_ptr, command_ptr, request as u32);
        #[cfg(test)]
        if steady_tx_fast_lane {
            record_test_cyw43_steady_tx_lease_action(4);
        }
        if !mark_driver_task_retained_priority_lease_committed(
            slot,
            driver_task_retained_uses_root_grant(contract, command),
        ) {
            // Sequence publication may already have been observed by the
            // autonomous runtime. The issued latch already poisons this
            // generation so no later turn can recommit or re-prime it.
            fail_driver_task_retained_priority_lease(slot, contract);
            cache_counter_batch.flush(slot);
            return None;
        }
        if steady_tx_fast_lane {
            let Some(operation) = steady_data_plane_operation else {
                fail_driver_task_retained_priority_lease(slot, contract);
                return None;
            };
            // The open Network lease or the request-bound pre-secure lease has
            // completed every scheduler transition. Commit -> Issued and
            // signal exactly once; all later root turns are terminal polls.
            // MR0 carries only the immutable request identity; the child
            // notification itself carries no message registers.
            crate::sel4::set_message_register(0, request as sel4_sys::seL4_Word);
            cache_counter_batch.flush(slot);
            if !signal_cyw43_steady_tx_service_lease_with(
                Cyw43SteadyTxServiceLeaseSignal {
                    slot,
                    contract,
                    command,
                    operation,
                    request,
                    fingerprint: command_fingerprint,
                    ring_root_ptr,
                },
                || {
                    if trace_call {
                        emit_driver_task_ring_call_begin(contract, endpoint, request, command);
                    }
                },
                |notification| {
                    crate::sel4::signal_unchecked(notification as sel4_sys::seL4_CPtr);
                },
            ) {
                fail_driver_task_retained_priority_lease(slot, contract);
            }
            return None;
        }
        if persistent_transaction {
            // The complete op11 descriptor and payload are now visible behind
            // the sequence-last commit. Transfer its full durable authority
            // with one scheduling hint; all later root turns are PollRing-only.
            crate::sel4::set_message_register(0, request as sel4_sys::seL4_Word);
            cache_counter_batch.flush(slot);
            if !signal_cyw43_persistent_transaction_with(
                Cyw43PersistentTransactionSignal {
                    slot,
                    contract,
                    command,
                    request,
                    fingerprint: command_fingerprint,
                    ring_root_ptr,
                },
                || {
                    if trace_call {
                        emit_driver_task_ring_call_begin(contract, endpoint, request, command);
                    }
                },
                |notification| {
                    crate::sel4::signal_unchecked(notification as sel4_sys::seL4_CPtr);
                },
            ) {
                fail_driver_task_retained_priority_lease(slot, contract);
            }
            return None;
        }
        cache_counter_batch.flush(slot);
        return None;
    }

    if retained_publish_grant_turn {
        let current = slot.retained_grant_id.load(Ordering::Acquire);
        let publication = if current == 0 {
            DriverTaskRetainedRootGrantPublication::Publish(1)
        } else {
            plan_driver_task_retained_root_grant_publication_with(
                command,
                current,
                || {
                    let completion = read_driver_task_ring_completion(
                        &mut cache_counter_batch,
                        ring_root_ptr,
                        completion_ptr,
                        request,
                    );
                    (completion.sequence == request as u32).then_some(completion)
                },
                || driver_task_ring_read_continuation_grant(ring_root_ptr),
            )
        };
        if !driver_task_retained_lease_identity_matches(
            slot,
            contract,
            request,
            command_fingerprint,
        ) || DriverTaskRetainedLeasePhase::from_usize(
            slot.retained_priority_lease_phase.load(Ordering::Acquire),
        ) != Some(DriverTaskRetainedLeasePhase::GrantRequired)
            || slot.retained_grant_id.load(Ordering::Acquire) != current
        {
            fail_driver_task_retained_priority_lease(slot, contract);
            cache_counter_batch.flush(slot);
            return None;
        }
        match publication {
            DriverTaskRetainedRootGrantPublication::LateCompletion(completion) => {
                if slot
                    .retained_priority_lease_phase
                    .compare_exchange(
                        DriverTaskRetainedLeasePhase::GrantRequired.as_usize(),
                        DriverTaskRetainedLeasePhase::Issued.as_usize(),
                        Ordering::AcqRel,
                        Ordering::Acquire,
                    )
                    .is_err()
                {
                    fail_driver_task_retained_priority_lease(slot, contract);
                    cache_counter_batch.flush(slot);
                    return None;
                }
                retained_early_completion = Some(completion);
            }
            DriverTaskRetainedRootGrantPublication::Publish(next) => {
                if !driver_task_ring_publish_continuation_grant(slot, ring_root_ptr, command, next)
                {
                    fail_driver_task_retained_priority_lease(slot, contract);
                    cache_counter_batch.flush(slot);
                    return None;
                }
                #[cfg(test)]
                TEST_ROOT_GRANT_PUBLICATIONS.fetch_add(1, Ordering::AcqRel);
                slot.retained_grant_id.store(next, Ordering::Release);
                if !mark_driver_task_retained_priority_lease_granted(slot) {
                    fail_driver_task_retained_priority_lease(slot, contract);
                }
                cache_counter_batch.flush(slot);
                return None;
            }
            DriverTaskRetainedRootGrantPublication::Invalid => {
                fail_driver_task_retained_priority_lease(slot, contract);
                cache_counter_batch.flush(slot);
                return None;
            }
        }
    }

    // MR0 carries only the current ring request sequence. Rewriting it before
    // each send is harmless and keeps resumed prompt slices aligned with the
    // already staged command.
    crate::sel4::set_message_register(0, request as sel4_sys::seL4_Word);

    if retained_notify_turn {
        let root_grant = driver_task_retained_uses_root_grant(contract, command);
        if persistent_transaction {
            // Persistent op11 must cross Committed -> Issued in the same
            // sequence-last producer transaction. Reaching a later notify turn
            // would create a second scheduling edge, so fail closed.
            fail_driver_task_retained_priority_lease(slot, contract);
            cache_counter_batch.flush(slot);
            return None;
        }
        if !admit_driver_task_retained_foreground_wake(slot, contract) {
            // Keep Committed/Granted and the exact command immutable. A later
            // EventPump turn rechecks the architectural counter; no endpoint,
            // grant, device state, retry counter, or MCS reservation changes
            // while this generated-period boundary is closed.
            cache_counter_batch.flush(slot);
            return None;
        }
        // The command is already immutable and visible. Root-generation
        // CYW43 descriptor continuations signal the child-bound notification;
        // unrelated runtime contracts retain their endpoint rendezvous.
        if trace_call {
            emit_driver_task_ring_call_begin(contract, endpoint, request, command);
        }
        if root_grant {
            cache_counter_batch.flush(slot);
            if signal_driver_task_retained_root_grant_with(
                DriverTaskRetainedRootGrantContinuation {
                    slot,
                    contract,
                    command,
                    request,
                    fingerprint: command_fingerprint,
                    ring_root_ptr,
                    #[cfg(test)]
                    record_test_actions: true,
                },
                |notification| {
                    crate::sel4::signal_unchecked(notification as sel4_sys::seL4_CPtr);
                },
            ) == DriverTaskRetainedRootGrantNotify::Invalid
            {
                fail_driver_task_retained_priority_lease(slot, contract);
            }
            return None;
        }
        let info = sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1);
        if !mcs_nonblocking_root_producer_allows_send(slot, endpoint) {
            cache_counter_batch.flush(slot);
            return None;
        }
        if !mark_driver_task_retained_priority_lease_issued(slot, false) {
            fail_driver_task_retained_priority_lease(slot, contract);
            cache_counter_batch.flush(slot);
            return None;
        }
        driver_task_counter_add(&slot.counters.send_attempts, 1);
        cache_counter_batch.flush(slot);
        crate::sel4::send_nb_unchecked(endpoint as sel4_sys::seL4_CPtr, info);
        return None;
    }

    let mut completion = if let Some(completion) = retained_early_completion {
        completion
    } else {
        read_driver_task_ring_completion(
            &mut cache_counter_batch,
            ring_root_ptr,
            completion_ptr,
            request,
        )
    };
    let mut start_ticks = None;
    let _priority_restore = if driver_task_ring_mode_uses_bounded_send(mode)
        && mode != DriverTaskRingCommandMode::RetainedTurn
    {
        boost_driver_task_priorities_for_bounded_turn(contract, command)
    } else {
        (None, None)
    };

    let mut progress_advanced = false;
    let mut timeout_progress = driver_task_ring_empty_progress_record();
    if driver_task_ring_mode_uses_bounded_send(mode) {
        let retained_doorbell_issued = mode == DriverTaskRingCommandMode::RetainedTurn
            && slot.retained_doorbell_issued.load(Ordering::Acquire) != 0;
        if trace_call && (!same_request_resume || !retained_doorbell_issued) {
            emit_driver_task_ring_call_begin(contract, endpoint, request, command);
        }
        if mode.records_latency() && (!same_request_resume || !retained_doorbell_issued) {
            start_ticks = driver_task_counter_ticks();
        }
        let attempts = if mode == DriverTaskRingCommandMode::RetainedTurn {
            0
        } else {
            driver_task_ring_attempt_limit(contract, command, mode)
        };
        if completion.sequence != request as u32 {
            let info = sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1);
            let mut send_attempts = 0usize;
            let mut yield_count = 0usize;
            for attempt in 0..attempts {
                if !mcs_nonblocking_root_producer_allows_send(slot, endpoint) {
                    break;
                }
                if !driver_task_ring_deadline_allows_attempt(recovery_deadline.as_deref_mut()) {
                    break;
                }
                send_attempts = send_attempts.saturating_add(1);
                crate::sel4::send_nb_unchecked(endpoint as sel4_sys::seL4_CPtr, info);
                if mode == DriverTaskRingCommandMode::RetainedTurn {
                    mark_driver_task_retained_priority_lease_issued(
                        slot,
                        driver_task_retained_uses_root_grant(contract, command),
                    );
                }
                if mode != DriverTaskRingCommandMode::RetainedTurn {
                    yield_count = yield_count.saturating_add(1);
                    crate::sel4::yield_now();
                }
                if attempt % DRIVER_TASK_RING_CACHE_POLL_INTERVAL == 0 {
                    cache_counter_batch.record_completion_invalidate(ring_root_ptr);
                }
                // SAFETY: The completion pointer addresses the same validated ring
                // page. A matching sequence means the isolated runtime observed the
                // nonblocking send and published the primitive completion record.
                completion = unsafe { core::ptr::read_volatile(completion_ptr) };
                if completion.sequence == request as u32 {
                    cache_counter_batch.record_completion_invalidate(ring_root_ptr);
                    // SAFETY: The matching sequence is re-read after the acquire
                    // barrier before root consumes completion fields or payload.
                    completion = unsafe { core::ptr::read_volatile(completion_ptr) };
                    if completion.sequence != request as u32 {
                        continue;
                    }
                    if driver_task_ring_completion_trace_enabled(trace_call, command, completion) {
                        emit_driver_task_ring_call_return(contract, endpoint, request, completion);
                    }
                    break;
                }
            }
            driver_task_counter_add(&slot.counters.send_attempts, send_attempts);
            driver_task_counter_add(&slot.counters.yield_count, yield_count);
        } else if driver_task_ring_completion_trace_enabled(trace_call, command, completion) {
            emit_driver_task_ring_call_return(contract, endpoint, request, completion);
        }
        if completion.sequence != request as u32 {
            driver_task_counter_add(&slot.counters.timeouts, 1);
            let trace_timeout =
                driver_task_ring_timeout_trace_enabled(trace_call, contract, command);
            let progress = driver_task_ring_read_progress_record(ring_root_ptr);
            timeout_progress = progress;
            if contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
                && cyw43_sdio_pair_restart_progress(progress)
            {
                // The runtime no longer has a provable owner for the in-flight
                // child turn. Do not run generic timeout cleanup or consume a
                // late completion. Publish the supervisor request, release the
                // root writer/priority guards, and let the caller (or the next
                // CYW43 submission) enter the fenced pair restart.
                record_driver_task_ring_progress(slot, progress);
                request_cyw43_sdio_pair_restart();
                cache_counter_batch.flush(slot);
                drop(_priority_restore);
                drop(_root_producer_guard);
                return None;
            }
            let ordinary_progress_advanced = driver_task_ring_progress_advanced_for_request(
                slot,
                progress,
                request as u32,
                command.aux0,
            );
            progress_advanced = if steady_tx_fast_lane
                && retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::PollRing)
            {
                // Generic phase breadcrumbs are diagnostic and can repeat or
                // be rewritten by another logical turn. Only the exact
                // sequence-last parent slice may rebase this finite inactivity
                // bound.
                driver_task_ring_steady_service_progress_advanced(slot, ring_root_ptr, command)
            } else {
                ordinary_progress_advanced
            };
            if driver_task_ring_progress_should_record_for_request(
                slot,
                progress,
                request as u32,
                command.aux0,
            ) {
                record_driver_task_ring_progress(slot, progress);
            }
            if trace_timeout {
                emit_driver_task_ring_call_timeout(
                    contract, endpoint, request, command, mode, attempts, progress,
                );
            }
            if trace_timeout {
                emit_driver_task_ring_call_progress(contract, request, command, mode, progress);
            }
        }
    } else if cfg!(sel4_config_kernel_mcs)
        || (physical_pi_driver_task_only_owner_state_active() && cfg!(not(sel4_config_kernel_mcs)))
    {
        // Synchronous MCS commands use Call -> Recv -> explicit Reply so the
        // root caller blocks until either the active-SC runtime publishes its
        // completion or the independent supervisor returns the typed fault
        // result. Classic Pi keeps its existing blocking Call behavior.
        if trace_call {
            emit_driver_task_ring_call_begin(contract, endpoint, request, command);
        }
        if mode.records_latency() {
            start_ticks = driver_task_counter_ticks();
        }
        // The fixed ABI uses MR0 as the request sequence. Re-writing it
        // immediately before the blocking call keeps diagnostic UART emission
        // out of the message-register contract.
        crate::sel4::set_message_register(0, request as sel4_sys::seL4_Word);
        #[cfg(sel4_config_kernel_mcs)]
        let call_admitted = begin_driver_task_mcs_call(slot, request as u32);
        #[cfg(not(sel4_config_kernel_mcs))]
        let call_admitted = true;

        if call_admitted {
            let _ = crate::sel4::call_unchecked(
                endpoint as sel4_sys::seL4_CPtr,
                sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1),
            );
            #[cfg(sel4_config_kernel_mcs)]
            let call_completed_normally = crate::sel4::message_register(0)
                != pi4_driver_abi::DRIVER_RUNTIME_MCS_FAULTED_CALL_RESULT as sel4_sys::seL4_Word
                && finish_driver_task_mcs_normal_reply(slot, request as u32);
            #[cfg(not(sel4_config_kernel_mcs))]
            let call_completed_normally = true;

            if call_completed_normally {
                cache_counter_batch.record_completion_invalidate(ring_root_ptr);
                // SAFETY: The completion pointer addresses the same validated
                // ring page; the reply boundary guarantees the isolated
                // runtime published the shared-frame result first.
                completion = unsafe { core::ptr::read_volatile(completion_ptr) };
            } else {
                completion = DriverTaskCompletionRecord::fault(
                    request as u32,
                    DriverTaskFaultCode::DeviceUnavailable,
                );
                completion.result = pi4_driver_abi::DRIVER_RUNTIME_MCS_FAULTED_CALL_RESULT;
            }
        } else {
            // Admission is closed before or during reconstruction. Return the
            // same typed result as the fault supervisor without issuing an
            // endpoint Call against old-generation authority.
            completion = DriverTaskCompletionRecord::fault(
                request as u32,
                DriverTaskFaultCode::DeviceUnavailable,
            );
            completion.result = pi4_driver_abi::DRIVER_RUNTIME_MCS_FAULTED_CALL_RESULT;
        }
        if driver_task_ring_completion_trace_enabled(trace_call, command, completion) {
            emit_driver_task_ring_call_return(contract, endpoint, request, completion);
        }
    } else {
        start_ticks = driver_task_counter_ticks();
        let info = sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1);
        let mut send_attempts = 0usize;
        let mut yield_count = 0usize;
        for attempt in 0..256 {
            send_attempts = send_attempts.saturating_add(1);
            crate::sel4::send_nb_unchecked(endpoint as sel4_sys::seL4_CPtr, info);
            yield_count = yield_count.saturating_add(1);
            crate::sel4::yield_now();
            if attempt % DRIVER_TASK_RING_CACHE_POLL_INTERVAL == 0 {
                cache_counter_batch.record_completion_invalidate(ring_root_ptr);
            }
            // SAFETY: The completion pointer addresses the same validated ring
            // page; a matching sequence means the isolated trampoline observed the
            // command through the shared frame.
            completion = unsafe { core::ptr::read_volatile(completion_ptr) };
            if completion.sequence == request as u32 {
                cache_counter_batch.record_completion_invalidate(ring_root_ptr);
                // SAFETY: The matching sequence is re-read after the acquire
                // barrier before root consumes completion fields or payload.
                completion = unsafe { core::ptr::read_volatile(completion_ptr) };
                if completion.sequence != request as u32 {
                    continue;
                }
                break;
            }
        }
        driver_task_counter_add(&slot.counters.send_attempts, send_attempts);
        driver_task_counter_add(&slot.counters.yield_count, yield_count);
    }

    let mut persistent_transaction_waiting = false;
    if persistent_transaction
        && completion.sequence != request as u32
        && retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::PollRing)
    {
        match cyw43_persistent_transaction_parent_condition(request as u32) {
            Cyw43PersistentTransactionParentCondition::Waiting => {
                // Root's scheduling boundary normally parks this exact durable
                // condition before entering HAL. A race that reaches this
                // final check still performs no operation, ages no scheduler
                // counter, and creates no authority.
                persistent_transaction_waiting = true;
            }
            Cyw43PersistentTransactionParentCondition::TerminalVisible => {
                completion = read_driver_task_ring_completion(
                    &mut cache_counter_batch,
                    ring_root_ptr,
                    completion_ptr,
                    request,
                );
                if completion.sequence != request as u32 {
                    // A sequence-last terminal is immutable. Losing it after a
                    // stable read is an issued-unknown transport violation.
                    fail_driver_task_retained_priority_lease(slot, contract);
                    cache_counter_batch.flush(slot);
                    return None;
                }
            }
            Cyw43PersistentTransactionParentCondition::DeadlineFault => {
                emit_driver_task_ring_call_abort(
                    contract,
                    endpoint,
                    request,
                    command,
                    mode,
                    "persistent-transaction-lifetime",
                    1,
                    timeout_progress,
                );
                cache_counter_batch.flush(slot);
                return None;
            }
            Cyw43PersistentTransactionParentCondition::NotExact => {
                fail_driver_task_retained_priority_lease(slot, contract);
                cache_counter_batch.flush(slot);
                return None;
            }
        }
    }

    let mut timeout_count = 0usize;
    let mut timeout_keep_limit = 0usize;
    let mut keep_active_on_timeout = if persistent_transaction_waiting {
        true
    } else if completion.sequence != request as u32 {
        let (keep_active, count) = driver_task_ring_timeout_keep_decision(
            slot,
            contract,
            command,
            mode,
            request as u32,
            progress_advanced,
        );
        timeout_count = count;
        if keep_active {
            timeout_keep_limit = driver_task_ring_timeout_keep_active_limit_for_progress(
                slot,
                contract,
                command,
                mode,
                request as u32,
            );
        }
        keep_active
    } else {
        false
    };

    if steady_tx_fast_lane
        && completion.sequence != request as u32
        && retained_lease_turn == Some(DriverTaskRetainedLeaseTurn::PollRing)
    {
        // The tagged parent already transferred its complete finite authority
        // with the initial sequence-last commit and sole notification. An
        // Issued resume is therefore completion-poll-only: it must never mint,
        // re-signal, or acknowledge continuation authority. Exact newer
        // runtime semantic-progress records can rebase the inactivity fence;
        // repeated or wrong-identity records cannot. The hardware path uses
        // CNTVCT age only to trigger the stable terminal fence and recovery,
        // never to create a wake or treat completion polls as elapsed time.
        if keep_active_on_timeout {
            driver_task_counter_add(&slot.counters.keep_active_timeouts, 1);
        }
        if keep_active_on_timeout
            && driver_task_ring_timeout_trace_enabled(trace_call, contract, command)
        {
            emit_driver_task_ring_call_keep_active(
                contract,
                endpoint,
                request,
                command,
                mode,
                timeout_count,
                timeout_keep_limit,
                progress_advanced,
                timeout_progress,
            );
        }
        cache_counter_batch.flush(slot);

        let mut final_terminal_cache_counter_batch = DriverTaskCacheCounterBatch::new();
        let first = read_driver_task_ring_completion(
            &mut final_terminal_cache_counter_batch,
            ring_root_ptr,
            completion_ptr,
            request,
        );
        let late = if first.sequence == request as u32 {
            first
        } else {
            read_driver_task_ring_completion(
                &mut final_terminal_cache_counter_batch,
                ring_root_ptr,
                completion_ptr,
                request,
            )
        };
        final_terminal_cache_counter_batch.flush(slot);
        if late.sequence != request as u32 {
            if keep_active_on_timeout {
                return None;
            }
            // The fault-containment deadline expired after a stable terminal
            // miss. Treat this issued request as unknown and enter coordinated
            // pair recovery without creating another scheduling edge.
            driver_task_counter_add(&slot.counters.aborts, 1);
            emit_driver_task_ring_call_abort(
                contract,
                endpoint,
                request,
                command,
                mode,
                "steady-service-inactivity",
                timeout_count,
                timeout_progress,
            );
            // The exact tagged request crossed its sequence-last issue
            // boundary. A finite no-progress expiry is issued-unknown and must
            // enter the coordinated CYW43/SDIO recovery lane, never clear the
            // slot locally or replay the Ethernet frame.
            fail_driver_task_retained_priority_lease(slot, contract);
            return None;
        }
        completion = late;
        keep_active_on_timeout = false;
        if driver_task_ring_completion_trace_enabled(trace_call, command, completion) {
            emit_driver_task_ring_call_return(contract, endpoint, request, completion);
        }
    }

    if mode == DriverTaskRingCommandMode::RetainedTurn && completion.sequence == request as u32 {
        if retained_lease_ready_to_complete {
            if !finish_driver_task_retained_priority_lease(
                slot,
                contract,
                command,
                request,
                command_fingerprint,
            ) {
                fail_driver_task_retained_priority_lease(slot, contract);
                cache_counter_batch.flush(slot);
                return None;
            }
        } else {
            match latch_driver_task_retained_priority_lease_completion(slot) {
                DriverTaskRetainedLeaseTurn::Pending => {
                    cache_counter_batch.flush(slot);
                    return None;
                }
                DriverTaskRetainedLeaseTurn::ReadyToComplete => {
                    if !finish_driver_task_retained_priority_lease(
                        slot,
                        contract,
                        command,
                        request,
                        command_fingerprint,
                    ) {
                        fail_driver_task_retained_priority_lease(slot, contract);
                        cache_counter_batch.flush(slot);
                        return None;
                    }
                }
                DriverTaskRetainedLeaseTurn::CommitRing
                | DriverTaskRetainedLeaseTurn::PublishGrant
                | DriverTaskRetainedLeaseTurn::NotifyRing
                | DriverTaskRetainedLeaseTurn::PollRing
                | DriverTaskRetainedLeaseTurn::Failed => {
                    fail_driver_task_retained_priority_lease(slot, contract);
                    cache_counter_batch.flush(slot);
                    return None;
                }
            }
        }
    } else if retained_lease_ready_to_complete {
        fail_driver_task_retained_priority_lease(slot, contract);
        cache_counter_batch.flush(slot);
        return None;
    }

    let retained_wake_armed = mode != DriverTaskRingCommandMode::RetainedTurn
        || !keep_active_on_timeout
        || arm_driver_task_retained_priority_lease_wake_retry(
            slot,
            contract,
            command,
            ring_root_ptr,
            request,
            command_fingerprint,
        );
    if !retained_wake_armed {
        // The command may already have executed one physical quantum. A torn
        // continuation/wake cursor is therefore issued-unknown. CYW43/SDIO
        // poison the pair generation; other retained services fail closed
        // instead of mistaking transport state for a normal Pending turn.
        fail_driver_task_retained_priority_lease(slot, contract);
        cache_counter_batch.flush(slot);
        return None;
    }
    if keep_active_on_timeout {
        driver_task_counter_add(&slot.counters.keep_active_timeouts, 1);
    }
    if keep_active_on_timeout
        && driver_task_ring_timeout_trace_enabled(trace_call, contract, command)
    {
        emit_driver_task_ring_call_keep_active(
            contract,
            endpoint,
            request,
            command,
            mode,
            timeout_count,
            timeout_keep_limit,
            progress_advanced,
            timeout_progress,
        );
    }
    if completion.sequence == request as u32
        && persistent_transaction
        && !publish_cyw43_semantic_terminal_receipt(
            slot,
            request as u32,
            command,
            command_fingerprint,
        )
    {
        // The child terminal is already durable but its replacement authority
        // could not be published. Preserve the active slot and enter the sole
        // pair-recovery lane; never return a body without a lifetime receipt.
        request_cyw43_sdio_pair_restart();
        fail_driver_task_retained_priority_lease(slot, contract);
        cache_counter_batch.flush(slot);
        return None;
    }
    if completion.sequence == request as u32 || !keep_active_on_timeout {
        slot.active.store(0, Ordering::Release);
        slot.active_command_fingerprint.store(0, Ordering::Release);
        slot.timeout_resumes.store(0, Ordering::Release);
        slot.retained_doorbell_issued.store(0, Ordering::Release);
        slot.retained_grant_id.store(0, Ordering::Release);
        slot.retained_steady_tx_fast_lane
            .store(0, Ordering::Release);
        slot.retained_steady_tx_last_progress_slice
            .store(0, Ordering::Release);
        slot.retained_steady_tx_last_progress_ticks
            .store(0, Ordering::Release);
        slot.retained_persistent_transaction_start_ticks
            .store(0, Ordering::Release);
        if completion.sequence != request as u32 && timeout_count != 0 {
            driver_task_counter_add(&slot.counters.aborts, 1);
            emit_driver_task_ring_call_abort(
                contract,
                endpoint,
                request,
                command,
                mode,
                "timeout-resume-limit",
                timeout_count,
                timeout_progress,
            );
        }
    }
    cache_counter_batch.flush(slot);
    if completion.sequence == request as u32 {
        driver_task_record_completion_counters(slot, completion);
        if completion.code == DriverTaskCompletionCode::Fault.as_u16()
            && driver_task_ring_completion_trace_enabled(trace_call, command, completion)
        {
            let progress = driver_task_ring_read_progress_record(ring_root_ptr);
            if driver_task_ring_progress_should_record_for_request(
                slot,
                progress,
                request as u32,
                command.aux0,
            ) {
                record_driver_task_ring_progress(slot, progress);
            }
            emit_driver_task_ring_call_progress(contract, request, command, mode, progress);
        }
        if let (Some(start_ticks), Some(end_ticks), Some(counter_frequency)) = (
            start_ticks,
            driver_task_counter_ticks(),
            driver_task_counter_frequency(),
        ) {
            let elapsed_us = driver_task_elapsed_us(start_ticks, end_ticks, counter_frequency);
            record_observed_service_us(contract, elapsed_us);
        }
        Some(completion)
    } else {
        None
    }
}

