#[cfg(feature = "kernel")]
fn driver_task_hdmi_progress_line_if_new_with_gate(
    gate: &AtomicUsize,
    contract: DriverTaskContract,
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
) -> Option<heapless::String<192>> {
    let line =
        driver_task_resource_hdmi_progress_line(contract, hot_path, stage, status, completion)?;
    if !driver_task_hdmi_progress_repeat_allowed_with_gate(
        gate, hot_path, stage, status, completion,
    ) {
        return None;
    }
    Some(line)
}

#[cfg(feature = "kernel")]
fn driver_task_hdmi_progress_repeat_allowed_with_gate(
    gate: &AtomicUsize,
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
) -> bool {
    let key = driver_task_hdmi_progress_key(hot_path, stage, status, completion);
    gate.swap(key, Ordering::AcqRel) != key
}

fn driver_task_hdmi_progress_key(
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
) -> usize {
    // Hash string contents rather than their addresses: Rust does not guarantee
    // that identical string literals share one allocation, so pointer identity
    // would make repeat suppression depend on code generation and call site.
    let mut key = 0xcbf2_9ce4_8422_2325u64;
    for byte in stage
        .as_bytes()
        .iter()
        .copied()
        .chain(core::iter::once(0xff))
        .chain(status.as_bytes().iter().copied())
    {
        key ^= u64::from(byte);
        key = key.wrapping_mul(0x0000_0100_0000_01b3);
    }
    let completion_key = completion.map_or(0, |completion| {
        (u64::from(completion.detail) << 32) ^ completion.result as u64
    });
    key ^= u64::from(hot_path.as_u32()).rotate_left(11);
    key ^= completion_key.rotate_left(23);
    key as usize
}

fn driver_task_resource_hdmi_progress_line(
    _contract: DriverTaskContract,
    hot_path: DriverTaskHotPath,
    stage: &'static str,
    status: &'static str,
    completion: Option<DriverTaskCompletionRecord>,
) -> Option<heapless::String<192>> {
    use core::fmt::Write;

    if !driver_task_resource_status_mirrors_to_hdmi(hot_path, stage, status) {
        return None;
    }
    let mut line = heapless::String::<192>::new();
    let _ = write!(
        line,
        "[drivers] {} {} {}",
        driver_task_hdmi_progress_label(hot_path),
        stage,
        status,
    );
    if let Some(completion) = completion {
        let _ = write!(
            line,
            " detail=0x{:04x} result={}",
            completion.detail, completion.result
        );
    }
    Some(line)
}

fn driver_task_resource_status_mirrors_to_hdmi(
    hot_path: DriverTaskHotPath,
    stage: &str,
    status: &str,
) -> bool {
    if hot_path == DriverTaskHotPath::HdmiText {
        return false;
    }
    if hot_path == DriverTaskHotPath::UsbKeyboard {
        return driver_task_usb_resource_status_mirrors_to_hdmi(stage, status);
    }
    if stage == "cyw43-firmware-chunk" && status == "ready" {
        return false;
    }
    driver_task_high_impact_status_mirrors_to_hdmi(status)
        || driver_task_startup_milestone_mirrors_to_hdmi(hot_path, stage, status)
}

fn driver_task_high_impact_status_mirrors_to_hdmi(status: &str) -> bool {
    status == "begin"
        || status == "fault"
        || status == "failed"
        || status == "no-reply"
        || status == "unexpected-completion"
        || status == "descriptor-rejected"
        || status.ends_with("failed")
        || status.ends_with("-fail")
        || status.starts_with("blocked")
}

fn driver_task_usb_resource_status_mirrors_to_hdmi(stage: &str, status: &str) -> bool {
    if matches!(
        (stage, status),
        (
            "usb-engine-init",
            "fault" | "no-reply" | "busy" | "poll-timeout"
        ) | (
            "usb-xhci-init",
            "fault" | "no-reply" | "busy" | "poll-timeout"
        ) | (
            "usb-keyboard-first-report",
            "no-reply" | "busy" | "poll-timeout"
        ) | (
            "usb-keyboard-enumeration-resume",
            "address-device-failed" | "no-reply"
        )
    ) {
        return false;
    }
    if driver_task_high_impact_status_mirrors_to_hdmi(status)
        || status == "invalid-contract"
        || status == "slot-missing"
        || status == "no-endpoint"
        || status == "ring-missing"
        || status == "busy"
        || status == "poll-timeout"
        || status == "tx-no-reply"
    {
        return true;
    }
    driver_task_startup_milestone_mirrors_to_hdmi(DriverTaskHotPath::UsbKeyboard, stage, status)
}

fn driver_task_startup_milestone_mirrors_to_hdmi(
    hot_path: DriverTaskHotPath,
    stage: &str,
    status: &str,
) -> bool {
    if matches!(status, "deferred" | "pending" | "resumed" | "progress") {
        return false;
    }
    matches!(
        (hot_path, stage, status),
        (
            DriverTaskHotPath::SerialConsole,
            "runtime-descriptor-replay" | "serial-runtime-init" | "serial-owner-state",
            "ready"
        ) | (
            DriverTaskHotPath::UsbKeyboard,
            "usb-runtime-descriptor-replay" | "runtime-descriptor-replay" | "usb-engine-init",
            "begin" | "ready"
        ) | (
            DriverTaskHotPath::UsbKeyboard,
            "usb-keyboard-enumeration-resume",
            "begin" | "command-ring-ready" | "root-port-connected" | "device-addressed" | "ready"
        ) | (
            DriverTaskHotPath::UsbKeyboard,
            "usb-keyboard-enumeration"
                | "usb-xhci-init"
                | "usb-keyboard-first-report"
                | "usb-owner-state",
            "ready"
        ) | (
            DriverTaskHotPath::PcieRoot,
            "runtime-descriptor-replay"
                | "usb-prereq-pcie-replay"
                | "usb-prereq-pcie-hal-prep"
                | "pcie-owner-state",
            "ready"
        ) | (
            DriverTaskHotPath::PcieRoot,
            "usb-prereq-pcie-engine-init",
            "adopt-hal-prepared-descriptor" | "ready-adopted"
        ) | (
            DriverTaskHotPath::SdioHost,
            "runtime-descriptor-replay"
                | "sdio-engine-init"
                | "sdio-owner-state"
                | "cyw43-sdio-prereq"
                | "cyw43-post-release-sdio-reprime",
            "ready"
        ) | (
            DriverTaskHotPath::Cyw43Wifi,
            "runtime-descriptor-replay"
                | "net-engine-init"
                | "cyw43-transport-init"
                | "cyw43-firmware-prep"
                | "cyw43-nvram-tail"
                | "cyw43-firmware-release"
                | "cyw43-firmware"
                | "cyw43-function2"
                | "cyw43-owner-state",
            "ready"
        ) | (
            DriverTaskHotPath::GenetNic,
            "runtime-descriptor-replay" | "net-engine-init" | "genet-owner-state",
            "ready"
        )
    )
}

const fn driver_task_hdmi_progress_label(hot_path: DriverTaskHotPath) -> &'static str {
    match hot_path {
        DriverTaskHotPath::SerialConsole => "Serial",
        DriverTaskHotPath::UsbKeyboard => "USB",
        DriverTaskHotPath::HdmiText => "HDMI",
        DriverTaskHotPath::GenetNic => "GENET",
        DriverTaskHotPath::Cyw43Wifi => "WiFi",
        DriverTaskHotPath::SdioHost => "SDIO",
        DriverTaskHotPath::PcieRoot => "PCIe",
    }
}

