    #[cfg(feature = "kernel")]
    #[test]
    fn retained_foreground_wake_obeys_generated_period_boundary() {
        const PI_COUNTER_HZ: u64 = 54_000_000;
        const DRIVER_PERIOD_US: u32 = 10_000;
        const PERIOD_TICKS: u64 = 540_000;

        assert!(driver_task_retained_foreground_wake_due_at(
            0,
            17,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(!driver_task_retained_foreground_wake_due_at(
            1_000_000,
            1_000_000 + PERIOD_TICKS - 1,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(driver_task_retained_foreground_wake_due_at(
            1_000_000,
            1_000_000 + PERIOD_TICKS,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(driver_task_retained_foreground_wake_due_at(
            u64::MAX - 10,
            PERIOD_TICKS - 11,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(!driver_task_retained_foreground_wake_due_at(
            1,
            2,
            0,
            PI_COUNTER_HZ,
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_foreground_wake_waits_for_root_and_runtime_boundaries() {
        const PI_COUNTER_HZ: u64 = 54_000_000;
        const DRIVER_PERIOD_US: u32 = 10_000;
        const PERIOD_TICKS: u64 = 540_000;
        let current = 2_000_000;
        let root_release = current - PERIOD_TICKS;
        let delayed_runtime_entry = root_release + 4_000;

        assert!(driver_task_retained_foreground_boundaries_due_at(
            root_release,
            0,
            current,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(!driver_task_retained_foreground_boundaries_due_at(
            root_release,
            delayed_runtime_entry,
            current,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
        assert!(driver_task_retained_foreground_boundaries_due_at(
            root_release,
            delayed_runtime_entry,
            delayed_runtime_entry + PERIOD_TICKS,
            DRIVER_PERIOD_US,
            PI_COUNTER_HZ,
        ));
    }

