    #[cfg(feature = "kernel")]
    struct RetainedPairRestartTestExecutor {
        calls: Vec<(&'static str, Cyw43SdioPairRestartOperation)>,
        fail_running_at: Option<usize>,
        running_calls: usize,
        failure_injected: bool,
        failed_engine_completion: Option<(Cyw43SdioPairMember, DriverTaskCompletionRecord)>,
        pending_operation: Option<Cyw43SdioPairRestartOperation>,
        pending_remaining: usize,
        physical_lifetime: DriverRuntimeSdioPhysicalLifetimeRecord,
        published_epoch: u32,
    }

    #[cfg(feature = "kernel")]
    impl RetainedPairRestartTestExecutor {
        fn success() -> Self {
            Self {
                calls: Vec::new(),
                fail_running_at: None,
                running_calls: 0,
                failure_injected: false,
                failed_engine_completion: None,
                pending_operation: None,
                pending_remaining: 0,
                physical_lifetime: DriverRuntimeSdioPhysicalLifetimeRecord::empty(),
                published_epoch: 7,
            }
        }

        fn with_published_epoch(mut self, epoch: u32) -> Self {
            self.published_epoch = epoch;
            self
        }

        fn failure_at(index: usize) -> Self {
            Self {
                fail_running_at: Some(index),
                ..Self::success()
            }
        }

        fn engine_failure(
            member: Cyw43SdioPairMember,
            completion: DriverTaskCompletionRecord,
        ) -> Self {
            Self {
                failed_engine_completion: Some((member, completion)),
                ..Self::success()
            }
        }
    }

    #[cfg(feature = "kernel")]
    impl Cyw43SdioPairRestartExecutor for RetainedPairRestartTestExecutor {
        fn execute(
            &mut self,
            cursor: &mut Cyw43SdioPairRestartCursor,
            operation: Cyw43SdioPairRestartOperation,
        ) -> Cyw43SdioPairRestartOperationOutcome {
            let running = cursor.mode == Cyw43SdioPairRestartCursorMode::Running;
            let action = if running {
                current_cyw43_sdio_pair_restart_action(cursor)
                    .map(Cyw43SdioPairRestartAction::as_str)
                    .unwrap_or("invalid-action")
            } else {
                "failure-fence"
            };
            self.calls.push((action, operation));
            if running {
                let call = self.running_calls;
                self.running_calls = self.running_calls.saturating_add(1);
                if let Cyw43SdioPairRestartOperation::ReplayEngine(member) = operation {
                    if let Some((failed_member, completion)) = self.failed_engine_completion {
                        if member == failed_member {
                            return Cyw43SdioPairRestartOperationOutcome::FailedCompletion(
                                completion,
                            );
                        }
                    }
                }
                if !self.failure_injected && self.fail_running_at == Some(call) {
                    self.failure_injected = true;
                    return Cyw43SdioPairRestartOperationOutcome::Failed;
                }
            }
            if self.pending_operation == Some(operation) && self.pending_remaining != 0 {
                self.pending_remaining = self.pending_remaining.saturating_sub(1);
                return Cyw43SdioPairRestartOperationOutcome::Pending;
            }
            match operation {
                Cyw43SdioPairRestartOperation::ReadCardInterrupt(_) => {
                    Cyw43SdioPairRestartOperationOutcome::Value(0)
                }
                Cyw43SdioPairRestartOperation::ReplayEngine(member) => {
                    let mut completion = DriverTaskCompletionRecord::progress(1, 1);
                    if member == Cyw43SdioPairMember::Sdio {
                        completion.detail = DRIVER_RUNTIME_SDIO_INIT_DETAIL_READY;
                        self.physical_lifetime = DriverRuntimeSdioPhysicalLifetimeRecord {
                            begun_epoch: 1,
                            completed_epoch: 1,
                            ..DriverRuntimeSdioPhysicalLifetimeRecord::empty()
                        };
                    }
                    Cyw43SdioPairRestartOperationOutcome::Completion(completion)
                }
                Cyw43SdioPairRestartOperation::AdvanceEpoch => {
                    Cyw43SdioPairRestartOperationOutcome::Value(self.published_epoch)
                }
                _ => Cyw43SdioPairRestartOperationOutcome::Complete,
            }
        }

        fn physical_lifetime_snapshot(
            &mut self,
        ) -> Option<DriverRuntimeSdioPhysicalLifetimeRecord> {
            Some(self.physical_lifetime)
        }
    }

    #[cfg(feature = "kernel")]
    fn drive_retained_pair_restart_test(
        cursor: &mut Cyw43SdioPairRestartCursor,
        executor: &mut RetainedPairRestartTestExecutor,
    ) -> Cyw43SdioPairRestartTurn {
        let mut now = 1u64;
        for _ in 0..1_024 {
            let operations_before = executor.calls.len();
            let turn = step_cyw43_sdio_pair_restart_with(cursor, Some(now), executor);
            assert_eq!(
                executor.calls.len(),
                operations_before.saturating_add(1),
                "each nonterminal retained turn must execute exactly one operation"
            );
            match turn {
                Cyw43SdioPairRestartTurn::Pending { .. } => {
                    now = now.saturating_add(10);
                }
                Cyw43SdioPairRestartTurn::Complete { .. }
                | Cyw43SdioPairRestartTurn::Superseded { .. }
                | Cyw43SdioPairRestartTurn::Failed(_) => return turn,
            }
        }
        panic!("retained pair restart exceeded deterministic test bound");
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn pair_restart_completion_mints_only_owned_cold_epoch_provenance() {
        reset_cyw43_sdio_pair_recovery_for_test();

        let mut recovery = retained_pair_restart_test_cursor_with_provenance(
            Cyw43SdioPairRestartProvenance::Recovery,
        );
        let mut recovery_executor =
            RetainedPairRestartTestExecutor::success().with_published_epoch(1);
        assert_eq!(
            drive_retained_pair_restart_test(&mut recovery, &mut recovery_executor),
            Cyw43SdioPairRestartTurn::Complete {
                epoch: 1,
                physical_lifetime_epoch: 1,
            },
            "a pre-handoff recovery may legitimately publish pair epoch one",
        );
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
            "recovery provenance must never mint cold initial-lifetime provenance",
        );

        reset_cyw43_sdio_pair_recovery_for_test();
        CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN
            .store(CYW43_SDIO_COLD_BOOTSTRAP_CURSOR_ARMED, Ordering::Release);
        let mut cold = retained_pair_restart_test_cursor_with_provenance(
            Cyw43SdioPairRestartProvenance::ColdBootstrap,
        );
        let mut cold_executor = RetainedPairRestartTestExecutor::success().with_published_epoch(1);
        assert_eq!(
            drive_retained_pair_restart_test(&mut cold, &mut cold_executor),
            Cyw43SdioPairRestartTurn::Complete {
                epoch: 1,
                physical_lifetime_epoch: 1,
            },
        );
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            1,
        );
        assert!(begin_cyw43_sdio_pair_context_replay());
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            1,
            "the exact provenance remains live through its owned replay terminal",
        );
        finish_cyw43_sdio_pair_context_replay(true);
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
        );
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn recovery_request_during_cold_cursor_survives_and_supersedes_completion() {
        reset_cyw43_sdio_pair_recovery_for_test();
        CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.store(1, Ordering::Release);
        CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN
            .store(CYW43_SDIO_COLD_BOOTSTRAP_CURSOR_ARMED, Ordering::Release);
        let mut cursor = retained_pair_restart_test_cursor_with_provenance(
            Cyw43SdioPairRestartProvenance::ColdBootstrap,
        );
        cursor.owns_global_latch = true;
        cursor.released = false;
        let mut executor = RetainedPairRestartTestExecutor::success().with_published_epoch(1);
        assert!(matches!(
            step_cyw43_sdio_pair_restart_with(&mut cursor, Some(1), &mut executor),
            Cyw43SdioPairRestartTurn::Pending { .. }
        ));

        request_cyw43_sdio_pair_restart();
        assert_eq!(
            CYW43_SDIO_PAIR_RESTART_SUPERSEDED.load(Ordering::Acquire),
            1,
        );
        assert_eq!(CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire), 1);
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
        );

        assert_eq!(
            drive_retained_pair_restart_test(&mut cursor, &mut executor),
            Cyw43SdioPairRestartTurn::Superseded {
                epoch: 1,
                physical_lifetime_epoch: 1,
            },
        );
        assert_eq!(
            CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire),
            1,
            "completion must preserve the later recovery request",
        );
        assert_eq!(
            CYW43_SDIO_PAIR_CONTEXT_REPLAY_STATE.load(Ordering::Acquire),
            0,
        );
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
        );
        assert_eq!(
            CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire),
            0,
        );
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cold_epoch_provenance_is_revoked_by_failure_and_unfinished_drop() {
        reset_cyw43_sdio_pair_recovery_for_test();
        CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.store(1, Ordering::Release);
        CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN
            .store(CYW43_SDIO_COLD_BOOTSTRAP_CURSOR_ARMED, Ordering::Release);
        let mut failed = retained_pair_restart_test_cursor_with_provenance(
            Cyw43SdioPairRestartProvenance::ColdBootstrap,
        );
        failed.owns_global_latch = true;
        failed.released = false;
        let mut failure_executor = RetainedPairRestartTestExecutor::failure_at(0);
        assert!(matches!(
            drive_retained_pair_restart_test(&mut failed, &mut failure_executor),
            Cyw43SdioPairRestartTurn::Failed(_)
        ));
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
        );

        reset_cyw43_sdio_pair_recovery_for_test();
        CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.store(1, Ordering::Release);
        CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN
            .store(CYW43_SDIO_COLD_BOOTSTRAP_CURSOR_ARMED, Ordering::Release);
        let mut dropped = retained_pair_restart_test_cursor_with_provenance(
            Cyw43SdioPairRestartProvenance::ColdBootstrap,
        );
        dropped.owns_global_latch = true;
        dropped.released = false;
        drop(dropped);
        assert_eq!(
            CYW43_SDIO_COLD_BOOTSTRAP_EPOCH_TOKEN.load(Ordering::Acquire),
            0,
        );
        assert_eq!(CYW43_SDIO_PAIR_RESTART_PENDING.load(Ordering::Acquire), 1);
        assert_eq!(
            CYW43_SDIO_PAIR_RESTART_IN_PROGRESS.load(Ordering::Acquire),
            0,
        );
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_pair_restart_executes_one_operation_per_turn_in_canonical_order() {
        let mut cursor = retained_pair_restart_test_cursor();
        let mut executor = RetainedPairRestartTestExecutor::success();
        assert_eq!(
            drive_retained_pair_restart_test(&mut cursor, &mut executor),
            Cyw43SdioPairRestartTurn::Complete {
                epoch: 7,
                physical_lifetime_epoch: 1,
            }
        );

        let mut actions = Vec::new();
        for (action, _) in &executor.calls {
            if actions.last().copied() != Some(*action) {
                actions.push(*action);
            }
        }
        let expected: Vec<_> = CYW43_SDIO_PAIR_RESTART_ACTION_ORDER
            .iter()
            .map(|action| action.as_str())
            .collect();
        assert_eq!(actions, expected);
        let sdio_priority_path: Vec<_> = executor
            .calls
            .iter()
            .filter(|(action, _)| {
                *action == "program-sdio-restart-registers" || *action == "replay-sdio-descriptor"
            })
            .map(|(_, operation)| *operation)
            .collect();
        assert_eq!(
            sdio_priority_path,
            [
                Cyw43SdioPairRestartOperation::SetBootstrapPriority(Cyw43SdioPairMember::Sdio,),
                Cyw43SdioPairRestartOperation::ProgramRestartRegisters(Cyw43SdioPairMember::Sdio,),
                Cyw43SdioPairRestartOperation::ReplayDescriptor(Cyw43SdioPairMember::Sdio),
            ]
        );
        let cyw43_priority_path: Vec<_> = executor
            .calls
            .iter()
            .filter(|(action, _)| {
                *action == "program-cyw43-restart-registers" || *action == "replay-cyw43-descriptor"
            })
            .map(|(_, operation)| *operation)
            .collect();
        assert_eq!(
            cyw43_priority_path,
            [
                Cyw43SdioPairRestartOperation::SetBootstrapPriority(Cyw43SdioPairMember::Cyw43,),
                Cyw43SdioPairRestartOperation::ProgramRestartRegisters(Cyw43SdioPairMember::Cyw43,),
                Cyw43SdioPairRestartOperation::ReplayDescriptor(Cyw43SdioPairMember::Cyw43),
            ]
        );
        let bootstrap_priority_operations: Vec<_> = executor
            .calls
            .iter()
            .filter_map(|(_, operation)| match operation {
                Cyw43SdioPairRestartOperation::SetBootstrapPriority(member) => Some(*member),
                _ => None,
            })
            .collect();
        assert_eq!(
            bootstrap_priority_operations,
            [Cyw43SdioPairMember::Sdio, Cyw43SdioPairMember::Cyw43],
            "pair restart raises each suspended runtime once; steady cutover belongs to the later ready-generation boundary",
        );
        assert_eq!(
            executor
                .calls
                .iter()
                .filter(|(action, _)| *action == "drain-notifications-before-irq")
                .count(),
            CYW43_SDIO_PAIR_RESTART_NOTIFICATION_DRAIN_CAP * 2
        );
        assert_eq!(
            executor
                .calls
                .iter()
                .filter(|(action, _)| *action == "drain-notifications-after-irq")
                .count(),
            CYW43_SDIO_PAIR_RESTART_NOTIFICATION_DRAIN_CAP * 2
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn pair_restart_engine_replay_requires_each_runtime_success_contract() {
        let cyw43 = DriverTaskCompletionRecord::progress(41, 1);
        let mut sdio = DriverTaskCompletionRecord::progress(42, 1);
        sdio.detail = DRIVER_RUNTIME_SDIO_INIT_DETAIL_READY;

        assert!(cyw43_sdio_restart_engine_completion_ready(
            DriverTaskHotPath::Cyw43Wifi,
            cyw43,
        ));
        assert!(cyw43_sdio_restart_engine_completion_ready(
            DriverTaskHotPath::SdioHost,
            sdio,
        ));
        assert!(!cyw43_sdio_restart_engine_completion_ready(
            DriverTaskHotPath::SdioHost,
            cyw43,
        ));
        assert!(!cyw43_sdio_restart_engine_completion_ready(
            DriverTaskHotPath::Cyw43Wifi,
            sdio,
        ));

        let mut wrong_code = sdio;
        wrong_code.code = DriverTaskCompletionCode::Fault.as_u16();
        let mut wrong_result = sdio;
        wrong_result.result = 0;
        let mut framed = sdio;
        framed.frame.len = 1;
        let mut wrong_detail = sdio;
        wrong_detail.detail = DriverTaskFaultCode::None.as_u16();
        for malformed in [wrong_code, wrong_result, framed, wrong_detail] {
            assert!(!cyw43_sdio_restart_engine_completion_ready(
                DriverTaskHotPath::SdioHost,
                malformed,
            ));
        }
    }

    #[cfg(feature = "kernel")]
    fn assert_pair_restart_engine_failure_completion_survives_fence(
        member: Cyw43SdioPairMember,
        expected_action: &'static str,
        completion: DriverTaskCompletionRecord,
    ) {
        let mut cursor = retained_pair_restart_test_cursor();
        let mut executor = RetainedPairRestartTestExecutor::engine_failure(member, completion);
        let Cyw43SdioPairRestartTurn::Failed(failure) =
            drive_retained_pair_restart_test(&mut cursor, &mut executor)
        else {
            panic!("terminal engine completion did not fail the pair restart");
        };
        assert_eq!(
            failure.kind(),
            Cyw43SdioPairRestartFailureKind::ActionFailed
        );
        assert_eq!(failure.action(), expected_action);
        assert_eq!(failure.status(), "failed-fenced");
        assert_eq!(failure.completion(), Some(completion));
        let preserved = failure
            .completion()
            .expect("engine failure completion exists");
        assert_eq!(preserved.sequence, completion.sequence);
        assert_eq!(preserved.code, completion.code);
        assert_eq!(preserved.detail, completion.detail);
        assert_eq!(preserved.result, completion.result);
    }

