    #[cfg(feature = "kernel")]
    #[test]
    fn first_recovery_scheduler_snapshot_survives_poison_scrub_and_second_fault() {
        let _guard = PERSISTENT_OP11_DEADLINE_TEST_LOCK
            .lock()
            .expect("first recovery scheduler snapshot test lock");
        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        reset_cyw43_sdio_pair_recovery_for_test();
        test_reset_root_grant_action_counts();

        let mut first_ring = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        let first_ring_root_ptr = first_ring.0.as_mut_ptr() as usize;
        test_open_cyw43_sdio_network_priority_lease_for_current_pair();
        let outer = cyw43_sdio_network_priority_lease_snapshot();
        assert_eq!(outer.phase, Cyw43SdioNetworkPriorityLeasePhase::Open);
        let priority_mask = DRIVER_TASK_RETAINED_LEASE_PRIMARY | DRIVER_TASK_RETAINED_LEASE_BUS;
        let request = 0x4359_6401;
        let generation = 0x4359_0064;
        seed_first_recovery_scheduler_root(first_ring_root_ptr, request, generation, priority_mask);
        let send_attempts = DRIVER_TASK_SLOT_CYW43455
            .counters
            .send_attempts
            .load(Ordering::Acquire);

        request_cyw43_sdio_pair_restart();
        assert_eq!(
            cyw43_sdio_network_priority_lease_snapshot().phase,
            Cyw43SdioNetworkPriorityLeasePhase::Poisoned,
        );
        let retained = first_cyw43_recovery_scheduler_snapshot()
            .expect("the first recovery mutation must preserve its raw scheduler tuple");
        assert_eq!(
            retained.outer_phase,
            Cyw43SdioNetworkPriorityLeasePhase::Open
        );
        assert_eq!(retained.outer_pair_epoch, outer.pair_epoch);
        assert_eq!(retained.outer_priority_mask, outer.mask);
        assert!(retained.root_active);
        assert_eq!(retained.root_phase_name, "issued");
        assert_eq!(retained.root_priority_mask, priority_mask);
        assert_eq!(retained.root_request, request);
        assert_eq!(retained.root_generation, generation);
        assert_eq!(retained.root_command_sequence, request);
        assert_eq!(
            retained.root_command_flags,
            DRIVER_TASK_RING_FLAG_ONE_WAY | DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION
        );
        assert_eq!(retained.root_command_aux0, DRIVER_RUNTIME_CYW43_COMMAND_AUX);
        assert!(retained.root_doorbell_issued);
        assert!(retained.root_signal_returned);
        assert!(!retained.root_parent_deadline_expired);
        assert!(!retained.child_terminal_observed);
        assert!(!retained.child_wait_receipt_observed);
        assert!(!retained.child_bus_episode_observed);
        assert_eq!(retained.child_bus_parent_sequence, 0);
        assert_eq!(retained.child_bus_parent_op, 0);

        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        assert_eq!(
            first_cyw43_recovery_scheduler_snapshot(),
            Some(retained),
            "transport scrub cannot replace the retained first-pre-fence tuple with idle state",
        );

        let mut second_ring = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        test_open_cyw43_sdio_network_priority_lease_for_current_pair();
        seed_first_recovery_scheduler_root(
            second_ring.0.as_mut_ptr() as usize,
            request.wrapping_add(1),
            generation.wrapping_add(1),
            0,
        );
        request_cyw43_sdio_pair_restart();
        assert_eq!(
            first_cyw43_recovery_scheduler_snapshot(),
            Some(retained),
            "a second request and poison cannot replace first-cause scheduler identity",
        );
        assert_eq!(test_root_grant_action_counts(), (0, 0));
        assert_eq!(
            DRIVER_TASK_SLOT_CYW43455
                .counters
                .send_attempts
                .load(Ordering::Acquire),
            send_attempts,
            "capture, poison, and scrub cannot publish a grant or signal a runtime",
        );

        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn first_recovery_snapshot_retains_delegated_sdio_ring_before_scrub() {
        let _guard = PERSISTENT_OP11_DEADLINE_TEST_LOCK
            .lock()
            .expect("delegated SDIO recovery snapshot test lock");
        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        reset_cyw43_sdio_pair_recovery_for_test();

        let mut cyw43_ring = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        let mut sdio_ring = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        let cyw43_request = 0x4359_6601;
        seed_first_recovery_scheduler_root(
            cyw43_ring.0.as_mut_ptr() as usize,
            cyw43_request,
            0x4359_0066,
            DRIVER_TASK_RETAINED_LEASE_PRIMARY | DRIVER_TASK_RETAINED_LEASE_BUS,
        );

        let sdio_ring_root_ptr = sdio_ring.0.as_mut_ptr() as usize;
        publish_driver_task_ring(SDIO_HOST_DRIVER_TASK_CONTRACT, sdio_ring_root_ptr);
        let owner_guard = test_delegate_cyw43_sdio_dpc_owner();
        let mut command = DriverTaskCommandRecord::service(
            0xeff0_90d9,
            DriverTaskBudgetGrant::from_contract(SDIO_HOST_DRIVER_TASK_CONTRACT),
        );
        command.flags = DRIVER_TASK_RING_FLAG_ONE_WAY;
        command.aux0 = DRIVER_RUNTIME_CYW43_COMMAND_AUX;
        command.aux1 = 0x4359_0001;
        let fault_frame_offset = DRIVER_TASK_RING_FRAME_OFFSET + 64;
        let fault_result = 0x0600_0000;
        let completion = DriverTaskCompletionRecord {
            sequence: 5,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: 0x5104,
            result: fault_result,
            frame: DriverFrameDescriptor {
                offset: fault_frame_offset as u32,
                len: pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_BYTES,
                flags: pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_FRAME_FLAG_CONTAINED,
            },
        };
        let fault_words = &mut sdio_ring.0[fault_frame_offset / 4
            ..fault_frame_offset / 4 + pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_WORDS];
        fault_words[0] = pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_MAGIC;
        fault_words[1] = pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_VERSION;
        fault_words[pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_FAILURE_OFFSET / 4] =
            fault_result;
        fault_words[pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_CS_OFFSET / 4] = 0x100;
        fault_words[pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_CONBLK_OFFSET / 4] =
            0xc100_0080;
        fault_words[pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_DEBUG_OFFSET / 4] = 7;
        // SAFETY: Both records are written to their fixed ABI offsets in the
        // aligned test-owned page before the recovery snapshot reads it.
        unsafe {
            core::ptr::write_volatile(sdio_ring_root_ptr as *mut DriverTaskCommandRecord, command);
            core::ptr::write_volatile(
                (sdio_ring_root_ptr + DRIVER_TASK_RING_COMPLETION_OFFSET)
                    as *mut DriverTaskCompletionRecord,
                completion,
            );
        }

        request_cyw43_sdio_pair_restart();
        let retained = first_cyw43_recovery_scheduler_snapshot()
            .expect("the first recovery cut must retain the delegated SDIO records");
        assert!(retained.sdio_ring_observed);
        assert_eq!(retained.sdio_command_sequence, command.sequence);
        assert_eq!(retained.sdio_command_opcode, command.opcode);
        assert_eq!(retained.sdio_command_flags, command.flags);
        assert_eq!(retained.sdio_command_aux0, command.aux0);
        assert_eq!(retained.sdio_command_aux1, command.aux1);
        assert_eq!(retained.sdio_completion_sequence, completion.sequence);
        assert_eq!(retained.sdio_completion_code, completion.code);
        assert_eq!(retained.sdio_completion_detail, completion.detail);
        assert_eq!(retained.sdio_completion_result, completion.result);
        assert_eq!(
            retained.sdio_completion_frame_offset,
            completion.frame.offset
        );
        assert_eq!(retained.sdio_completion_frame_len, completion.frame.len);
        assert_eq!(retained.sdio_completion_frame_flags, completion.frame.flags);
        assert!(retained.sdio_fault_frame_observed);
        assert_eq!(
            retained.sdio_fault_words
                [pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_CS_OFFSET / 4],
            0x100,
        );
        assert_eq!(
            retained.sdio_fault_words
                [pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_CONBLK_OFFSET / 4],
            0xc100_0080,
        );
        assert_eq!(
            retained.sdio_fault_words
                [pi4_driver_abi::DRIVER_RUNTIME_SDIO_FAULT_TELEMETRY_DMA_DEBUG_OFFSET / 4],
            7,
        );

        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        assert_eq!(
            first_cyw43_recovery_scheduler_snapshot(),
            Some(retained),
            "pair scrub cannot erase the retained command/completion discriminator",
        );

        drop(owner_guard);
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn inactive_outer_restart_still_captures_issued_root_without_actions() {
        let _guard = PERSISTENT_OP11_DEADLINE_TEST_LOCK
            .lock()
            .expect("inactive outer recovery snapshot test lock");
        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        reset_cyw43_sdio_pair_recovery_for_test();
        test_reset_root_grant_action_counts();

        let mut ring = Box::new(AlignedDriverTaskRing(
            [0u32; DRIVER_TASK_RING_PAGE_BYTES / core::mem::size_of::<u32>()],
        ));
        assert_eq!(
            cyw43_sdio_network_priority_lease_snapshot().phase,
            Cyw43SdioNetworkPriorityLeasePhase::Inactive,
        );
        let request = 0x4359_6501;
        let generation = 0x4359_0065;
        seed_first_recovery_scheduler_root(
            ring.0.as_mut_ptr() as usize,
            request,
            generation,
            DRIVER_TASK_RETAINED_LEASE_BUS,
        );
        let send_attempts = DRIVER_TASK_SLOT_CYW43455
            .counters
            .send_attempts
            .load(Ordering::Acquire);

        request_cyw43_sdio_pair_restart();
        let retained = first_cyw43_recovery_scheduler_snapshot()
            .expect("restart intake must capture root identity even without an outer lease");
        assert_eq!(
            retained.outer_phase,
            Cyw43SdioNetworkPriorityLeasePhase::Inactive,
        );
        assert_eq!(retained.outer_priority_mask, 0);
        assert!(retained.root_active);
        assert_eq!(retained.root_phase_name, "issued");
        assert_eq!(retained.root_priority_mask, DRIVER_TASK_RETAINED_LEASE_BUS);
        assert_eq!(retained.root_request, request);
        assert_eq!(retained.root_generation, generation);
        assert_eq!(retained.root_command_sequence, request);
        assert_eq!(
            retained.root_command_flags,
            DRIVER_TASK_RING_FLAG_ONE_WAY | DRIVER_RUNTIME_COMMAND_FLAG_PERSISTENT_TRANSACTION
        );
        assert_eq!(retained.root_command_aux0, DRIVER_RUNTIME_CYW43_COMMAND_AUX);
        assert!(retained.root_doorbell_issued);
        assert!(retained.root_signal_returned);
        assert!(!retained.root_parent_deadline_expired);
        assert!(!retained.child_terminal_observed);
        assert!(!retained.child_wait_receipt_observed);
        assert!(!retained.child_bus_episode_observed);
        assert_eq!(retained.child_bus_parent_sequence, 0);
        assert_eq!(retained.child_bus_parent_op, 0);
        assert_eq!(test_root_grant_action_counts(), (0, 0));
        assert_eq!(
            DRIVER_TASK_SLOT_CYW43455
                .counters
                .send_attempts
                .load(Ordering::Acquire),
            send_attempts,
        );

        clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        clear_driver_task_transport(SDIO_HOST_DRIVER_TASK_CONTRACT);
        reset_cyw43_sdio_pair_recovery_for_test();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_sdio_network_priority_lease_amortizes_scheduler_transitions() {
        let lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let cyw43 = network_priority_test_slot(160);
        let sdio = network_priority_test_slot(200);
        let generation = 17;
        let command = network_priority_test_cyw43_command(generation);
        let mut transitions = Vec::new();

        assert_eq!(
            begin_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                |contract, _, owner_token, boost| {
                    assert_eq!(owner_token, CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN);
                    transitions.push((contract.name, boost));
                    true
                },
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::Opened {
                pair_epoch: generation
            }
        );
        for _ in 0..3 {
            assert_eq!(
                cyw43_sdio_network_priority_request_coverage_with(
                    &lease,
                    &cyw43,
                    &sdio,
                    CYW43_WIFI_DRIVER_TASK_CONTRACT,
                    command,
                    true,
                    generation,
                    false,
                ),
                Cyw43SdioNetworkPriorityRequestCoverage::Covered
            );
        }
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                None,
                |contract, _, owner_token, boost| {
                    assert_eq!(owner_token, CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN);
                    transitions.push((contract.name, boost));
                    true
                },
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::Closed
        );

        assert_eq!(
            transitions,
            vec![
                (SDIO_HOST_DRIVER_TASK_CONTRACT.name, true),
                (CYW43_WIFI_DRIVER_TASK_CONTRACT.name, true),
                (CYW43_WIFI_DRIVER_TASK_CONTRACT.name, false),
                (SDIO_HOST_DRIVER_TASK_CONTRACT.name, false),
            ],
            "one Network quantum owns four scheduler writes regardless of request count"
        );
        assert_eq!(
            cyw43.retained_priority_boost_active.load(Ordering::Acquire),
            0
        );
        assert_eq!(
            sdio.retained_priority_boost_active.load(Ordering::Acquire),
            0
        );
        assert_eq!(lease.opens.load(Ordering::Acquire), 1);
        assert_eq!(lease.closes.load(Ordering::Acquire), 1);
        assert_eq!(lease.restores.load(Ordering::Acquire), 1);
        assert_eq!(lease.amortized_requests.load(Ordering::Acquire), 3);
        assert_eq!(
            Cyw43SdioNetworkPriorityLeasePhase::from_u32(lease.phase.load(Ordering::Acquire)),
            Some(Cyw43SdioNetworkPriorityLeasePhase::Inactive)
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_sdio_network_priority_lease_closing_drains_exact_parent_and_blocks_fresh_pair_work() {
        let lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let cyw43 = network_priority_test_slot(160);
        let sdio = network_priority_test_slot(200);
        let generation = 23;
        let mut transitions = Vec::new();
        assert_eq!(
            begin_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                |contract, _, _, boost| {
                    transitions.push((contract.name, boost));
                    true
                },
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::Opened {
                pair_epoch: generation
            }
        );
        let command = network_priority_test_cyw43_command(generation);
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                Some(DriverTaskRetainedRequestState::Prepared {
                    request: 31,
                    command,
                }),
                |_, _, _, _| panic!("a retained parent must drain before restore"),
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::DrainRequired {
                request: 31,
                issued: false,
            }
        );
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                Some(DriverTaskRetainedRequestState::Issued {
                    request: 31,
                    command,
                }),
                |_, _, _, _| panic!("an exact issued parent must drain before restore"),
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::DrainRequired {
                request: 31,
                issued: true,
            }
        );
        assert_eq!(
            Cyw43SdioNetworkPriorityLeasePhase::from_u32(lease.phase.load(Ordering::Acquire)),
            Some(Cyw43SdioNetworkPriorityLeasePhase::Closing)
        );
        assert_eq!(lease.failures.load(Ordering::Acquire), 0);
        assert_eq!(lease.amortized_requests.load(Ordering::Acquire), 0);
        assert_eq!(
            cyw43_sdio_network_priority_request_coverage_with(
                &lease,
                &cyw43,
                &sdio,
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                command,
                true,
                generation,
                false,
            ),
            Cyw43SdioNetworkPriorityRequestCoverage::FailClosed,
            "Closing is an admission fence, not a fresh request lease"
        );
        assert_eq!(
            cyw43_sdio_network_priority_request_coverage_with(
                &lease,
                &cyw43,
                &sdio,
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                command,
                true,
                generation,
                true,
            ),
            Cyw43SdioNetworkPriorityRequestCoverage::Covered,
            "only the fingerprint-matched parent resume may borrow a Closing lease"
        );
        assert_eq!(
            cyw43_sdio_network_priority_request_coverage_with(
                &lease,
                &cyw43,
                &sdio,
                GENET_DRIVER_TASK_CONTRACT,
                DriverTaskCommandRecord::service(
                    0,
                    DriverTaskBudgetGrant::from_contract(GENET_DRIVER_TASK_CONTRACT),
                ),
                true,
                generation,
                false,
            ),
            Cyw43SdioNetworkPriorityRequestCoverage::NotApplicable,
            "GENET must remain outside CYW43/SDIO priority-lease state"
        );
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                generation,
                None,
                |contract, _, _, boost| {
                    transitions.push((contract.name, boost));
                    true
                },
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::Closed
        );
        assert_eq!(transitions.len(), 4);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_sdio_network_priority_lease_partial_failure_is_rolled_back_or_poisoned() {
        let clean_lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let clean_cyw43 = network_priority_test_slot(160);
        let clean_sdio = network_priority_test_slot(200);
        let mut clean_transitions = Vec::new();
        assert_eq!(
            begin_cyw43_sdio_network_priority_lease_with(
                &clean_lease,
                &clean_cyw43,
                &clean_sdio,
                29,
                |contract, _, _, boost| {
                    clean_transitions.push((contract.name, boost));
                    !(contract == CYW43_WIFI_DRIVER_TASK_CONTRACT && boost)
                },
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::RecoveryRequired
        );
        assert_eq!(
            clean_transitions,
            vec![
                (SDIO_HOST_DRIVER_TASK_CONTRACT.name, true),
                (CYW43_WIFI_DRIVER_TASK_CONTRACT.name, true),
                (SDIO_HOST_DRIVER_TASK_CONTRACT.name, false),
            ]
        );
        assert_eq!(
            Cyw43SdioNetworkPriorityLeasePhase::from_u32(clean_lease.phase.load(Ordering::Acquire)),
            Some(Cyw43SdioNetworkPriorityLeasePhase::Inactive)
        );
        assert_eq!(
            clean_cyw43
                .retained_priority_boost_active
                .load(Ordering::Acquire),
            0
        );
        assert_eq!(
            clean_sdio
                .retained_priority_boost_active
                .load(Ordering::Acquire),
            0
        );

        let poisoned_lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let poisoned_cyw43 = network_priority_test_slot(160);
        let poisoned_sdio = network_priority_test_slot(200);
        assert_eq!(
            begin_cyw43_sdio_network_priority_lease_with(
                &poisoned_lease,
                &poisoned_cyw43,
                &poisoned_sdio,
                31,
                |contract, _, _, boost| { contract == SDIO_HOST_DRIVER_TASK_CONTRACT && boost },
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::RecoveryRequired
        );
        assert_eq!(
            Cyw43SdioNetworkPriorityLeasePhase::from_u32(
                poisoned_lease.phase.load(Ordering::Acquire)
            ),
            Some(Cyw43SdioNetworkPriorityLeasePhase::Poisoned)
        );
        assert_eq!(
            poisoned_cyw43
                .retained_priority_boost_active
                .load(Ordering::Acquire),
            CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN
        );
        assert_eq!(
            poisoned_sdio
                .retained_priority_boost_active
                .load(Ordering::Acquire),
            CYW43_SDIO_NETWORK_PRIORITY_OWNER_TOKEN
        );
        assert_eq!(
            request_cyw43_sdio_network_priority_lease_close_with(
                &poisoned_lease,
                &poisoned_cyw43,
                &poisoned_sdio,
                31,
            ),
            Cyw43SdioNetworkPriorityLeaseCloseRequest::RecoveryRequired
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_sdio_network_priority_lease_separates_pair_and_connection_epochs() {
        let lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let cyw43 = network_priority_test_slot(160);
        let sdio = network_priority_test_slot(200);
        let pair_epoch = 37;
        let connection_generation = 83;
        let command = network_priority_test_cyw43_command(connection_generation);
        assert_eq!(
            begin_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                pair_epoch,
                |_, _, _, _| true,
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::Opened { pair_epoch }
        );
        assert_eq!(
            cyw43_sdio_network_priority_request_coverage_with(
                &lease,
                &cyw43,
                &sdio,
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                command,
                true,
                pair_epoch,
                false,
            ),
            Cyw43SdioNetworkPriorityRequestCoverage::Covered,
            "the pair lease must not alias command.aux1's connection generation"
        );
        assert_eq!(
            cyw43_sdio_network_priority_request_coverage_with(
                &lease,
                &cyw43,
                &sdio,
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                command,
                true,
                pair_epoch.wrapping_add(1),
                false,
            ),
            Cyw43SdioNetworkPriorityRequestCoverage::FailClosed,
            "a different pair epoch remains outside the scheduling lease"
        );
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                pair_epoch,
                Some(DriverTaskRetainedRequestState::Prepared {
                    request: 41,
                    command,
                }),
                |_, _, _, _| panic!("the exact parent must drain before restore"),
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::DrainRequired {
                request: 41,
                issued: false,
            }
        );
        assert_eq!(
            finish_or_drain_cyw43_sdio_network_priority_lease_with(
                &lease,
                &cyw43,
                &sdio,
                pair_epoch,
                None,
                |_, _, _, _| true,
            ),
            Cyw43SdioNetworkPriorityLeaseFinish::Closed
        );

        let stale_pair_lease = Cyw43SdioNetworkPriorityLeaseState::new();
        let stale_pair_cyw43 = network_priority_test_slot(160);
        let stale_pair_sdio = network_priority_test_slot(200);
        assert!(matches!(
            begin_cyw43_sdio_network_priority_lease_with(
                &stale_pair_lease,
                &stale_pair_cyw43,
                &stale_pair_sdio,
                pair_epoch,
                |_, _, _, _| true,
                || true,
            ),
            Cyw43SdioNetworkPriorityLeaseBegin::Opened { .. }
        ));
        assert_eq!(
            request_cyw43_sdio_network_priority_lease_close_with(
                &stale_pair_lease,
                &stale_pair_cyw43,
                &stale_pair_sdio,
                pair_epoch.wrapping_add(1),
            ),
            Cyw43SdioNetworkPriorityLeaseCloseRequest::RecoveryRequired
        );
        assert_eq!(
            Cyw43SdioNetworkPriorityLeasePhase::from_u32(
                stale_pair_lease.phase.load(Ordering::Acquire)
            ),
            Some(Cyw43SdioNetworkPriorityLeasePhase::Poisoned)
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_one_way_turn_keeps_a_demoted_pi_runtime_schedulable() {
        assert!(retained_priority_boost_required(true, true, 160));
        assert!(retained_priority_boost_required(true, true, 200));
        assert!(!retained_priority_boost_required(false, true, 160));
        assert!(!retained_priority_boost_required(true, false, 160));
        assert!(!retained_priority_boost_required(true, true, 0));
        assert!(!retained_priority_boost_required(true, true, 255));

        let mask = DRIVER_TASK_RETAINED_LEASE_BUS | DRIVER_TASK_RETAINED_LEASE_PRIMARY;
        let mut phase = DriverTaskRetainedLeasePhase::BoostBus;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostBus
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::BoostPrimary
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::CommitRing
        );
        phase = DriverTaskRetainedLeasePhase::Committed;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::NotifyRing
        );
        phase = DriverTaskRetainedLeasePhase::Issued;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::PollRing
        );

        phase = DriverTaskRetainedLeasePhase::RestorePrimary;
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::RestorePrimary
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::RestoreBus
        );
        phase = phase.after_success(mask);
        assert_eq!(
            phase.operation(),
            DriverTaskRetainedLeaseOperation::Complete
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn deferred_steady_priority_cutover_is_claimed_exactly_once() {
        let slot = DriverTaskCommandSlot::new();
        assert_eq!(
            DriverTaskSteadyPriorityState::from_usize(
                slot.steady_priority_state.load(Ordering::Acquire),
            ),
            Some(DriverTaskSteadyPriorityState::Bootstrap),
        );
        assert!(claim_driver_task_steady_priority_cutover(&slot));
        assert!(!claim_driver_task_steady_priority_cutover(&slot));
        assert!(resolve_driver_task_steady_priority_cutover(&slot, true));
        assert!(driver_task_steady_priority_is_active(&slot));
        assert!(!claim_driver_task_steady_priority_cutover(&slot));
        assert!(!resolve_driver_task_steady_priority_cutover(&slot, true));
    }

