    #[cfg(feature = "kernel")]
    #[test]
    fn usb_keyboard_poll_uses_prompt_window_without_timeout_spam() {
        let mut command = DriverTaskCommandRecord::pi4_hot_path(
            0,
            DriverTaskHotPath::UsbKeyboard,
            DriverTaskBudgetGrant::from_contract(USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT),
            DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        );

        assert_eq!(
            driver_task_ring_attempt_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking
            ),
            DRIVER_TASK_USB_PROMPT_POLL_RING_ATTEMPTS
        );
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking
            ),
            0
        );
        assert!(!driver_task_ring_call_trace_enabled(
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            DriverTaskRingCommandMode::NonBlocking
        ));

        let slot = DriverTaskCommandSlot::new();
        let request = 17;
        record_driver_task_ring_progress(
            &slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_USB,
                aux0: command.aux0,
            },
        );
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit_for_progress(
                &slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking,
                request,
            ),
            0
        );
        slot.timeout_resumes.store(7, Ordering::Release);
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking,
                request,
                false,
            ),
            (false, 0)
        );
        assert_eq!(slot.timeout_resumes.load(Ordering::Acquire), 7);

        command.aux0 = DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX;
        assert_eq!(
            driver_task_ring_attempt_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking
            ),
            DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS
        );
        assert_eq!(
            driver_task_ring_attempt_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::PromptSlice
            ),
            DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS
        );
        assert_eq!(
            DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS,
            DRIVER_TASK_USB_PROMPT_ENUM_RING_ATTEMPTS
        );
        assert!(
            DRIVER_TASK_USB_PROMPT_RECOVERY_RING_ATTEMPTS
                > DRIVER_TASK_USB_PROMPT_POLL_RING_ATTEMPTS
        );
        assert!(driver_task_ring_timeout_keeps_active(
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            DriverTaskRingCommandMode::NonBlocking
        ));
        assert!(driver_task_ring_timeout_keeps_active(
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            DriverTaskRingCommandMode::PromptSlice
        ));
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::NonBlocking
            ),
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        assert_eq!(
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT,
            DRIVER_TASK_USB_ENUM_STATUS_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        assert!(
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
                > DRIVER_TASK_USB_ENUM_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        let recovery_slot = DriverTaskCommandSlot::new();
        let recovery_request = 41;
        record_driver_task_ring_progress(
            &recovery_slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: recovery_request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_USB,
                aux0: command.aux0,
            },
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &recovery_slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                recovery_request,
                true,
            ),
            (true, 0)
        );
        recovery_slot.timeout_resumes.store(
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT - 1,
            Ordering::Release,
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &recovery_slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                recovery_request,
                false,
            ),
            (false, DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT)
        );
        record_driver_task_ring_progress(
            &recovery_slot,
            DriverTaskRingProgressRecord {
                magic: DRIVER_RUNTIME_RING_PROGRESS_MAGIC,
                sequence: recovery_request,
                phase: DRIVER_RUNTIME_RING_PROGRESS_USB_HID_INTERRUPT_QUEUE_BEGIN,
                aux0: command.aux0,
            },
        );
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit_for_progress(
                &recovery_slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                recovery_request,
            ),
            DRIVER_TASK_USB_HID_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
        );
        recovery_slot.timeout_resumes.store(
            DRIVER_TASK_USB_HID_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT - 1,
            Ordering::Release,
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &recovery_slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::PromptSlice,
                recovery_request,
                false,
            ),
            (
                false,
                DRIVER_TASK_USB_HID_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT
            )
        );
        assert!(!driver_task_ring_call_trace_enabled(
            USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
            command,
            DriverTaskRingCommandMode::NonBlocking
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_usb_keyboard_poll_fails_closed_at_its_protocol_bound() {
        let mut command = DriverTaskCommandRecord::pi4_hot_path(
            0,
            DriverTaskHotPath::UsbKeyboard,
            DriverTaskBudgetGrant::from_contract(USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT),
            DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        );
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::RetainedTurn,
            ),
            DRIVER_TASK_USB_STEADY_POLL_TIMEOUT_KEEP_ACTIVE_LIMIT,
        );

        let slot = DriverTaskCommandSlot::new();
        slot.timeout_resumes.store(
            DRIVER_TASK_USB_STEADY_POLL_TIMEOUT_KEEP_ACTIVE_LIMIT - 1,
            Ordering::Release,
        );
        assert_eq!(
            driver_task_ring_timeout_keep_decision(
                &slot,
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::RetainedTurn,
                23,
                false,
            ),
            (false, DRIVER_TASK_USB_STEADY_POLL_TIMEOUT_KEEP_ACTIVE_LIMIT,),
            "a retained USB poll without a terminal completion cannot live forever",
        );

        command.aux0 = DRIVER_RUNTIME_USB_ENUMERATE_AUX;
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::RetainedTurn,
            ),
            DRIVER_TASK_RETAINED_OWNER_TERMINAL_KEEP_ACTIVE_LIMIT,
            "enumeration must retain its exact owner command across normal MCS replenishment",
        );
        command.aux0 = DRIVER_RUNTIME_USB_KEYBOARD_RECOVERY_AUX;
        assert_eq!(
            driver_task_ring_timeout_keep_active_limit(
                USB_LOCAL_SEAT_DRIVER_TASK_CONTRACT,
                command,
                DriverTaskRingCommandMode::RetainedTurn,
            ),
            DRIVER_TASK_USB_RECOVERY_TIMEOUT_KEEP_ACTIVE_LIMIT,
        );
    }

