    #[cfg(feature = "kernel")]
    #[test]
    fn repeated_log_gate_keeps_first_and_sparse_milestones() {
        let key_cell = AtomicUsize::new(0);
        let count_cell = AtomicUsize::new(0);

        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            Some(1)
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            Some(2)
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            Some(3)
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            Some(4)
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            None
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            None
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            None
        );
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x55),
            Some(8)
        );
        let mut emitted_16 = false;
        let mut emitted_32 = false;
        let mut emitted_64 = false;
        let mut emitted_128 = false;
        let mut emitted_192 = false;
        for _ in 9..=192 {
            if let Some(count) = driver_task_log_repeat_count(&key_cell, &count_cell, 0x55) {
                emitted_16 |= count == 16;
                emitted_32 |= count == 32;
                emitted_64 |= count == 64;
                emitted_128 |= count == 128;
                emitted_192 |= count == 192;
            }
        }
        assert!(emitted_16);
        assert!(emitted_32);
        assert!(emitted_64);
        assert!(emitted_128);
        assert!(!emitted_192);
        assert_eq!(
            driver_task_log_repeat_count(&key_cell, &count_cell, 0x66),
            Some(1)
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn no_reply_resource_key_tracks_stable_blocker_not_retry_turn() {
        let progress_3 = DriverTaskRingProgressSnapshot {
            marker_valid: true,
            sequence: 3,
            phase: DRIVER_RUNTIME_RING_PROGRESS_USB_RESET_WAIT_BEGIN,
            phase_name: "usb-reset-wait-begin",
            aux0: DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX,
        };
        let progress_4 = DriverTaskRingProgressSnapshot {
            sequence: 4,
            ..progress_3
        };

        let key_3 = driver_task_resource_log_key(
            DriverTaskHotPath::UsbKeyboard,
            "usb-engine-init",
            "no-reply",
            None,
            0,
            0,
            Some(3),
            Some(progress_3),
        );
        let key_4 = driver_task_resource_log_key(
            DriverTaskHotPath::UsbKeyboard,
            "usb-engine-init",
            "no-reply",
            None,
            0,
            0,
            Some(4),
            Some(progress_4),
        );
        assert_eq!(key_3, key_4);

        let ready_key_3 = driver_task_resource_log_key(
            DriverTaskHotPath::UsbKeyboard,
            "usb-engine-init",
            "ready",
            None,
            0,
            0,
            Some(3),
            Some(progress_3),
        );
        let ready_key_4 = driver_task_resource_log_key(
            DriverTaskHotPath::UsbKeyboard,
            "usb-engine-init",
            "ready",
            None,
            0,
            0,
            Some(4),
            Some(progress_4),
        );
        assert_ne!(ready_key_3, ready_key_4);

        let cnr_progress = DriverTaskRingProgressSnapshot {
            phase: DRIVER_RUNTIME_RING_PROGRESS_USB_CNR_WAIT_BEGIN,
            phase_name: "usb-cnr-wait-begin",
            ..progress_4
        };
        let cnr_key = driver_task_resource_log_key(
            DriverTaskHotPath::UsbKeyboard,
            "usb-engine-init",
            "no-reply",
            None,
            0,
            0,
            Some(4),
            Some(cnr_progress),
        );
        assert_ne!(key_3, cnr_key);
    }

